;=====================================================================
;
;   G H O S T   Z A P P E R S        - Amiga 500 version -
;
;   Created By Mark Stronks (Stronkie)  -  port of the C64 original
;   Programming AI : Claude
;
;   Target: Amiga 500, OCS, Kickstart/Workbench 1.3, 512K chip + 512K
;   trapdoor.  68000 assembler, Devpac/vasm Motorola syntax:
;       vasmm68k_mot -Fhunkexe -kick1hunks -nosym -o GhostZappers main.s
;
;=====================================================================

; ---------------- custom chip registers (offsets from $dff000) -------
CUSTOM		equ	$dff000
DMACONR		equ	$002
VPOSR		equ	$004
VHPOSR		equ	$006
JOY0DAT		equ	$00a
JOY1DAT		equ	$00c
ADKCONR		equ	$010
POTGOR		equ	$016
INTENAR		equ	$01c
INTREQR		equ	$01e
BLTCON0		equ	$040
BLTCON1		equ	$042
BLTAFWM		equ	$044
BLTALWM		equ	$046
BLTCPT		equ	$048
BLTBPT		equ	$04c
BLTAPT		equ	$050
BLTDPT		equ	$054
BLTSIZE		equ	$058
BLTCMOD		equ	$060
BLTBMOD		equ	$062
BLTAMOD		equ	$064
BLTDMOD		equ	$066
BLTCDAT		equ	$070
BLTBDAT		equ	$072
BLTADAT		equ	$074
COP1LC		equ	$080
COPJMP1		equ	$088
DMACON		equ	$096
INTENA		equ	$09a
INTREQ		equ	$09c
ADKCON		equ	$09e
AUD0LC		equ	$0a0
AUD0VOL		equ	$0a8
AUD1VOL		equ	$0b8
AUD2VOL		equ	$0c8
AUD2LC		equ	$0c0
AUD2LEN		equ	$0c4
AUD2PER		equ	$0c6
AUD3LC		equ	$0d0
AUD3LEN		equ	$0d4
AUD3PER		equ	$0d6
AUD3VOL		equ	$0d8
CIAA_PRA	equ	$bfe001
CIAA_SDR	equ	$bfec01
CIAA_ICR	equ	$bfed01
CIAA_CRA	equ	$bfee01

; ---------------- raw key codes ----------------
KEY_ESC		equ	$45
KEY_SPACE	equ	$40
KEY_RETURN	equ	$44
KEY_BACK	equ	$41
KEY_DEL		equ	$46
KEY_UP		equ	$4c
KEY_DOWN	equ	$4d
KEY_RIGHT	equ	$4e
KEY_LEFT	equ	$4f
KEY_A		equ	$20
KEY_D		equ	$22
KEY_S		equ	$21
KEY_W		equ	$11
KEY_T		equ	$14
KEY_P		equ	$19
KEY_Q		equ	$10
KEY_M		equ	$37
KEY_Y		equ	$15
KEY_N		equ	$36
KEY_F1		equ	$50

; ---------------- screen layout ----------------
PF1W		equ	84		; bytes per plane row (672 px)
PF1ROW		equ	PF1W*3
PF2W		equ	48		; bytes per plane row (384 px)
PF2ROW		equ	PF2W*3
LOGO_Y		equ	22

; ---------------- colours (playfield 2) ----------------
C_WHITE		equ	1
C_BLUE		equ	2		; pale cyan
C_MAGENTA	equ	3		; mid blue
C_DEEP		equ	4
C_YELLOW	equ	5
C_ORANGE	equ	5
C_GREEN		equ	6
C_DARK		equ	7

;=====================================================================
	section	code,code
;=====================================================================
Start:
	movem.l	d1-d7/a0-a6,-(sp)
	bsr	SysInit
	tst.l	d0
	bne.s	.fail
	lea	CUSTOM,a5
	bsr	InitAll
	bsr	MainMenuLoop
	bsr	SysExit
.fail:	movem.l	(sp)+,d1-d7/a0-a6
	moveq	#0,d0
	rts

InitAll:
	bsr	InitFadeTab
	bsr	InitDoubleTab
	bsr	InitWaitTab
	bsr	InitVoice
	lea	NullPtrs,a0
	moveq	#7,d0
.np:	move.l	#NullSprite,(a0)+
	dbf	d0,.np
	move.l	#LoadPal,PicPal
	bsr	InitColFont
	move.l	#PF2BufA,FrontBuf
	move.l	#PF2BufB,BackBuf
	move.l	#CopListA,CopShown
	move.l	#CopListB,CopNext
	move.w	#16,ClipTop
	move.w	#248,ClipBottom
	move.b	#$ff,LastKey
	move.w	#1,MusicOn
	move.w	#16,BgFade
	move.w	HiData+HISIZE-4,Difficulty
	cmp.w	#3,Difficulty
	blo.s	.dok
	move.w	#1,Difficulty
.dok:
	move.l	#$2f6e2b1d,d0
	add.l	FrameCount,d0
	move.w	VHPOSR(a5),d1
	swap	d1
	eor.l	d1,d0
	bne.s	.s
	moveq	#1,d0
.s:	move.l	d0,RandSeed
	move.w	#3,d0
	bsr	SetScene
	bsr	ClearBoth
	clr.w	Fade
	rts

;---------------------------------------------------------------------
; file: system.s
;---------------------------------------------------------------------
;=====================================================================
; GHOST ZAPPERS - Amiga 500 version
; system.s : hardware takeover, frame loop, copper, input, disk I/O
;=====================================================================

;---------------------------------------------------------------------
; Startup: called once from Start (a6 = execbase)
;---------------------------------------------------------------------
SysInit:
	move.l	4.w,a6
	move.l	a6,ExecBase
	sub.l	a1,a1
	jsr	-294(a6)			; FindTask(0)
	move.l	d0,a4
	tst.l	172(a4)				; pr_CLI
	bne.s	.cli
	lea	92(a4),a0			; pr_MsgPort
	jsr	-384(a6)			; WaitPort
	lea	92(a4),a0
	jsr	-372(a6)			; GetMsg
	move.l	d0,WBMsg
.cli:
	lea	GfxName,a1
	jsr	-408(a6)			; OldOpenLibrary
	move.l	d0,GfxBase
	beq	.fail
	lea	DosName,a1
	jsr	-408(a6)
	move.l	d0,DosBase
	beq	.fail
	bsr	LoadHighscores
	bsr	TakeSystem
	moveq	#0,d0
	rts
.fail:	moveq	#-1,d0
	rts

SysExit:
	bsr	ReleaseSystem
	move.l	ExecBase,a6
	move.l	DosBase,d0
	beq.s	.nodos
	move.l	d0,a1
	jsr	-414(a6)			; CloseLibrary
.nodos:	move.l	GfxBase,d0
	beq.s	.nogfx
	move.l	d0,a1
	jsr	-414(a6)
.nogfx:	move.l	WBMsg,d0
	beq.s	.nowb
	jsr	-132(a6)			; Forbid
	move.l	d0,a1
	jsr	-378(a6)			; ReplyMsg
.nowb:	rts

;---------------------------------------------------------------------
; TakeSystem: switch off the OS display / interrupts and take over
;---------------------------------------------------------------------
TakeSystem:
	movem.l	d0-d7/a0-a6,-(sp)
	move.l	GfxBase,a6
	move.l	34(a6),OldView			; gb_ActiView
	sub.l	a1,a1
	jsr	-222(a6)			; LoadView(NULL)
	jsr	-270(a6)			; WaitTOF
	jsr	-270(a6)
	move.l	ExecBase,a6
	jsr	-132(a6)			; Forbid
	lea	CUSTOM,a5
	move.w	DMACONR(a5),OldDma
	move.w	INTENAR(a5),OldInt
	move.w	ADKCONR(a5),OldAdk
	bsr	WaitVBL
	move.w	#$7fff,INTENA(a5)
	move.w	#$7fff,INTREQ(a5)
	move.w	#$7fff,INTREQ(a5)
	move.w	#$7fff,DMACON(a5)
	move.w	#$00ff,ADKCON(a5)
	move.w	#0,AUD0VOL(a5)
	move.w	#0,AUD1VOL(a5)
	move.w	#0,AUD2VOL(a5)
	move.w	#0,AUD3VOL(a5)
	; build both copper lists and start display
	bsr	BuildCopper
	move.l	CopNext,COP1LC(a5)
	move.w	d0,COPJMP1(a5)
	move.w	#$83e0,DMACON(a5)		; DMAEN|BPLEN|COPEN|BLTEN|SPREN (null sprites)
	movem.l	(sp)+,d0-d7/a0-a6
	rts

;---------------------------------------------------------------------
; ReleaseSystem: give the machine back to the OS
;---------------------------------------------------------------------
ReleaseSystem:
	movem.l	d0-d7/a0-a6,-(sp)
	lea	CUSTOM,a5
	bsr	WaitBlit
	bsr	WaitVBL
	move.w	#$7fff,DMACON(a5)
	move.w	#$7fff,INTENA(a5)
	move.w	#$7fff,INTREQ(a5)
	move.w	#0,AUD0VOL(a5)
	move.w	#0,AUD1VOL(a5)
	move.w	#0,AUD2VOL(a5)
	move.w	#0,AUD3VOL(a5)
	move.l	GfxBase,a6
	move.l	38(a6),COP1LC(a5)		; gb_copinit
	move.w	d0,COPJMP1(a5)
	move.w	OldAdk,d0
	or.w	#$8000,d0
	move.w	#$7fff,ADKCON(a5)
	move.w	d0,ADKCON(a5)
	move.w	OldDma,d0
	or.w	#$8000,d0
	move.w	d0,DMACON(a5)
	move.w	OldInt,d0
	or.w	#$c000,d0
	move.w	d0,INTENA(a5)
	move.l	OldView,a1
	jsr	-222(a6)			; LoadView(old)
	jsr	-270(a6)
	jsr	-270(a6)
	move.l	ExecBase,a6
	jsr	-138(a6)			; Permit
	movem.l	(sp)+,d0-d7/a0-a6
	rts

;---------------------------------------------------------------------
; Highscore file (uses dos.library - only while the OS is running)
;---------------------------------------------------------------------
LoadHighscores:
	movem.l	d0-d7/a0-a6,-(sp)
	lea	HiDefault,a0
	lea	HiData,a1
	move.w	#HISIZE-1,d0
.def:	move.b	(a0)+,(a1)+
	dbf	d0,.def
	move.l	DosBase,a6
	move.l	#HiName,d1
	move.l	#1005,d2			; MODE_OLDFILE
	jsr	-30(a6)				; Open
	move.l	d0,d7
	beq.s	.none
	move.l	d7,d1
	move.l	#HiBuffer,d2
	move.l	#HISIZE,d3
	jsr	-42(a6)				; Read
	move.l	d0,d6
	move.l	d7,d1
	jsr	-36(a6)				; Close
	cmp.l	#HISIZE,d6
	bne.s	.none
	cmp.l	#HIMAGIC,HiBuffer
	bne.s	.none
	lea	HiBuffer,a0
	lea	HiData,a1
	move.w	#HISIZE-1,d0
.cp:	move.b	(a0)+,(a1)+
	dbf	d0,.cp
.none:	movem.l	(sp)+,d0-d7/a0-a6
	rts

SaveHighscores:
	movem.l	d0-d7/a0-a6,-(sp)
	bsr	ReleaseSystem
	move.l	DosBase,a6
	move.l	#HiName,d1
	move.l	#1006,d2			; MODE_NEWFILE
	jsr	-30(a6)
	move.l	d0,d7
	beq.s	.fail
	move.l	d7,d1
	move.l	#HiData,d2
	move.l	#HISIZE,d3
	jsr	-48(a6)				; Write
	move.l	d7,d1
	jsr	-36(a6)				; Close
.fail:	bsr	TakeSystem
	movem.l	(sp)+,d0-d7/a0-a6
	rts

;---------------------------------------------------------------------
; Wait for the vertical blank (raster line 300)
;---------------------------------------------------------------------
WaitVBL:
	move.l	d0,-(sp)
WaitVBL_loop1:
	move.l	VPOSR(a5),d0
	and.l	#$1ff00,d0
	cmp.l	#$12c00,d0
	bne.s	WaitVBL_loop1
WaitVBL_loop2:
	move.l	VPOSR(a5),d0
	and.l	#$1ff00,d0
	cmp.l	#$12c00,d0
	beq.s	WaitVBL_loop2
WaitVBL_end:
	move.l	(sp)+,d0
	rts

WaitBlit:
	tst.w	DMACONR(a5)
WaitBlit_loop:
	btst	#6,DMACONR(a5)
	bne.s	WaitBlit_loop
WaitBlit_end:
	rts

;---------------------------------------------------------------------
; Frame: finish drawing, show the back buffer, wait VBL, run audio/input
;---------------------------------------------------------------------
Frame:
	movem.l	d0-d7/a0-a6,-(sp)
	bsr	WaitBlit
	bsr	BuildCopper
	bsr	WaitVBL
	move.l	CopNext,COP1LC(a5)
	; swap PF2 buffers and copper lists
	move.l	FrontBuf,d0
	move.l	BackBuf,FrontBuf
	move.l	d0,BackBuf
	move.l	CopNext,d0
	move.l	CopShown,CopNext
	move.l	d0,CopShown
	addq.l	#1,FrameCount
	bsr	MusicTick
	bsr	SfxTick
	bsr	ReadInput
	movem.l	(sp)+,d0-d7/a0-a6
	rts

;---------------------------------------------------------------------
; BuildCopper: write the copper list CopNext for the BackBuf
;---------------------------------------------------------------------
BuildCopper:
	movem.l	d0-d7/a0-a4/a6,-(sp)
	bsr	UpdatePalCache
	move.l	CopNext,a0
	tst.w	PicMode
	bne	BuildPicCopper
	move.l	#$008e2c81,(a0)+		; DIWSTRT
	move.l	#$00902cc1,(a0)+		; DIWSTOP
	move.l	#$00920030,(a0)+		; DDFSTRT (one extra word for scrolling)
	move.l	#$009400d0,(a0)+		; DDFSTOP
	move.l	#$010800d2,(a0)+		; BPL1MOD = 252-42
	move.l	#$010a0066,(a0)+		; BPL2MOD = 144-42
	move.l	#$01040064,(a0)+		; BPLCON2: PF2 in front, sprites in front of both
	move.l	#$01006600,(a0)+		; BPLCON0: 6 planes, dual playfield, colour
	; sprites 0-3 = the hunter (attached pairs), 4-7 = null
	lea	SprPtrs,a1
	tst.w	SprOn
	bne.s	.son
	lea	NullPtrs,a1
.son:	move.w	#$0120,d1
	moveq	#7,d2
.spr:	cmp.w	#3,d2
	bne.s	.sp1
	lea	NullPtrs,a1
.sp1:	move.l	(a1)+,d0
	move.w	d1,(a0)+
	swap	d0
	move.w	d0,(a0)+
	addq.w	#2,d1
	move.w	d1,(a0)+
	swap	d0
	move.w	d0,(a0)+
	addq.w	#2,d1
	dbf	d2,.spr
	; playfield 2 pointers (planes 2,4,6), vertical shake
	move.w	ShakeY,d0
	mulu	#PF2ROW,d0
	add.l	BackBuf,d0
	move.w	#$00e4,d1
	moveq	#2,d2
.pf2:	swap	d0
	move.w	d1,(a0)+
	move.w	d0,(a0)+
	addq.w	#2,d1
	swap	d0
	move.w	d1,(a0)+
	move.w	d0,(a0)+
	addq.w	#6,d1
	add.l	#PF2W,d0
	dbf	d2,.pf2
	; colours: PF2 9..15, sprites 17..31
	lea	PalCache,a1
	move.w	#$0190,d3
	moveq	#7,d2
.c2:	move.w	d3,(a0)+
	move.w	(a1)+,(a0)+
	addq.w	#2,d3
	dbf	d2,.c2
	lea	SprCache,a1
	move.w	#$01a2,d3
	moveq	#14,d2
.c3:	move.w	d3,(a0)+
	move.w	(a1)+,(a0)+
	addq.w	#2,d3
	dbf	d2,.c3
	move.l	#$01800000,(a0)+		; COLOR00 black for the top HUD
	; band 0 (sky): pointers + palette
	moveq	#0,d4
	move.w	ShakeX,d5
	bsr	CopBand
	moveq	#0,d7				; current band
	bsr	CopBandCols
	; per 4-line step loop: y = 16..244
	lea	SkyCache,a1
	tst.w	FlashCol
	beq.s	.nf
	lea	FlashSky,a1
	move.w	FlashCol,d0
	moveq	#57,d1
.fl:	move.w	d0,(a1)+
	dbf	d1,.fl
	lea	FlashSky,a1
.nf:	lea	WaitTab,a3
	lea	LogoCache,a2
	moveq	#16,d6
	move.w	LBox,d3				; letterbox height (multiple of 4)
.step:	move.w	(a3)+,(a0)+
	move.w	#$fffe,(a0)+
	cmp.w	#112,d6
	beq.s	.b1
	cmp.w	#152,d6
	beq.s	.b2
	cmp.w	#232,d6
	beq.s	.b3
	bra.s	.nob
.b1:	move.w	ScrollFar,d5
	moveq	#1,d7
	bra.s	.band
.b2:	move.w	ScrollNear,d5
	moveq	#2,d7
	bra.s	.band
.b3:	move.w	ScrollStreet,d5
	moveq	#3,d7
.band:	add.w	ShakeX,d5
	cmp.w	#320,d5
	blt.s	.bs
	sub.w	#320,d5
.bs:	move.w	ShakeY,d4
	add.w	d6,d4
	bsr	CopBand
	bsr	CopBandColsLB
.nob:	tst.w	d3
	beq.s	.nolb
	cmp.w	#16,d6
	bne.s	.lb0
	bsr	CopBlackCols			; top bar starts at the HUD
.lb0:	; letterbox edges
	move.w	d3,d0
	add.w	#16,d0
	cmp.w	d0,d6
	bne.s	.lb1
	bsr	CopBandCols			; top bar ends: real colours back
.lb1:	move.w	#248,d0
	sub.w	d3,d0
	cmp.w	d0,d6
	bne.s	.lb2
	bsr	CopBlackCols			; bottom bar starts
.lb2:	; COLOR00
	move.w	d3,d0
	add.w	#16,d0
	cmp.w	d0,d6
	blt.s	.black
	move.w	#248,d0
	sub.w	d3,d0
	cmp.w	d0,d6
	bge.s	.black
.nolb:	move.w	#$0180,(a0)+
	move.w	(a1)+,(a0)+
	bra.s	.logo
.black:	move.l	#$01800000,(a0)+
	addq.l	#2,a1
.logo:	tst.w	LogoGrad
	beq.s	.nlg
	cmp.w	#LOGO_Y,d6
	blt.s	.nlg
	cmp.w	#LOGO_Y+LOGO_H,d6
	bge.s	.nlg
	move.w	d6,d0
	sub.w	#LOGO_Y,d0
	lsr.w	#1,d0
	and.w	#$fffe,d0
	move.w	#$019c,(a0)+
	move.w	(a2,d0.w),(a0)+
.nlg:	addq.w	#4,d6
	cmp.w	#248,d6
	bne	.step
	move.w	(a3)+,(a0)+			; wait for y = 248
	move.w	#$fffe,(a0)+
	move.l	#$01800000,(a0)+		; black bottom HUD
	move.w	#$019c,(a0)+			; restore colour 14
	move.w	PalCache+12,(a0)+
	move.l	#$fffffffe,(a0)+
	movem.l	(sp)+,d0-d7/a0-a4/a6
	rts

; CopBandCols: PF1 colours 1..7 of band d7 ; CopBandColsLB: black when the
; band starts inside a letterbox bar ; CopBlackCols: all black
CopBandColsLB:
	tst.w	d3
	beq.s	CopBandCols
	move.w	d3,d0
	add.w	#16,d0
	cmp.w	d0,d6
	blt.s	CopBlackCols
	move.w	#248,d0
	sub.w	d3,d0
	cmp.w	d0,d6
	bge.s	CopBlackCols
CopBandCols:
	movem.l	d0-d2/a4,-(sp)
	lea	BandCache,a4
	move.w	d7,d0
	lsl.w	#4,d0
	add.w	d0,a4
	move.w	#$0182,d1
	moveq	#6,d2
.c:	move.w	d1,(a0)+
	move.w	(a4)+,(a0)+
	addq.w	#2,d1
	dbf	d2,.c
	movem.l	(sp)+,d0-d2/a4
	rts
CopBlackCols:
	movem.l	d1-d2,-(sp)
	move.w	#$0182,d1
	moveq	#6,d2
.c:	move.w	d1,(a0)+
	clr.w	(a0)+
	addq.w	#2,d1
	dbf	d2,.c
	movem.l	(sp)+,d1-d2
	rts

; picture mode: 5 planes, 32 colours, interleaved picture in PF1Buf
BuildPicCopper:
	move.l	#$008e2c81,(a0)+
	move.l	#$00902cc1,(a0)+
	move.l	#$00920038,(a0)+
	move.l	#$009400d0,(a0)+
	move.l	#$010800a0,(a0)+		; modulo 160 (5 planes x 40 bytes)
	move.l	#$010a00a0,(a0)+
	move.l	#$01040000,(a0)+
	move.l	#$01020000,(a0)+
	move.l	#$01005200,(a0)+
	move.l	#NullSprite,d0
	move.w	#$0120,d1
	moveq	#7,d2
.spr:	move.w	d1,(a0)+
	swap	d0
	move.w	d0,(a0)+
	addq.w	#2,d1
	move.w	d1,(a0)+
	swap	d0
	move.w	d0,(a0)+
	addq.w	#2,d1
	dbf	d2,.spr
	move.l	#PF1Buf,d0
	move.w	#$00e0,d1
	moveq	#4,d2
.bp:	swap	d0
	move.w	d1,(a0)+
	move.w	d0,(a0)+
	addq.w	#2,d1
	swap	d0
	move.w	d1,(a0)+
	move.w	d0,(a0)+
	addq.w	#2,d1
	add.l	#40,d0
	dbf	d2,.bp
	lea	PicCache,a1
	move.w	#$0180,d1
	moveq	#31,d2
.c:	move.w	d1,(a0)+
	move.w	(a1)+,(a0)+
	addq.w	#2,d1
	dbf	d2,.c
	tst.w	PicBlink
	beq.s	.nb
	move.w	#$01be,(a0)+			; colour 31 = colour 30 (text hidden)
	move.w	PicCache+60,(a0)+
.nb:	move.l	#$fffffffe,(a0)+
	movem.l	(sp)+,d0-d7/a0-a4/a6
	rts

; InitWaitTab: WAIT words for y = 16,20,...,248 (line-1, h=$df)
InitWaitTab:
	lea	WaitTab,a0
	moveq	#16,d0
.l:	move.w	d0,d1
	add.w	#$2c-1,d1
	lsl.w	#8,d1
	or.w	#$df,d1
	move.w	d1,(a0)+
	addq.w	#4,d0
	cmp.w	#252,d0
	bne.s	.l
	rts

; UpdatePalCache: refresh faded colours when fade / scene / fog changed
UpdatePalCache:
	move.w	Fade,d0
	swap	d0
	move.w	BgFade,d0
	cmp.l	PalKey,d0
	bne.s	.go
	move.l	ScenePal,d1
	cmp.l	PalKeyScene,d1
	bne.s	.go
	move.w	SkyFog,d1
	cmp.w	PalKeyFog,d1
	bne.s	.go
	rts
.go:	move.l	d0,PalKey
	move.l	ScenePal,PalKeyScene
	move.w	SkyFog,PalKeyFog
	lea	FadeTab,a3
	move.w	Fade,d0
	lsl.w	#4,d0
	add.w	d0,a3
	move.l	a3,a4				; full fade (objects, sprites, logo, picture)
	lea	PalCache,a0
	lea	PF2Pal,a1
	moveq	#7,d2
	bsr	FadeList
	lea	SprCache,a0
	lea	SprPal,a1
	moveq	#14,d2
	bsr	FadeList
	lea	LogoCache,a0
	lea	LogoColours,a1
	moveq	#31,d2
	bsr	FadeList
	lea	PicCache,a0
	move.l	PicPal,a1
	moveq	#31,d2
	bsr	FadeList
	; background fade level (can be brighter than 16 for lightning)
	lea	FadeTab,a3
	move.w	Fade,d0
	cmp.w	BgFade,d0
	ble.s	.bgf
	move.w	BgFade,d0
.bgf:	cmp.w	#16,d0
	blt.s	.bgf2
	move.w	BgFade,d0			; brighter only when fully faded in
.bgf2:	lsl.w	#4,d0
	add.w	d0,a3
	move.l	ScenePal,a1
	lea	BandCache,a0
	moveq	#3,d3
.bands:	moveq	#7,d2
	bsr	FadeList
	dbf	d3,.bands
	lea	SkyCache,a0
	moveq	#57,d2
.s:	move.w	(a1)+,d0
	tst.w	SkyFog
	beq.s	.nofog
	bsr	FogCol
.nofog:	bsr	FadeCol
	move.w	d0,(a0)+
	dbf	d2,.s
	rts

; FadeList: d2+1 colours from a1 -> a0 through fade table a3
FadeList:
.l:	move.w	(a1)+,d0
	bsr	FadeCol
	move.w	d0,(a0)+
	dbf	d2,.l
	rts

; FogCol: blend d0 towards the fog colour $678 by SkyFog/16
FogCol:
	movem.l	d1-d5,-(sp)
	moveq	#0,d5
	moveq	#2,d4				; components: shift 8,4,0
	moveq	#8,d3
.c:	move.w	d0,d1
	lsr.w	d3,d1
	and.w	#15,d1
	lea	FogTarget,a6
	move.w	d4,d2
	add.w	d2,d2
	move.w	(a6,d2.w),d2			; target component
	sub.w	d1,d2
	muls	SkyFog,d2
	asr.w	#4,d2
	add.w	d2,d1
	lsl.w	d3,d1
	or.w	d1,d5
	subq.w	#4,d3
	subq.w	#1,d4
	bpl.s	.c
	move.w	d5,d0
	movem.l	(sp)+,d1-d5
	rts
FogTarget:	dc.w	8,7,6		; blue, green, red components of the fog colour

; CopBand: d4 = first row, d5 = scroll position 0..319 -> PF1 pointers + BPLCON1
CopBand:
	move.l	d7,-(sp)
	move.w	d5,d0
	add.w	#15,d0
	lsr.w	#4,d0				; P = (s+15)>>4
	move.w	d0,d1
	lsl.w	#4,d1
	sub.w	d5,d1				; delay = P*16-s
	add.w	d0,d0
	ext.l	d0
	move.w	d4,d7
	mulu	#PF1ROW,d7
	add.l	d7,d0
	add.l	#PF1Buf,d0
	move.w	#$00e0,d7
	moveq	#2,d2
.bp:	swap	d0
	move.w	d7,(a0)+
	move.w	d0,(a0)+
	addq.w	#2,d7
	swap	d0
	move.w	d7,(a0)+
	move.w	d0,(a0)+
	addq.w	#6,d7
	add.l	#PF1W,d0
	dbf	d2,.bp
	move.w	ShakeX,d0			; playfield 2 shakes too
	and.w	#3,d0
	lsl.w	#4,d0
	or.w	d0,d1
	move.w	#$0102,(a0)+
	move.w	d1,(a0)+
	move.l	(sp)+,d7
	rts

; FadeCol: d0 = $0RGB -> faded via a3 (FadeTab row)
FadeCol:
	movem.l	d1-d2,-(sp)
	move.w	d0,d1
	and.w	#$f,d1
	move.b	(a3,d1.w),d2			; blue
	move.w	d0,d1
	lsr.w	#4,d1
	and.w	#$f,d1
	move.b	(a3,d1.w),d1
	lsl.w	#4,d1
	or.b	d1,d2
	lsr.w	#8,d0
	and.w	#$f,d0
	move.b	(a3,d0.w),d0
	lsl.w	#8,d0
	and.w	#$00ff,d2
	or.w	d2,d0
	movem.l	(sp)+,d1-d2
	rts

InitFadeTab:
	lea	FadeTab,a0
	moveq	#0,d1				; level 0..24 (17..24 = brighter, to white)
.lv:	moveq	#0,d2				; component
.cp:	cmp.w	#16,d1
	bgt.s	.br
	move.w	d2,d0
	mulu	d1,d0
	lsr.w	#4,d0
	bra.s	.st
.br:	moveq	#15,d0
	sub.w	d2,d0
	move.w	d1,d3
	sub.w	#16,d3
	mulu	d3,d0
	lsr.w	#3,d0
	add.w	d2,d0
	cmp.w	#15,d0
	ble.s	.st
	moveq	#15,d0
.st:	move.b	d0,(a0)+
	addq.w	#1,d2
	cmp.w	#16,d2
	bne.s	.cp
	addq.w	#1,d1
	cmp.w	#25,d1
	bne.s	.lv
	rts

;---------------------------------------------------------------------
; Scenes: unpack background into PF1 and select palette
; d0 = scene (0 harlem,1 manhattan,2 harbor,3 jfk,4 statue,5 map,6 flight)
;---------------------------------------------------------------------
SetScene:
	movem.l	d0-d2/a0-a1,-(sp)
	move.w	d0,Scene
	clr.w	PicMode
	move.w	d0,d1
	mulu	#SCENESIZE,d1
	lea	PalTable,a0
	add.l	d1,a0
	move.l	a0,ScenePal
	lsl.w	#2,d0
	lea	BgTable,a0
	move.l	(a0,d0.w),a0
	lea	PF1Buf,a1
	bsr	UnpackBits
	clr.w	ScrollPos
	clr.w	ScrollFar
	clr.w	ScrollNear
	clr.w	ScrollStreet
	movem.l	(sp)+,d0-d2/a0-a1
	rts

; PackBits decoder a0 = src, a1 = dest
UnpackBits:
	moveq	#0,d0
.next:	move.b	(a0)+,d0
	cmp.b	#128,d0
	beq.s	.done
	bhi.s	.run
.lit:	move.b	(a0)+,(a1)+
	dbf	d0,.lit
	moveq	#0,d0
	bra.s	.next
.run:	neg.b	d0				; 257-n = -n+1 -> dbf count = -n
	move.b	(a0)+,d1
.rl:	move.b	d1,(a1)+
	dbf	d0,.rl
	moveq	#0,d0
	bra.s	.next
.done:	rts

; Scroll the city by d0 pixels (parallax: far 1/4, near 1/2, street 1/1)
; uses ScrollPos (fixed 4.4)
ScrollCity:
	movem.l	d0-d1,-(sp)
	add.w	ScrollPos,d0
	cmp.w	#320*4,d0
	blt.s	.ok
	sub.w	#320*4,d0
.ok:	move.w	d0,ScrollPos
	move.w	d0,d1
	lsr.w	#2,d1				; street: pos/4  (pos is in 1/4 px)
	move.w	d1,ScrollStreet
	move.w	d0,d1
	lsr.w	#3,d1				; near: half speed
	move.w	d1,ScrollNear
	lsr.w	#4,d0				; far: quarter speed
	move.w	d0,ScrollFar
	movem.l	(sp)+,d0-d1
	rts

;---------------------------------------------------------------------
; Fades
;---------------------------------------------------------------------
FadeOut:
	move.l	d0,-(sp)
.l:	tst.w	Fade
	beq.s	.d
	subq.w	#1,Fade
	bsr	Frame
	bra.s	.l
.d:	bsr	Frame
	move.l	(sp)+,d0
	rts
FadeIn:
	move.l	d0,-(sp)
.l:	cmp.w	#16,Fade
	beq.s	.d
	addq.w	#1,Fade
	bsr	Frame
	bra.s	.l
.d:	move.l	(sp)+,d0
	rts

;---------------------------------------------------------------------
; Input: joystick port 2 + keyboard -> Joy (bits) and JoyNew (edges)
;---------------------------------------------------------------------
J_LEFT	equ	0
J_RIGHT	equ	1
J_UP	equ	2
J_DOWN	equ	3
J_FIRE	equ	4

ReadInput:
	movem.l	d0-d3/a0,-(sp)
	bsr	ReadKeyboard
	moveq	#0,d1
	move.w	JOY1DAT(a5),d0
	btst	#1,d0
	beq.s	.nr
	bset	#J_RIGHT,d1
.nr:	btst	#9,d0
	beq.s	.nl
	bset	#J_LEFT,d1
.nl:	move.w	d0,d2
	lsr.w	#1,d2
	eor.w	d0,d2
	btst	#8,d2
	beq.s	.nu
	bset	#J_UP,d1
.nu:	btst	#0,d2
	beq.s	.nd
	bset	#J_DOWN,d1
.nd:	btst	#7,CIAA_PRA
	bne.s	.nf
	bset	#J_FIRE,d1
.nf:	lea	KeyMap,a0
	tst.b	KEY_A(a0)
	bne.s	.kl
	tst.b	KEY_LEFT(a0)
	beq.s	.nkl
.kl:	bset	#J_LEFT,d1
.nkl:	tst.b	KEY_D(a0)
	bne.s	.kr
	tst.b	KEY_RIGHT(a0)
	beq.s	.nkr
.kr:	bset	#J_RIGHT,d1
.nkr:	tst.b	KEY_T(a0)
	bne.s	.ku
	tst.b	KEY_UP(a0)
	bne.s	.ku
	tst.b	KEY_W(a0)
	beq.s	.nku
.ku:	bset	#J_UP,d1
.nku:	tst.b	KEY_DOWN(a0)
	bne.s	.kd
	tst.b	KEY_S(a0)
	beq.s	.nkd
.kd:	bset	#J_DOWN,d1
.nkd:	tst.b	KEY_SPACE(a0)
	beq.s	.nks
	bset	#J_FIRE,d1
.nks:	tst.b	KEY_RETURN(a0)
	beq.s	.nkt
	bset	#J_FIRE,d1
.nkt:	move.w	Joy,d0
	move.w	d1,Joy
	not.w	d0
	and.w	d1,d0
	move.w	d0,JoyNew
	movem.l	(sp)+,d0-d3/a0
	rts

; Keyboard: polled CIA-A serial port with manual handshake
ReadKeyboard:
	movem.l	d0-d1/a0,-(sp)
	move.b	CIAA_ICR,d0
	btst	#3,d0
	beq.s	.none
	move.b	CIAA_SDR,d0
	bset	#6,CIAA_CRA			; handshake (SP output low)
	move.b	VHPOSR(a5),d1
.w1:	cmp.b	VHPOSR(a5),d1
	beq.s	.w1
	move.b	VHPOSR(a5),d1
.w2:	cmp.b	VHPOSR(a5),d1
	beq.s	.w2
	move.b	VHPOSR(a5),d1
.w3:	cmp.b	VHPOSR(a5),d1
	beq.s	.w3
	bclr	#6,CIAA_CRA
	not.b	d0
	ror.b	#1,d0
	moveq	#0,d1
	move.b	d0,d1
	and.w	#$7f,d1
	lea	KeyMap,a0
	tst.b	d0
	bmi.s	.up
	st	(a0,d1.w)
	move.b	d1,LastKey
	bra.s	.none
.up:	clr.b	(a0,d1.w)
.none:	movem.l	(sp)+,d0-d1/a0
	rts

; GetKey: returns raw key code of last key press in d0 (or -1) and clears it
GetKey:
	moveq	#0,d0
	move.b	LastKey,d0
	move.b	#$ff,LastKey
	cmp.b	#$ff,d0
	bne.s	.r
	moveq	#-1,d0
.r:	rts

; RawToAscii: d0 raw -> d0 ascii (0 if none)
RawToAscii:
	cmp.w	#$40,d0
	bhs.s	.z
	lea	RawAscii,a0
	move.b	(a0,d0.w),d0
	ext.w	d0
	rts
.z:	moveq	#0,d0
	rts

;---------------------------------------------------------------------
; Random number (xorshift32) -> d0
;---------------------------------------------------------------------
Random:
	move.l	d1,-(sp)
	move.l	RandSeed,d0
	move.l	d0,d1
	lsl.l	#8,d1
	lsl.l	#5,d1
	eor.l	d1,d0
	move.l	d0,d1
	swap	d1
	lsr.w	#1,d1
	and.l	#$7fff,d1
	eor.l	d1,d0
	move.l	d0,d1
	lsl.l	#5,d1
	eor.l	d1,d0
	move.l	d0,RandSeed
	move.l	(sp)+,d1
	rts

; RandRange: d0 = max (exclusive, < 32768) -> d0 = 0..max-1
RandRange:
	move.l	d1,-(sp)
	move.w	d0,d1
	bsr	Random
	and.l	#$7fff,d0
	divu	d1,d0
	swap	d0
	and.l	#$ffff,d0
	move.l	(sp)+,d1
	rts

;---------------------------------------------------------------------
; file: gfx.s
;---------------------------------------------------------------------
;=====================================================================
; gfx.s : playfield 2 drawing - blitter bobs, clears, text, numbers
; PF2 is interleaved: row = 3 planes x 48 bytes (PF2ROW = 144)
; bitmap x = screen x + 16 (16 hidden pixels left)
;=====================================================================

; ClearRows: d0 = first y, d1 = number of rows, a1 = buffer
ClearRows:
	movem.l	d0-d2/a1,-(sp)
	tst.w	d1
	ble.s	.x
	mulu	#PF2ROW,d0
	add.l	d0,a1
	bsr	WaitBlit
	move.l	#$01000000,BLTCON0(a5)		; D only, minterm 0
	move.w	#0,BLTDMOD(a5)
	move.l	a1,BLTDPT(a5)
	move.w	d1,d2
	mulu	#3,d2
	lsl.w	#6,d2
	or.w	#PF2W/2,d2
	move.w	d2,BLTSIZE(a5)
.x:	movem.l	(sp)+,d0-d2/a1
	rts

ClearBack:
	movem.l	d0-d1/a1,-(sp)
	moveq	#16,d0
	move.w	#232,d1
	move.l	BackBuf,a1
	bsr	ClearRows
	movem.l	(sp)+,d0-d1/a1
	rts

ClearBoth:
	movem.l	d0-d1/a1,-(sp)
	clr.w	DirtyCountA
	clr.w	DirtyCountB
	move.w	#-1,EnergyShownA
	move.w	#-1,EnergyShownB
	moveq	#0,d0
	move.w	#256,d1
	move.l	BackBuf,a1
	bsr	ClearRows
	move.l	FrontBuf,a1
	bsr	ClearRows
	bsr	WaitBlit
	movem.l	(sp)+,d0-d1/a1
	rts

; CopyBackToFront: make both buffers identical (after drawing static screens)
CopyBuffers:
	movem.l	d0-d2,-(sp)
	bsr	WaitBlit
	move.l	#$09f00000,BLTCON0(a5)		; A -> D
	move.l	#$ffffffff,BLTAFWM(a5)
	move.w	#0,BLTAMOD(a5)
	move.w	#0,BLTDMOD(a5)
	move.l	BackBuf,BLTAPT(a5)
	move.l	FrontBuf,BLTDPT(a5)
	move.w	#(768<<6)|(PF2W/2),BLTSIZE(a5)	; 256 rows x 3 planes
	bsr	WaitBlit
	movem.l	(sp)+,d0-d2
	rts

;---------------------------------------------------------------------
; Dirty rectangles: everything drawn into the back buffer is logged and
; erased (blitter, D only) the next time this buffer becomes the back
; buffer.  AddDirty: a2 = start address (even), d0 = BLTSIZE, d1 = modulo
;---------------------------------------------------------------------
AddDirty:
	movem.l	d2/a0-a1,-(sp)
	lea	DirtyA,a0
	lea	DirtyCountA,a1
	cmp.l	#PF2BufA,BackBuf
	beq.s	.a
	lea	DirtyB,a0
	lea	DirtyCountB,a1
.a:	move.w	(a1),d2
	cmp.w	#MAXDIRTY,d2
	bge.s	.x
	addq.w	#1,(a1)
	lsl.w	#3,d2
	add.w	d2,a0
	move.l	a2,(a0)+
	move.w	d0,(a0)+
	move.w	d1,(a0)+
.x:	movem.l	(sp)+,d2/a0-a1
	rts

ClearDirty:
	movem.l	d0-d2/a0-a1,-(sp)
	lea	DirtyA,a0
	lea	DirtyCountA,a1
	cmp.l	#PF2BufA,BackBuf
	beq.s	.a
	lea	DirtyB,a0
	lea	DirtyCountB,a1
.a:	move.w	(a1),d2
	clr.w	(a1)
	subq.w	#1,d2
	bmi.s	.x
	bsr	WaitBlit
	move.l	#$01000000,BLTCON0(a5)
.l:	bsr	WaitBlit
	move.l	(a0)+,BLTDPT(a5)
	move.w	(a0)+,d0
	move.w	(a0)+,BLTDMOD(a5)
	move.w	d0,BLTSIZE(a5)
	dbf	d2,.l
.x:	movem.l	(sp)+,d0-d2/a0-a1
	rts

;---------------------------------------------------------------------
; DrawBob: d0 = bob index, d1 = screen x, d2 = screen y (into BackBuf)
; clipped vertically to 16..247; skipped when off screen horizontally
;---------------------------------------------------------------------
DrawBob:
	movem.l	d0-d7/a0-a2,-(sp)
	move.l	BackBuf,a2
	st	BobDirty
	bsr.s	BobCore
	movem.l	(sp)+,d0-d7/a0-a2
	rts

; DrawBobBoth: draw into both buffers (static screens, not logged)
DrawBobBoth:
	movem.l	d0-d7/a0-a2,-(sp)
	move.l	BackBuf,a2
	sf	BobDirty
	bsr.s	BobCore
	movem.l	(sp),d0-d7/a0-a2
	move.l	FrontBuf,a2
	sf	BobDirty
	bsr.s	BobCore
	movem.l	(sp)+,d0-d7/a0-a2
	rts

; BobCore: a2 = buffer, d0 bob, d1 x, d2 y (clobbers registers)
BobCore:
	lea	BobTable,a0
	lsl.w	#4,d0
	add.w	d0,a0
	move.l	(a0)+,d6			; data
	move.l	(a0)+,d7			; mask
	move.w	(a0)+,d3			; words
	move.w	(a0)+,d4			; height
	; vertical clip
	move.w	ClipTop,d0
	cmp.w	d0,d2
	bge.s	.ct
	sub.w	d2,d0				; rows to skip
	cmp.w	d4,d0
	bge	.out
	sub.w	d0,d4
	move.w	d3,d5
	mulu	#6,d5				; bytes per bob row (3 planes)
	mulu	d0,d5
	add.l	d5,d6
	add.l	d5,d7
	move.w	ClipTop,d2
.ct:	move.w	d2,d0
	add.w	d4,d0
	cmp.w	ClipBottom,d0
	ble.s	.cb
	move.w	ClipBottom,d4
	sub.w	d2,d4
	ble	.out
.cb:	; horizontal
	add.w	#16,d1
	bmi	.out
	move.w	d3,d0
	addq.w	#1,d0
	lsl.w	#4,d0
	neg.w	d0
	add.w	#PF2W*8,d0
	cmp.w	d0,d1
	bgt	.out
	; dest
	move.w	d2,d0
	mulu	#PF2ROW,d0
	move.w	d1,d5
	lsr.w	#4,d5
	add.w	d5,d5
	add.w	d5,d0
	add.l	d0,a2
	and.w	#15,d1
	ror.w	#4,d1				; shift in bits 15-12
	bsr	WaitBlit
	move.w	d1,d0
	or.w	#$0fca,d0
	move.w	d0,BLTCON0(a5)
	move.w	d1,BLTCON1(a5)
	move.l	#$ffff0000,BLTAFWM(a5)
	move.w	#-2,BLTAMOD(a5)
	move.w	#-2,BLTBMOD(a5)
	move.w	d3,d0
	addq.w	#1,d0
	add.w	d0,d0
	neg.w	d0
	add.w	#PF2W,d0
	move.w	d0,BLTCMOD(a5)
	move.w	d0,BLTDMOD(a5)
	move.l	d7,BLTAPT(a5)
	move.l	d6,BLTBPT(a5)
	move.l	a2,BLTCPT(a5)
	move.l	a2,BLTDPT(a5)
	move.w	d4,d0
	mulu	#3,d0
	lsl.w	#6,d0
	addq.w	#1,d3
	or.w	d3,d0
	move.w	d0,BLTSIZE(a5)
	tst.b	BobDirty
	beq.s	.out
	move.w	d3,d1
	add.w	d1,d1
	neg.w	d1
	add.w	#PF2W,d1
	bsr	AddDirty
.out:	rts

; BobSize: d0 = bob -> d1 = width px, d2 = height
BobSize:
	move.l	a0,-(sp)
	lea	BobTable,a0
	lsl.w	#4,d0
	add.w	d0,a0
	move.w	10(a0),d2
	move.w	12(a0),d1
	lsr.w	#4,d0
	move.l	(sp)+,a0
	rts

;---------------------------------------------------------------------
; FillRect: d0 = x (multiple of 8), d1 = y, d2 = width (multiple of 8),
; d3 = height, d4 = colour (0..7), a1 = buffer.  CPU byte fill.
;---------------------------------------------------------------------
FillRect:
	movem.l	d0-d7/a0-a1,-(sp)
	bsr	WaitBlit
	mulu	#PF2ROW,d1
	add.l	d1,a1
	lsr.w	#3,d0
	addq.w	#2,d0
	add.w	d0,a1
	lsr.w	#3,d2
	subq.w	#1,d2
	subq.w	#1,d3
	bmi.s	.x
.row:	moveq	#0,d5				; plane
	move.l	a1,a0
.pl:	moveq	#0,d6
	btst	d5,d4
	beq.s	.z
	moveq	#-1,d6
.z:	move.w	d2,d7
	move.l	a0,-(sp)
.b:	move.b	d6,(a0)+
	dbf	d7,.b
	move.l	(sp)+,a0
	add.w	#PF2W,a0
	addq.w	#1,d5
	cmp.w	#3,d5
	bne.s	.pl
	add.w	#PF2ROW,a1
	dbf	d3,.row
.x:	movem.l	(sp)+,d0-d7/a0-a1
	rts

;---------------------------------------------------------------------
; Text.  Print: a0 = string (0 terminated), d0 = column (0..39),
; d1 = y (pixels), d2 = colour (0..7), a1 = buffer
; '\n' (10) moves to the next line (8 px) at the start column.
; Uses ColFont: per colour, per char 8 rows x 3 plane bytes.
;---------------------------------------------------------------------
InitColFont:
	lea	ColFont,a1
	moveq	#0,d2				; colour
.col:	lea	Font,a0
	moveq	#95,d6				; chars
.char:	moveq	#0,d7				; previous row of this char
	moveq	#7,d3
.row:	move.b	(a0)+,d0
	move.b	d7,d4				; shadow = previous row shifted right
	lsr.b	#1,d4
	move.b	d0,d5
	not.b	d5
	and.b	d5,d4
	tst.w	d2
	bne.s	.sh
	moveq	#0,d4				; colour 0: no shadow
.sh:	move.b	d0,d7
	moveq	#0,d5
.pl:	moveq	#0,d1
	btst	d5,d2
	beq.s	.z
	move.b	d0,d1
.z:	or.b	d4,d1				; shadow uses colour 7 (all planes)
	move.b	d1,(a1)+
	addq.w	#1,d5
	cmp.w	#3,d5
	bne.s	.pl
	dbf	d3,.row
	dbf	d6,.char
	addq.w	#1,d2
	cmp.w	#8,d2
	bne.s	.col
	rts

Print:
	movem.l	d0-d7/a0-a3,-(sp)
	bsr	WaitBlit
	cmp.l	BackBuf,a1
	bne.s	.nod
	tst.b	NoDirty
	bne.s	.nod
	bsr	PrintDirty
.nod:	lea	ColFont,a3
	and.w	#7,d2
	mulu	#96*24,d2
	add.l	d2,a3
	move.l	a1,d2				; d2 = buffer
	move.w	d0,d7				; start column
.line:	move.w	d1,d3
	mulu	#PF2ROW,d3
	move.l	d2,a2
	add.l	d3,a2
	add.w	d0,a2
	addq.w	#2,a2				; a2 = destination of this column
.ch:	moveq	#0,d3
	move.b	(a0)+,d3
	beq.s	.done
	cmp.b	#10,d3
	beq.s	.nl
	cmp.w	#40,d0
	bge.s	.skip
	sub.w	#32,d3
	bmi.s	.skip
	mulu	#24,d3
	lea	(a3,d3.w),a1		; glyph rows
	move.l	a2,d6
	moveq	#7,d4
.r:	move.b	(a1)+,(a2)
	move.b	(a1)+,PF2W(a2)
	move.b	(a1)+,PF2W*2(a2)
	lea	PF2ROW(a2),a2
	dbf	d4,.r
	move.l	d6,a2
.skip:	addq.w	#1,d0
	addq.l	#1,a2
	bra.s	.ch
.nl:	move.w	d7,d0
	add.w	#10,d1
	bra.s	.line
.done:	movem.l	(sp)+,d0-d7/a0-a3
	rts

; PrintDirty: log the area of string a0 at column d0, y d1 (single line;
; multi-line strings log 8 rows per line)
PrintDirty:
	movem.l	d0-d3/a0-a2,-(sp)
	cmp.w	#16,d1
	blt.s	.x
	cmp.w	#248,d1
	bge.s	.x
.line:	moveq	#0,d2
.len:	move.b	(a0)+,d3
	beq.s	.go
	cmp.b	#10,d3
	beq.s	.go
	addq.w	#1,d2
	bra.s	.len
.go:	tst.w	d2
	beq.s	.nxt
	move.w	d1,d3
	mulu	#PF2ROW,d3
	move.l	a1,a2
	add.l	d3,a2
	move.w	d0,d3
	addq.w	#2,d3
	and.w	#$fffe,d3
	add.w	d3,a2
	movem.l	d0-d1,-(sp)
	add.w	#3,d2
	lsr.w	#1,d2				; words
	move.w	#(24<<6),d0
	or.w	d2,d0
	add.w	d2,d2
	neg.w	d2
	add.w	#PF2W,d2
	move.w	d2,d1
	bsr	AddDirty
	movem.l	(sp)+,d0-d1
.nxt:	add.w	#10,d1
	tst.b	-1(a0)
	bne.s	.line
.x:	movem.l	(sp)+,d0-d3/a0-a2
	rts

; PrintBoth: print into both buffers
PrintBoth:
	move.l	a1,-(sp)
	st	NoDirty
	move.l	BackBuf,a1
	bsr	Print
	move.l	FrontBuf,a1
	bsr	Print
	sf	NoDirty
	move.l	(sp)+,a1
	rts

; PrintBack: print into back buffer
PrintBack:
	move.l	a1,-(sp)
	move.l	BackBuf,a1
	bsr	Print
	move.l	(sp)+,a1
	rts

; PrintCentre*: centre string a0 on line d1, colour d2
StrLen:
	move.l	a0,-(sp)
	moveq	#-1,d0
.l:	addq.w	#1,d0
	tst.b	(a0)+
	bne.s	.l
	move.l	(sp)+,a0
	rts
CentreCol:
	bsr	StrLen
	neg.w	d0
	add.w	#40,d0
	asr.w	#1,d0
	rts
PrintCentreBoth:
	movem.l	d0,-(sp)
	bsr	CentreCol
	bsr	PrintBoth
	movem.l	(sp)+,d0
	rts
PrintCentreBack:
	movem.l	d0,-(sp)
	bsr	CentreCol
	bsr	PrintBack
	movem.l	(sp)+,d0
	rts

;---------------------------------------------------------------------
; PrintBig: big 16 px font (blitter glyphs). a0 = string, d0 = x pixel,
; d1 = y, d2 = colour (C_YELLOW = gold style, others = cool), a1 = buffer
;---------------------------------------------------------------------
BIG_ADV	equ	15
PrintBig:
	movem.l	d0-d7/a0-a4,-(sp)
	moveq	#0,d6
	cmp.w	#C_YELLOW,d2
	bne.s	.c
	move.w	#BIGCOUNT,d6
.c:	move.l	a1,a4
	sf	d7
	cmp.l	BackBuf,a1
	bne.s	.ch
	tst.b	NoDirty
	bne.s	.ch
	st	d7
.ch:	moveq	#0,d3
	move.b	(a0)+,d3
	beq.s	.done
	cmp.b	#'a',d3
	blt.s	.up
	sub.b	#32,d3
.up:	sub.w	#32,d3
	bmi.s	.next
	cmp.w	#64,d3
	bhs.s	.next
	lea	BigMap,a3
	move.b	(a3,d3.w),d3
	cmp.b	#$ff,d3
	beq.s	.next
	ext.w	d3
	add.w	d6,d3
	add.w	#BOB_BF_COOL_41,d3
	movem.l	d0-d7/a0-a4,-(sp)
	move.b	d7,BobDirty
	move.w	d1,d2
	move.w	d0,d1
	move.w	d3,d0
	move.l	a4,a2
	bsr	BobCore
	movem.l	(sp)+,d0-d7/a0-a4
.next:	add.w	#BIG_ADV,d0
	bra.s	.ch
.done:	movem.l	(sp)+,d0-d7/a0-a4
	rts

; PrintBigCentre: a0 string, d1 y, d2 colour, a1 buffer
PrintBigCentre:
	movem.l	d0,-(sp)
	bsr	StrLen
	mulu	#BIG_ADV,d0
	neg.w	d0
	add.w	#320,d0
	asr.w	#1,d0
	bsr	PrintBig
	movem.l	(sp)+,d0
	rts

InitDoubleTab:
	lea	DoubleTab,a0
	moveq	#0,d0
.n:	moveq	#0,d1
	moveq	#7,d2
.b:	lsl.w	#2,d1
	btst	d2,d0
	beq.s	.z
	or.w	#3,d1
.z:	dbf	d2,.b
	move.w	d1,(a0)+
	addq.w	#1,d0
	cmp.w	#256,d0
	bne.s	.n
	rts

;---------------------------------------------------------------------
; Numbers: NumStr d0 = value, d1 = digits, a0 = buffer -> zero padded
; string (0 terminated). value < 655360
;---------------------------------------------------------------------
NumStr:
	movem.l	d0-d2/a0,-(sp)
	and.l	#$000fffff,d0
	add.w	d1,a0
	clr.b	(a0)
	subq.w	#1,d1
.d:	divu	#10,d0
	swap	d0
	add.b	#'0',d0
	move.b	d0,-(a0)
	clr.w	d0
	swap	d0
	dbf	d1,.d
	movem.l	(sp)+,d0-d2/a0
	rts

; PutNumW: like PutNum for a word value in d0
PutNumW:
	move.l	d0,-(sp)
	and.l	#$ffff,d0
	bsr.s	PutNum
	move.l	(sp)+,d0
	rts
; PutNum: write digits of d0 into string at a0 (no terminator), d1 digits
PutNum:
	movem.l	d0-d2/a0,-(sp)
	and.l	#$000fffff,d0
	add.w	d1,a0
	subq.w	#1,d1
.d:	divu	#10,d0
	swap	d0
	add.b	#'0',d0
	move.b	d0,-(a0)
	clr.w	d0
	swap	d0
	dbf	d1,.d
	movem.l	(sp)+,d0-d2/a0
	rts

;---------------------------------------------------------------------
; DrawLogo: copy the title logo into both buffers at y = LOGO_Y
;---------------------------------------------------------------------
DrawLogo:
	movem.l	d0-d2/a0-a2,-(sp)
	move.l	BackBuf,a1
	bsr.s	.one
	move.l	FrontBuf,a1
	bsr.s	.one
	movem.l	(sp)+,d0-d2/a0-a2
	rts
.one:	bsr	WaitBlit
	move.l	#$09f00000,BLTCON0(a5)
	move.l	#$ffffffff,BLTAFWM(a5)
	move.w	#0,BLTAMOD(a5)
	move.w	#PF2W-40,BLTDMOD(a5)
	move.l	#LogoData,BLTAPT(a5)
	move.l	a1,d0
	add.l	#LOGO_Y*PF2ROW+2,d0
	move.l	d0,BLTDPT(a5)
	move.w	#((LOGO_H*3)<<6)|20,BLTSIZE(a5)
	bsr	WaitBlit
	rts

;---------------------------------------------------------------------
; HLine: CPU horizontal line in PF2 (for frames / bars), d0 x (mult 8),
; d1 y, d2 width (mult 8), d4 colour, a1 buffer   (1 pixel high)
;---------------------------------------------------------------------
HLine:
	movem.l	d3,-(sp)
	moveq	#1,d3
	bsr	FillRect
	movem.l	(sp)+,d3
	rts

; Bar: energy style bar. d0 x, d1 y, d2 total width(px mult 8), d3 filled px,
; d4 colour full, d5 colour empty, a1 buffer. height 6. Fills whole bytes.
Bar:
	movem.l	d0-d7/a0-a1,-(sp)
	move.w	d3,d6
	lsr.w	#3,d6				; full bytes
	move.w	d2,d7
	lsr.w	#3,d7
	sub.w	d6,d7				; empty bytes
	move.w	d4,-(sp)
	move.w	d6,d2
	lsl.w	#3,d2
	beq.s	.nofull
	moveq	#6,d3
	bsr	FillRect
.nofull:
	add.w	d2,d0
	move.w	(sp)+,d4
	move.w	d7,d2
	lsl.w	#3,d2
	beq.s	.noempty
	move.w	d5,d4
	moveq	#6,d3
	bsr	FillRect
.noempty:
	movem.l	(sp)+,d0-d7/a0-a1
	rts

;---------------------------------------------------------------------
; Drawing into playfield 1 (static scenes: map / flight). PF1 is
; interleaved 3 planes x 84 bytes; with scroll 0, column = screen x + 16
;---------------------------------------------------------------------
; PlotPF1: d0 x, d1 y, d2 colour (0..7)
PlotPF1:
	movem.l	d0-d4/a1,-(sp)
	tst.w	d0
	bmi.s	.x
	cmp.w	#320,d0
	bge.s	.x
	lea	PF1Buf,a1
	add.w	#16,d0
	mulu	#PF1ROW,d1
	add.l	d1,a1
	move.w	d0,d1
	lsr.w	#3,d1
	add.w	d1,a1
	not.w	d0
	and.w	#7,d0
	moveq	#2,d4
	moveq	#0,d3
.p:	btst	d3,d2
	beq.s	.cl
	bset	d0,(a1)
	bra.s	.n
.cl:	bclr	d0,(a1)
.n:	add.w	#PF1W,a1
	addq.w	#1,d3
	dbf	d4,.p
.x:	movem.l	(sp)+,d0-d4/a1
	rts

; MarkerPF1: d0 x, d1 y, d2 colour - 4x4 block
MarkerPF1:
	movem.l	d0-d4,-(sp)
	moveq	#3,d4
.r:	moveq	#3,d3
.c:	movem.l	d0-d1,-(sp)
	add.w	d3,d0
	add.w	d4,d1
	bsr	PlotPF1
	movem.l	(sp)+,d0-d1
	dbf	d3,.c
	dbf	d4,.r
	movem.l	(sp)+,d0-d4
	rts

; PrintPF1: a0 string, d0 column, d1 y, d2 colour (transparent: ORs glyph)
PrintPF1:
	movem.l	d0-d7/a0-a3,-(sp)
	lea	Font,a3
.ch:	moveq	#0,d3
	move.b	(a0)+,d3
	beq.s	.done
	sub.w	#32,d3
	bmi.s	.skip
	lsl.w	#3,d3
	lea	(a3,d3.w),a2
	lea	PF1Buf,a1
	move.w	d1,d4
	mulu	#PF1ROW,d4
	add.l	d4,a1
	add.w	d0,a1
	addq.w	#2,a1
	moveq	#7,d4
.r:	move.b	(a2)+,d5
	move.b	d5,d6
	not.b	d6
	moveq	#0,d7
.pl:	btst	d7,d2
	beq.s	.z
	or.b	d5,(a1)
	bra.s	.nx
.z:	and.b	d6,(a1)
.nx:	add.w	#PF1W,a1
	addq.w	#1,d7
	cmp.w	#3,d7
	bne.s	.pl
	add.w	#PF1ROW-PF1W*3,a1
	dbf	d4,.r
.skip:	addq.w	#1,d0
	bra.s	.ch
.done:	movem.l	(sp)+,d0-d7/a0-a3
	rts

;---------------------------------------------------------------------
; Hunter = 4 hardware sprites (two attached pairs, 32 x 32, 15 colours).
; SetHunter: d0 = frame (0-6 facing right, 7-13 left), d1 = x, d2 = y
; The sprite data of the back buffer's copy is updated (no tearing).
;---------------------------------------------------------------------
SetHunter:
	movem.l	d0-d7/a0-a2,-(sp)
	cmp.l	#PF2BufA,BackBuf
	beq.s	.a
	add.w	#SPR_NFRAMES,d0
.a:	lsl.w	#4,d0
	lea	HunterFrames,a0
	add.w	d0,a0
	lea	SprPtrs,a1
	add.w	#$2c,d2				; VSTART
	move.w	d2,d3
	add.w	#SPR_H,d3			; VSTOP
	add.w	#$80,d1				; HSTART
	moveq	#0,d6				; sprite 0..3
.l:	move.l	(a0)+,a2
	move.l	a2,(a1)+
	move.w	d1,d4
	cmp.w	#2,d6
	blt.s	.x0
	add.w	#16,d4
.x0:	move.w	d2,d5
	lsl.w	#8,d5
	move.w	d4,d7
	lsr.w	#1,d7
	and.w	#$ff,d7
	or.w	d7,d5
	move.w	d5,(a2)				; POS
	move.w	d3,d5
	lsl.w	#8,d5
	btst	#8,d2
	beq.s	.v1
	bset	#2,d5
.v1:	btst	#8,d3
	beq.s	.v2
	bset	#1,d5
.v2:	btst	#0,d4
	beq.s	.h0
	bset	#0,d5
.h0:	btst	#0,d6
	beq.s	.na
	bset	#7,d5				; attach odd sprites
.na:	move.w	d5,2(a2)			; CTL
	addq.w	#1,d6
	cmp.w	#4,d6
	bne.s	.l
	move.w	#1,SprOn
	movem.l	(sp)+,d0-d7/a0-a2
	rts

HideHunter:
	movem.l	d0/a0,-(sp)
	lea	SprPtrs,a0
	moveq	#3,d0
.l:	move.l	#NullSprite,(a0)+
	dbf	d0,.l
	movem.l	(sp)+,d0/a0
	rts

;---------------------------------------------------------------------
; file: sound.s
;---------------------------------------------------------------------
;=====================================================================
; sound.s : tiny 3-channel music player + sound effects on channel 3
;=====================================================================
CH_VOL		equ	0
CH_DEC		equ	2
CH_FLOOR	equ	4
CH_NEEDLOOP	equ	6
CH_LOOP		equ	8
CH_LOOPLEN	equ	12
CHSIZE		equ	16
PATSIZE		equ	64*6

; PlaySong: a0 = order list
PlaySong:
	movem.l	d0-d1/a0,-(sp)
	bsr	StopMusic
	move.l	a0,SongStart
	move.l	a0,SongPos
	bsr	NextPattern
	clr.w	Row
	clr.w	Tick
	move.w	#1,SongActive
	movem.l	(sp)+,d0-d1/a0
	rts

StopMusic:
	clr.w	SongActive
	move.w	#$0007,DMACON(a5)
	move.w	#0,AUD0VOL(a5)
	move.w	#0,AUD1VOL(a5)
	move.w	#0,AUD2VOL(a5)
	clr.w	ChState+CH_VOL
	clr.w	ChState+CHSIZE+CH_VOL
	clr.w	ChState+CHSIZE*2+CH_VOL
	rts

NextPattern:
	movem.l	d0-d1/a0,-(sp)
	move.l	SongPos,a0
.again:	moveq	#0,d0
	move.b	(a0)+,d0
	cmp.b	#$fe,d0
	bne.s	.nostop
	clr.w	SongActive
	move.w	#$0007,DMACON(a5)
	bra.s	.x
.nostop:
	cmp.b	#$ff,d0
	bne.s	.pat
	moveq	#0,d1
	move.b	(a0),d1
	move.l	SongStart,a0
	add.w	d1,a0
	bra.s	.again
.pat:	mulu	#PATSIZE,d0
	add.l	#Patterns,d0
	move.l	d0,PatPtr
	move.l	a0,SongPos
.x:	movem.l	(sp)+,d0-d1/a0
	rts

; wait ~4 raster lines so Paula notices DMA switched off
DmaWait:
	movem.l	d0-d1,-(sp)
	moveq	#3,d1
.l:	move.b	VHPOSR(a5),d0
.w:	cmp.b	VHPOSR(a5),d0
	beq.s	.w
	dbf	d1,.l
	movem.l	(sp)+,d0-d1
	rts

MusicTick:
	movem.l	d0-d7/a0-a4,-(sp)
	tst.w	SongActive
	beq	.x
	subq.w	#1,Tick
	bpl	.env
	move.w	#5,Tick
	move.l	PatPtr,a0
	move.w	Row,d0
	mulu	#6,d0
	add.l	d0,a0
	lea	ChState,a1
	lea	AUD0LC(a5),a2
	moveq	#0,d7
	moveq	#0,d6
.ch:	moveq	#0,d0
	move.b	(a0)+,d0
	moveq	#0,d1
	move.b	(a0)+,d1
	tst.b	d0
	beq.s	.nextch
	cmp.b	#255,d0
	bne.s	.play
	clr.w	CH_VOL(a1)
	bra.s	.nextch
.play:	cmp.w	#2,d6
	bne.s	.pl2
	tst.w	VoiceTicks
	bne.s	.nextch
.pl2:	lea	InstTable,a3
	mulu	#20,d1
	add.w	d1,a3
	moveq	#1,d2
	lsl.w	d6,d2
	move.w	d2,DMACON(a5)
	or.w	d2,d7
	move.l	(a3),(a2)
	move.w	4(a3),4(a2)
	add.w	d0,d0
	lea	PeriodTable,a4
	move.w	(a4,d0.w),6(a2)
	move.l	6(a3),CH_LOOP(a1)
	move.w	10(a3),CH_LOOPLEN(a1)
	move.w	12(a3),CH_VOL(a1)
	move.w	14(a3),CH_DEC(a1)
	move.w	16(a3),CH_FLOOR(a1)
	move.w	#1,CH_NEEDLOOP(a1)
.nextch:
	lea	CHSIZE(a1),a1
	lea	16(a2),a2
	addq.w	#1,d6
	cmp.w	#3,d6
	bne	.ch
	tst.w	d7
	beq.s	.nodma
	bsr	DmaWait
	or.w	#$8000,d7
	move.w	d7,DMACON(a5)
.nodma:	addq.w	#1,Row
	cmp.w	#64,Row
	bne.s	.vols
	clr.w	Row
	bsr	NextPattern
	bra.s	.vols
.env:	lea	ChState,a1
	lea	AUD0LC(a5),a2
	moveq	#2,d6
.e:	tst.w	CH_NEEDLOOP(a1)
	beq.s	.nl
	tst.w	d6
	bne.s	.e2
	tst.w	VoiceTicks
	bne.s	.nl
.e2:
	clr.w	CH_NEEDLOOP(a1)
	move.l	CH_LOOP(a1),(a2)
	move.w	CH_LOOPLEN(a1),4(a2)
.nl:	move.w	CH_VOL(a1),d0
	sub.w	CH_DEC(a1),d0
	cmp.w	CH_FLOOR(a1),d0
	bge.s	.vf
	move.w	CH_FLOOR(a1),d0
	cmp.w	CH_VOL(a1),d0
	ble.s	.vf
	move.w	CH_VOL(a1),d0
.vf:	move.w	d0,CH_VOL(a1)
	lea	CHSIZE(a1),a1
	lea	16(a2),a2
	dbf	d6,.e
.vols:	lea	ChState,a1
	lea	AUD0LC(a5),a2
	moveq	#2,d6
.v:	move.w	CH_VOL(a1),d0
	tst.w	MusicOn
	bne.s	.von
	moveq	#0,d0
.von:	tst.w	d6
	bne.s	.vw
	tst.w	VoiceTicks
	bne.s	.vs
.vw:	move.w	d0,8(a2)
.vs:
	lea	CHSIZE(a1),a1
	lea	16(a2),a2
	dbf	d6,.v
.x:	movem.l	(sp)+,d0-d7/a0-a4
	rts

;---------------------------------------------------------------------
; Sound effects (channel 3): sampled.  PlaySfx d0 = effect number
; SfxTable entry: dc.l sample / dc.w words, period, loop ticks (0 = one shot), volume, pad
;---------------------------------------------------------------------
PlaySfx:
	movem.l	d0-d1/a0,-(sp)
	lea	SfxTable,a0
	mulu	#14,d0
	add.w	d0,a0
	move.w	#$0008,DMACON(a5)
	move.l	(a0)+,AUD3LC(a5)
	move.w	(a0),AUD3LEN(a5)
	move.w	2(a0),AUD3PER(a5)
	move.w	6(a0),AUD3VOL(a5)
	move.w	4(a0),d0			; loop ticks
	beq.s	.one
	move.w	d0,SfxTicks
	clr.w	SfxNull
	bra.s	.go
.one:	move.w	(a0),d0				; duration in frames = words*period/35469
	mulu	2(a0),d0
	divu	#35469,d0
	addq.w	#2,d0
	move.w	d0,SfxTicks
	move.w	#1,SfxNull
.go:	bsr	DmaWait
	move.w	#$8008,DMACON(a5)
	movem.l	(sp)+,d0-d1/a0
	rts

SfxTick:
	tst.w	SfxNull
	beq.s	.n
	clr.w	SfxNull
	move.l	#smp_null,AUD3LC(a5)		; one shot: loop silence afterwards
	move.w	#2,AUD3LEN(a5)
.n:	tst.w	SfxTicks
	beq.s	.v
	subq.w	#1,SfxTicks
	bne.s	.v
	move.w	#0,AUD3VOL(a5)
	move.w	#$0008,DMACON(a5)
.v:	bsr	VoiceTick
	rts

;---------------------------------------------------------------------
; Voices and long effects (channel 2, music voice 2 steps aside).
; Data is 4-bit Fibonacci-delta packed in slow RAM; it is decoded into
; the chip buffer VoiceBuf a little ahead of Paula, every frame.
; PlayVoice d0 = V_xxx
;---------------------------------------------------------------------
InitVoice:
	lea	FibTab1,a0
	lea	FibTab2,a1
	lea	FibDelta,a2
	moveq	#0,d0
.l:	move.w	d0,d1
	lsr.w	#4,d1
	move.b	(a2,d1.w),d2
	move.b	d2,(a0)+
	move.w	d0,d1
	and.w	#15,d1
	add.b	(a2,d1.w),d2
	move.b	d2,(a1)+
	addq.w	#1,d0
	cmp.w	#256,d0
	bne.s	.l
	rts

PlayVoice:
	movem.l	d0-d3/a0-a1,-(sp)
	lea	VoiceTable,a0
	lsl.w	#3,d0
	add.w	d0,a0
	move.l	(a0)+,a1
	move.w	(a0)+,d2			; words
	move.w	#$0004,DMACON(a5)
	move.w	#0,AUD2VOL(a5)
	move.b	(a1)+,VoiceVal
	addq.l	#1,a1
	move.l	a1,VoiceSrc
	move.l	#VoiceBuf,VoiceDst
	move.w	d2,VoiceLeft			; packed bytes left (= words)
	move.w	#600,d0
	bsr	VoiceDecode			; first 1200 samples
	move.l	#VoiceBuf,AUD2LC(a5)
	move.w	d2,AUD2LEN(a5)
	move.w	(a0),AUD2PER(a5)
	move.w	#64,AUD2VOL(a5)
	move.w	(a0),d0				; duration
	mulu	d2,d0
	divu	#35469,d0
	addq.w	#3,d0
	move.w	d0,VoiceTicks
	move.w	#1,VoiceNull
	bsr	DmaWait
	move.w	#$8004,DMACON(a5)
	movem.l	(sp)+,d0-d3/a0-a1
	rts

; VoiceDecode: decode up to d0 packed bytes
VoiceDecode:
	movem.l	d0-d4/a0-a3,-(sp)
	move.w	VoiceLeft,d1
	beq.s	.x
	cmp.w	d1,d0
	ble.s	.ok
	move.w	d1,d0
.ok:	sub.w	d0,VoiceLeft
	move.l	VoiceSrc,a0
	move.l	VoiceDst,a1
	lea	FibTab1,a2
	lea	FibTab2,a3
	move.b	VoiceVal,d2
	subq.w	#1,d0
	moveq	#0,d1
.l:	move.b	(a0)+,d1
	move.b	d2,d3
	add.b	(a2,d1.w),d3
	move.b	d3,(a1)+
	add.b	(a3,d1.w),d2
	move.b	d2,(a1)+
	dbf	d0,.l
	move.b	d2,VoiceVal
	move.l	a0,VoiceSrc
	move.l	a1,VoiceDst
.x:	movem.l	(sp)+,d0-d4/a0-a3
	rts

VoiceTick:
	tst.w	VoiceTicks
	beq.s	.x
	move.w	#500,d0
	bsr	VoiceDecode
	tst.w	VoiceNull
	beq.s	.n
	clr.w	VoiceNull
	move.l	#smp_null,AUD2LC(a5)
	move.w	#2,AUD2LEN(a5)
.n:	subq.w	#1,VoiceTicks
	bne.s	.x
	move.w	#0,AUD2VOL(a5)
	move.w	#$0004,DMACON(a5)
.x:	rts

FibDelta:	dc.b	-34,-21,-13,-8,-5,-3,-2,-1,0,1,2,3,5,8,13,21

;---------------------------------------------------------------------
; file: screens.s
;---------------------------------------------------------------------
;=====================================================================
; screens.s : title / attract pages, menu, hall of fame, how to play,
;             story, flights, map, level clear, game over, victory,
;             credits, name entry
;=====================================================================

MainMenuLoop:
	lea	SongMain,a0
	bsr	PlaySong
	bsr	LoadingScreen
.loop:	bsr	TitleScreen
	tst.w	d0
	bne.s	.n0
	bsr	PlayGame
	bra.s	.loop
.n0:	cmp.w	#1,d0
	bne.s	.n1
	bsr	BonusMenu
	bra.s	.loop
.n1:	cmp.w	#2,d0
	bne.s	.n2
	bsr	HowToPlay
	bra.s	.loop
.n2:	bsr	FadeOut
	bsr	StopMusic
	rts

; NewScreen: d0 = scene. fade out, set scene, clear playfield 2
NewScreen:
	bsr	FadeOut
	move.w	#16,BgFade
	clr.w	LogoGrad
	clr.w	FlashCol
	clr.w	SprOn
	clr.w	LBox
	clr.w	LBoxTarget
	clr.w	ShakeX
	clr.w	ShakeY
	clr.w	SkyFog
	bsr	SetScene
	bsr	ClearBoth
	rts

; WaitFireOrKey: d0 = timeout frames (0 = none) - returns d0 = 1 if pressed
; scrolls city by d1 per frame
WaitFire:
	movem.l	d1-d2,-(sp)
	move.w	d0,d2
.l:	move.w	d1,d0
	bsr	ScrollCity
	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.p
	bsr	GetKey
	cmp.w	#KEY_SPACE,d0
	beq.s	.p
	cmp.w	#KEY_RETURN,d0
	beq.s	.p
	cmp.w	#KEY_ESC,d0
	beq.s	.p
	tst.w	d2
	beq.s	.l
	subq.w	#1,d2
	bne.s	.l
	moveq	#0,d0
	bra.s	.x
.p:	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	moveq	#1,d0
.x:	movem.l	(sp)+,d1-d2
	rts

;---------------------------------------------------------------------
; Title screen with attract pages. returns d0: 0 start, 1 bonus,
; 2 how to play, 3 quit
;---------------------------------------------------------------------
TitleScreen:
	movem.l	d1-d7/a0-a6,-(sp)
	moveq	#1,d0
	bsr	NewScreen
	tst.w	SongActive
	bne.s	.mus
	lea	SongMain,a0
	bsr	PlaySong
.mus:	clr.w	Page
.page:	bsr	ClearBoth
	clr.w	LogoGrad
	move.w	#6,BgFade
	move.w	Page,d0
	bne.s	.p1
	move.w	#12,BgFade
	bsr	DrawMenuPage
	bra.s	.drawn
.p1:	cmp.w	#1,d0
	bne.s	.p2
	bsr	DrawHallOfFame
	bra.s	.drawn
.p2:	cmp.w	#2,d0
	bne.s	.p3
	bsr	DrawPowerPage
	bra.s	.drawn
.p3:	bsr	DrawBossPage
.drawn:	bsr	FadeIn
	clr.w	PageTimer
.loop:	; animated ghosts in the street band on the menu page
	tst.w	Page
	bne.s	.noanim
	move.w	#204,d0
	moveq	#28,d1
	move.l	BackBuf,a1
	bsr	ClearRows
	bsr	TitleGhosts
.noanim:
	moveq	#1,d0
	bsr	ScrollCity
	addq.w	#1,LogoPhase
	bsr	Frame
	addq.w	#1,PageTimer
	; keys
	bsr	GetKey
	move.w	d0,d7
	bsr	CheatCheck
	cmp.w	#KEY_M,d7
	bne.s	.nm
	eor.w	#1,MusicOn
	tst.w	Page
	bne.s	.nm
	bsr	DrawMusicLine
.nm:	cmp.w	#KEY_ESC,d7
	bne.s	.ne
	tst.w	Page
	bne.s	.tomenu
	move.w	#4,MenuSel
	moveq	#3,d0
	bra	.x
.ne:	move.w	JoyNew,d6
	tst.w	CheatHold			; S and T double as down / up: ignore them
	beq.s	.nch				; while GHOST is being typed
	subq.w	#1,CheatHold
	moveq	#0,d6
.nch:	tst.w	Page
	beq.s	.menu
	; any input on an info page -> back to the menu
	tst.w	d6
	bne.s	.tomenu
	tst.w	d7
	bpl.s	.tomenu
	bra	.timer
.tomenu:
	clr.w	Page
	bsr	FadeOut
	bra	.page
.menu:	btst	#J_UP,d6
	beq.s	.nu
	subq.w	#1,MenuSel
	bpl.s	.mv
	move.w	#4,MenuSel
	bra.s	.mv
.nu:	btst	#J_DOWN,d6
	beq.s	.nd
	addq.w	#1,MenuSel
	cmp.w	#5,MenuSel
	blt.s	.mv
	clr.w	MenuSel
.mv:	moveq	#SFX_MOVE,d0
	bsr	PlaySfx
	bsr	DrawMenuItems
	clr.w	PageTimer
	bra	.timer
.nd:	cmp.w	#3,MenuSel			; difficulty: left/right/fire toggles
	bne.s	.nodiff
	move.w	d6,d0
	and.w	#(1<<J_LEFT)|(1<<J_RIGHT)|(1<<J_FIRE),d0
	beq.s	.timer
	btst	#J_LEFT,d6
	beq.s	.dinc
	subq.w	#1,Difficulty
	bpl.s	.dset
	move.w	#2,Difficulty
	bra.s	.dset
.dinc:	addq.w	#1,Difficulty
	cmp.w	#3,Difficulty
	blt.s	.dset
	clr.w	Difficulty
.dset:	move.w	Difficulty,HiData+HISIZE-4
	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	bsr	DrawMenuItems
	clr.w	PageTimer
	bra.s	.timer
.nodiff:
	btst	#J_FIRE,d6
	bne.s	.sel
	cmp.w	#KEY_RETURN,d7
	beq.s	.sel
	cmp.w	#KEY_SPACE,d7
	bne.s	.timer
.sel:	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	move.w	MenuSel,d0
	cmp.w	#4,d0
	bne.s	.x
	moveq	#3,d0
	bra.s	.x
.timer:	cmp.w	#600,PageTimer
	blt	.loop
	addq.w	#1,Page
	and.w	#3,Page
	bsr	FadeOut
	bra	.page
.x:	movem.l	(sp)+,d1-d7/a0-a6
	rts

DrawMenuPage:
	bsr	DrawLogo
	move.w	#1,LogoGrad
	lea	TxtAmigaGame,a0
	move.w	#102,d1
	moveq	#C_BLUE,d2
	bsr	PrintCentreBoth
	bsr	MakeHiLine
	lea	TmpStr,a0
	move.w	#116,d1
	moveq	#C_GREEN,d2
	bsr	PrintCentreBoth
	bsr	DrawMenuItems
	bsr	DrawCheatLine
	bsr	DrawMusicLine
	lea	TxtCreated,a0
	move.w	#240,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	rts

DrawMusicLine:
	lea	TxtMMusicOn,a0
	tst.w	MusicOn
	bne.s	.on
	lea	TxtMMusicOff,a0
.on:	moveq	#1,d0
	move.w	#232,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBoth
	lea	TxtYear,a0
	moveq	#35,d0
	bsr	PrintBoth
	rts

; "HIGH SCORE STRONKIE 00600 LV 02"
MakeHiLine:
	movem.l	d0-d2/a0-a1,-(sp)
	lea	TmpStr,a1
	lea	TxtHighScore,a0
.c:	move.b	(a0)+,(a1)+
	bne.s	.c
	subq.l	#1,a1
	lea	HiData+4,a0
	moveq	#7,d0
.n:	move.b	(a0)+,(a1)+
	dbf	d0,.n
	move.b	#' ',(a1)+
	move.l	(a0)+,d0
	move.l	a1,a0
	moveq	#5,d1
	bsr	PutNum
	lea	5(a1),a1
	move.b	#' ',(a1)+
	move.b	#'L',(a1)+
	move.b	#'V',(a1)+
	move.b	#' ',(a1)+
	move.w	HiData+4+12,d0
	move.l	a1,a0
	moveq	#2,d1
	bsr	PutNumW
	clr.b	2(a1)
	movem.l	(sp)+,d0-d2/a0-a1
	rts

DrawMenuItems:
	movem.l	d0-d7/a0-a2,-(sp)
	lea	MenuTexts,a2
	moveq	#0,d7
	move.w	#134,d6
.l:	; clear line
	moveq	#0,d0
	move.w	d6,d1
	move.w	#320,d2
	moveq	#8,d3
	moveq	#0,d4
	move.l	BackBuf,a1
	bsr	FillRect
	move.l	FrontBuf,a1
	bsr	FillRect
	move.l	(a2)+,a0
	cmp.w	#3,d7
	bne.s	.nd
	move.w	Difficulty,d0
	lsl.w	#2,d0
	lea	DiffTexts,a0
	move.l	(a0,d0.w),a0
.nd:	moveq	#C_WHITE,d2
	cmp.w	MenuSel,d7
	bne.s	.p
	moveq	#C_YELLOW,d2
	; selection markers
	movem.l	d0-d2/a0,-(sp)
	bsr	CentreCol
	subq.w	#3,d0
	lea	TxtMarkL,a0
	move.w	d6,d1
	bsr	PrintBoth
	movem.l	(sp)+,d0-d2/a0
	movem.l	d0-d2/a0,-(sp)
	bsr	CentreCol
	move.w	d0,d1
	bsr	StrLen
	add.w	d1,d0
	addq.w	#1,d0
	lea	TxtMarkR,a0
	move.w	d6,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBoth
	movem.l	(sp)+,d0-d2/a0
.p:	move.w	d6,d1
	bsr	PrintCentreBoth
	add.w	#12,d6
	addq.w	#1,d7
	cmp.w	#5,d7
	bne	.l
	movem.l	(sp)+,d0-d7/a0-a2
	rts

; three ghosts floating along the bottom of the menu page
; CheatCheck: d7 = key. Typing G-H-O-S-T on the title switches the test
; cheat on / off: unlimited lives, full power, N = next level, no Hall of Fame
CheatCheck:
	movem.l	d0-d2/a0-a1,-(sp)
	tst.w	d7
	bmi	.x
	lea	CheatSeq,a0
.in:	move.b	(a0)+,d0
	beq.s	.nin
	cmp.b	d0,d7
	bne.s	.in
	move.w	#6,CheatHold
.nin:	lea	CheatSeq,a0
	move.w	CheatPos,d0
	cmp.b	(a0,d0.w),d7
	beq.s	.ok
	clr.w	CheatPos
	cmp.b	(a0),d7
	bne.s	.x
.ok:	addq.w	#1,CheatPos
	cmp.w	#5,CheatPos
	bne.s	.x
	clr.w	CheatPos
	eor.w	#1,Cheat
	; flash the screen
	move.w	#$fff,FlashCol
	moveq	#5,d2
.fl:	bsr	Frame
	dbf	d2,.fl
	clr.w	FlashCol
	moveq	#SFX_POWER,d0
	bsr	PlaySfx
	tst.w	Cheat
	beq.s	.off
	moveq	#V_CHEAT,d0
	bsr	PlayVoice
.off:	tst.w	Page
	bne.s	.x
	bsr	DrawCheatLine
.x:	movem.l	(sp)+,d0-d2/a0-a1
	rts

DrawCheatLine:
	movem.l	d0-d4/a0-a1,-(sp)
	moveq	#0,d0
	move.w	#196,d1
	move.w	#320,d2
	moveq	#8,d3
	moveq	#0,d4
	move.l	BackBuf,a1
	bsr	FillRect
	move.l	FrontBuf,a1
	bsr	FillRect
	tst.w	Cheat
	beq.s	.x
	lea	TxtCheatOn,a0
	move.w	#196,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
.x:	movem.l	(sp)+,d0-d4/a0-a1
	rts

TitleGhosts:
	movem.l	d0-d4/a0,-(sp)
	moveq	#2,d4
.g:	move.l	FrameCount,d1
	move.w	d4,d0
	mulu	#110,d0
	add.w	d0,d1
	and.w	#511,d1
	sub.w	#60,d1
	move.l	FrameCount,d2
	lsl.w	#2,d2
	move.w	d4,d0
	lsl.w	#6,d0
	add.w	d0,d2
	and.w	#255,d2
	lea	SinTab,a0
	move.b	(a0,d2.w),d2
	ext.w	d2
	asr.w	#7,d2
	add.w	#206,d2
	move.w	d4,d0
	lsl.w	#2,d0
	add.w	#BOB_G_NORMAL0,d0
	move.l	FrameCount,d3
	lsr.w	#3,d3
	and.w	#3,d3
	add.w	d3,d0
	cmp.w	#2,d4
	bne.s	.d
	move.w	#BOB_BAT0,d0
	add.w	d3,d0
.d:	bsr	DrawBob
	dbf	d4,.g
	movem.l	(sp)+,d0-d4/a0
	rts

DrawHallOfFame:
	movem.l	d0-d7/a0-a2,-(sp)
	lea	TxtHof,a0
	moveq	#24,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	lea	TxtTop10,a0
	moveq	#38,d1
	moveq	#C_BLUE,d2
	bsr	PrintCentreBoth
	lea	HiData+4,a2
	moveq	#0,d7
	moveq	#58,d6
.e:	lea	TmpStr,a1
	move.w	d7,d0
	addq.w	#1,d0
	cmp.w	#10,d0
	blt.s	.sp
	move.b	#'1',(a1)+
	moveq	#0,d0
	bra.s	.dg
.sp:	move.b	#' ',(a1)+
.dg:	add.b	#'0',d0
	move.b	d0,(a1)+
	move.b	#'.',(a1)+
	move.b	#' ',(a1)+
	move.b	#' ',(a1)+
	moveq	#7,d0
.nm:	move.b	(a2)+,(a1)+
	dbf	d0,.nm
	move.b	#' ',(a1)+
	move.b	#' ',(a1)+
	move.l	(a2)+,d0
	move.l	a1,a0
	moveq	#5,d1
	bsr	PutNum
	lea	5(a1),a1
	move.b	#' ',(a1)+
	move.b	#' ',(a1)+
	move.b	#'L',(a1)+
	move.b	#'V',(a1)+
	move.b	#' ',(a1)+
	move.w	(a2)+,d0
	move.l	a1,a0
	moveq	#2,d1
	bsr	PutNumW
	clr.b	2(a1)
	lea	TmpStr,a0
	move.w	d6,d1
	moveq	#C_WHITE,d2
	tst.w	d7
	bne.s	.c
	moveq	#C_YELLOW,d2
.c:	moveq	#6,d0
	bsr	PrintBoth
	add.w	#12,d6
	addq.w	#1,d7
	cmp.w	#10,d7
	bne	.e
	lea	TxtPressPlay,a0
	move.w	#186,d1
	moveq	#C_GREEN,d2
	bsr	PrintCentreBoth
	movem.l	(sp)+,d0-d7/a0-a2
