;---------------------------------------------------------------------
; Story: letterboxed, lightning and thunder, ghosts swooping over the
; city, the opening scene (hunter walks in and blasts a ghost), and the
; story text typed in between.  Fire / space / esc skips.
;---------------------------------------------------------------------
Story:
	movem.l	d0-d7/a0-a3,-(sp)
	moveq	#1,d0
	bsr	NewScreen
	move.w	#32,LBox
	move.w	#32,LBoxTarget
	bsr	FadeIn
	clr.w	StorySkip
	move.w	#16,StoryBase
	lea	StoryPages,a3
	moveq	#0,d7				; page number
.page:	move.l	(a3)+,d0
	beq	.done
	move.l	d0,a2
	bsr	ClearBoth
	; scene before the text
	move.w	d7,d0
	bsr	StoryScene
	tst.w	StorySkip
	bne	.done
	bsr	ClearBoth
	move.w	#9,StoryBase
	moveq	#54,d6				; y
.line:	move.b	(a2)+,d5			; colour code
	beq.s	.endpage
	ext.w	d5
	move.l	a2,a0
	bsr	CentreCol
	move.w	d0,d4
.ch:	move.b	(a2)+,d0
	beq.s	.eol
	lea	TmpStr,a0
	move.b	d0,(a0)
	clr.b	1(a0)
	move.w	d4,d0
	move.w	d6,d1
	move.w	d5,d2
	bsr	PrintBoth
	addq.w	#1,d4
	cmp.b	#' ',(a0)
	beq.s	.nt
	moveq	#SFX_TYPE,d0
	bsr	PlaySfx
.nt:	bsr	StoryFrame
	tst.w	StorySkip
	bne.s	.done
	bra.s	.ch
.eol:	add.w	#11,d6
	bra.s	.line
.endpage:
	move.w	#200,d5
.wait:	bsr	StoryFrame
	tst.w	StorySkip
	bne.s	.done
	btst	#J_FIRE,Joy+1
	bne.s	.done
	subq.w	#1,d5
	bne.s	.wait
	move.w	#16,StoryBase
	addq.w	#1,d7
	bra	.page
.done:	tst.w	StorySkip
	beq.s	.d2
	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
.d2:	clr.w	SprOn
	clr.w	LBoxTarget
	movem.l	(sp)+,d0-d7/a0-a3
	rts

; StoryFrame: one frame - slow pan, lightning, skip test
StoryFrame:
	movem.l	d0-d1,-(sp)
	moveq	#1,d0
	bsr	ScrollCity
	bsr	StoryLightning
	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.s
	bsr	GetKey
	cmp.w	#KEY_SPACE,d0
	beq.s	.s
	cmp.w	#KEY_ESC,d0
	bne.s	.x
.s:	move.w	#1,StorySkip
.x:	movem.l	(sp)+,d0-d1
	rts

StoryLightning:
	subq.w	#1,Lightning
	bgt.s	.f
	move.w	#200,d0
	bsr	RandRange
	add.w	#120,d0
	move.w	d0,Lightning
	move.w	#10,FlashBg
	moveq	#V_THUNDER,d0
	bsr	PlayVoice
.f:	move.w	StoryBase,d0
	tst.w	FlashBg
	beq.s	.set
	subq.w	#1,FlashBg
	move.w	FlashBg,d1
	and.w	#2,d1
	bne.s	.set
	moveq	#21,d0
.set:	move.w	d0,BgFade
	rts

; StoryScene: d0 = page. 0: ghosts swoop over the city
; 1: the hunter walks in, a ghost appears and he blasts it  2: ghost swarm
StoryScene:
	movem.l	d0-d7/a0-a3,-(sp)
	move.w	d0,d7
	move.w	#10,FlashBg
	moveq	#V_THUNDER,d0
	bsr	PlayVoice
	cmp.w	#1,d7
	beq	.hunter
	; ghosts swooping across: 3 ghosts on sine paths
	moveq	#0,d6
.sw:	bsr	ClearDirty
	moveq	#2,d5
.g:	move.w	d6,d1
	lsl.w	#1,d1
	move.w	d5,d0
	mulu	#70,d0
	sub.w	d0,d1
	sub.w	#30,d1
	cmp.w	#2,d7
	bne.s	.dir
	neg.w	d1
	add.w	#320,d1
.dir:	move.w	d6,d0
	lsl.w	#2,d0
	add.w	d5,d0
	add.w	d5,d0
	and.w	#255,d0
	lea	SinTab,a0
	move.b	(a0,d0.w),d2
	ext.w	d2
	asr.w	#2,d2
	move.w	d5,d0
	mulu	#36,d0
	add.w	#80,d0
	add.w	d0,d2
	move.w	d5,d0
	lsl.w	#2,d0
	add.w	#BOB_G_NORMAL0,d0
	move.w	d6,d3
	lsr.w	#3,d3
	and.w	#3,d3
	add.w	d3,d0
	bsr	DrawBob
	dbf	d5,.g
	bsr	StoryFrame
	tst.w	StorySkip
	bne	.x
	addq.w	#1,d6
	cmp.w	#230,d6
	bne	.sw
	bra	.x
.hunter:
	; the hunter walks in from the left
	move.w	#-30,d4				; x
	moveq	#0,d6
.walk:	bsr	ClearDirty
	addq.w	#2,d4
	addq.w	#1,d6
	move.w	d6,d0
	lsr.w	#2,d0
	and.w	#3,d0
	addq.w	#1,d0
	move.w	d4,d1
	move.w	#PLAYER_Y,d2
	bsr	SetHunter
	bsr	StoryFrame
	tst.w	StorySkip
	bne	.x
	cmp.w	#120,d4
	blt.s	.walk
	; a ghost appears above him
	moveq	#0,d6
.app:	bsr	ClearDirty
	moveq	#0,d0
	move.w	d4,d1
	move.w	#PLAYER_Y,d2
	bsr	SetHunter
	move.w	d6,d0
	lsr.w	#3,d0
	and.w	#3,d0
	add.w	#BOB_G_NORMAL0,d0
	move.w	d4,d1
	add.w	#12,d1
	move.w	d6,d2
	add.w	#40,d2
	bsr	DrawBob
	bsr	StoryFrame
	tst.w	StorySkip
	bne	.x
	addq.w	#1,d6
	cmp.w	#60,d6
	bne.s	.app
	; and he blasts it
	moveq	#0,d6
.zap:	bsr	ClearDirty
	moveq	#5,d0
	move.w	d4,d1
	move.w	#PLAYER_Y,d2
	bsr	SetHunter
	move.w	d4,d0
	add.w	#GUN_DX-8,d0
	move.w	#118,d3
	bsr	DrawBeamCol
	move.w	d6,d0
	lsr.w	#2,d0
	cmp.w	#5,d0
	blt.s	.sp
	moveq	#4,d0
.sp:	add.w	#BOB_SPARK0,d0
	move.w	d4,d1
	add.w	#10,d1
	moveq	#98,d2
	bsr	DrawBob
	tst.w	SfxTicks
	bne.s	.nz
	moveq	#SFX_ZAP,d0
	bsr	PlaySfx
.nz:	bsr	StoryFrame
	tst.w	StorySkip
	bne.s	.x
	addq.w	#1,d6
	cmp.w	#40,d6
	bne.s	.zap
	moveq	#SFX_CATCH,d0
	bsr	PlaySfx
	moveq	#30,d6
.ch:	bsr	ClearDirty
	moveq	#6,d0
	move.w	d4,d1
	move.w	#PLAYER_Y,d2
	bsr	SetHunter
	bsr	StoryFrame
	tst.w	StorySkip
	bne.s	.x
	dbf	d6,.ch
.x:	bsr	HideHunter
	bsr	ClearBoth
	movem.l	(sp)+,d0-d7/a0-a3
	rts

;---------------------------------------------------------------------
; LoadingScreen: the 32 colour picture until a key or fire is pressed
;---------------------------------------------------------------------
LoadingScreen:
	movem.l	d0-d2/a0-a1,-(sp)
	bsr	FadeOut
	lea	LoadPic,a0
	lea	PF1Buf,a1
	bsr	UnpackBits
	move.l	#LoadPal,PicPal
	clr.l	PalKey
	move.w	#1,PicMode
	moveq	#V_TITLE,d0
	bsr	PlayVoice
	bsr	FadeIn
	clr.b	LastKey
	move.b	#$ff,LastKey
.l:	move.l	FrameCount,d0
	and.w	#32,d0
	sne	d0
	ext.w	d0
	move.w	d0,PicBlink
	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.go
	bsr	GetKey
	tst.w	d0
	bmi.s	.l
.go:	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	clr.w	PicBlink
	bsr	FadeOut
	clr.w	PicMode
	clr.l	PalKey
.fl:	bsr	GetKey				; forget the key that left the picture
	tst.w	d0
	bpl.s	.fl
	clr.w	JoyNew
	movem.l	(sp)+,d0-d2/a0-a1
	rts

;---------------------------------------------------------------------
; Flight: d0 = 0 Amsterdam -> New York, 1 = New York -> Amsterdam
;---------------------------------------------------------------------
AMS_X		equ	250
AMS_Y		equ	86
NY_X		equ	74
NY_Y		equ	104
Flight:
	movem.l	d0-d7/a0-a3,-(sp)
	move.w	d0,d7
	moveq	#6,d0
	bsr	NewScreen
	lea	TxtFlightTo,a0
	tst.w	d7
	beq.s	.t
	lea	TxtFlightHome,a0
.t:	moveq	#18,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	lea	TxtAmsNY,a0
	tst.w	d7
	beq.s	.t2
	lea	TxtNYAms,a0
.t2:	move.w	#232,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	; city labels and markers into the map (playfield 1)
	lea	TxtAmsterdam,a0
	moveq	#28,d0
	moveq	#96,d1
	moveq	#1,d2
	bsr	PrintPF1
	lea	TxtNewYork,a0
	moveq	#4,d0
	move.w	#114,d1
	bsr	PrintPF1
	move.w	#AMS_X,d0
	move.w	#AMS_Y,d1
	moveq	#7,d2
	bsr	MarkerPF1
	move.w	#NY_X,d0
	move.w	#NY_Y,d1
	bsr	MarkerPF1
	bsr	FadeIn
	moveq	#0,d6				; t = 0..255
.fly:	bsr	ClearDirty
	bsr	FlightPos			; d0,d1 = point on the arc
	move.w	d6,d3
	and.w	#5,d3
	bne.s	.nodot
	moveq	#2,d2
	bsr	PlotPF1
.nodot:	sub.w	#12,d0
	sub.w	#8,d1
	move.w	d1,d2
	move.w	d0,d1
	move.w	#BOB_PLANE_L,d0
	tst.w	d7
	beq.s	.pl
	move.w	#BOB_PLANE,d0
.pl:	bsr	DrawBob
	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.land
	addq.w	#1,d6
	cmp.w	#256,d6
	bne.s	.fly
.land:	lea	TxtLandedNY,a0
	tst.w	d7
	beq.s	.l2
	lea	TxtWelcomeHome,a0
.l2:	move.w	#204,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	moveq	#SFX_LIFE,d0
	bsr	PlaySfx
	move.w	#200,d0
	moveq	#0,d1
	bsr	WaitFire
	movem.l	(sp)+,d0-d7/a0-a3
	rts

; FlightPos: d6 = t (0..255), d7 = direction -> d0 x, d1 y
FlightPos:
	movem.l	d2-d3/a0,-(sp)
	move.w	d6,d2
	tst.w	d7
	beq.s	.d
	neg.w	d2
	add.w	#255,d2
.d:	move.w	#NY_X-AMS_X,d0
	muls	d2,d0
	asr.l	#8,d0
	add.w	#AMS_X,d0
	move.w	#NY_Y-AMS_Y,d1
	muls	d2,d1
	asr.l	#8,d1
	add.w	#AMS_Y,d1
	move.w	d2,d3
	lsr.w	#1,d3
	lea	SinTab,a0
	move.b	(a0,d3.w),d3
	ext.w	d3
	muls	#46,d3
	asr.l	#7,d3
	sub.w	d3,d1
	addq.w	#2,d0
	addq.w	#2,d1
	movem.l	(sp)+,d2-d3/a0
	rts

;---------------------------------------------------------------------
; MapScreen: d0 = from location, d1 = to location
;---------------------------------------------------------------------
MapScreen:
	movem.l	d0-d7/a0-a3,-(sp)
	move.w	d0,MapFrom
	move.w	d1,MapTo
	moveq	#5,d0
	bsr	NewScreen
	lea	TxtNextStop,a0
	moveq	#18,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	moveq	#0,d7
.m:	move.w	d7,d0
	bsr	MapXY
	moveq	#6,d2				; not yet visited
	cmp.w	MapTo,d7
	bgt.s	.mk
	moveq	#4,d2				; visited: green
	cmp.w	MapTo,d7
	bne.s	.mk
	moveq	#2,d2				; target: yellow
.mk:	cmp.w	MapTo,d7
	bgt.s	.mk2
	moveq	#7,d2
	cmp.w	MapTo,d7
	bne.s	.mk2
	moveq	#2,d2
.mk2:	bsr	MarkerPF1
	lea	LocNames,a0
	move.w	d7,d3
	lsl.w	#2,d3
	move.l	(a0,d3.w),a0
	lea	MapLabelPos,a1
	move.w	(a1,d3.w),d0
	move.w	2(a1,d3.w),d1
	moveq	#1,d2
	bsr	PrintPF1
	addq.w	#1,d7
	cmp.w	#NLEVELS,d7
	bne.s	.m
	lea	TxtHeading,a0
	move.w	#228,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	LocNames,a0
	move.w	MapTo,d0
	lsl.w	#2,d0
	move.l	(a0,d0.w),a0
	move.w	#238,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	bsr	FadeIn
	moveq	#0,d6				; t = 0..127
.drive:	bsr	ClearDirty
	move.w	MapFrom,d0
	bsr	MapXY
	move.w	d0,d4
	move.w	d1,d5
	move.w	MapTo,d0
	bsr	MapXY
	sub.w	d4,d0
	sub.w	d5,d1
	muls	d6,d0
	asr.l	#7,d0
	muls	d6,d1
	asr.l	#7,d1
	add.w	d4,d0
	add.w	d5,d1
	addq.w	#2,d0
	addq.w	#2,d1
	move.w	d6,d2
	and.w	#3,d2
	bne.s	.nt
	moveq	#2,d2
	bsr	PlotPF1
.nt:	sub.w	#9,d0
	subq.w	#5,d1
	move.w	d1,d2
	move.w	d0,d1
	move.w	#BOB_TAXI,d0
	bsr	DrawBob
	bsr	Frame
	addq.w	#1,d6
	cmp.w	#129,d6
	bne	.drive
	moveq	#SFX_LIFE,d0
	bsr	PlaySfx
	moveq	#50,d0
	moveq	#0,d1
	bsr	WaitFire
	bsr	FadeOut
	; "WELCOME TO ..."
	move.w	MapTo,d0
	lea	LevelScene,a0
	add.w	d0,d0
	move.w	(a0,d0.w),d0
	bsr	SetScene
	bsr	ClearBoth
	lea	TxtWelcomeTo,a0
	moveq	#80,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	LocNames,a0
	move.w	MapTo,d0
	lsl.w	#2,d0
	move.l	(a0,d0.w),a0
	moveq	#96,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	bsr	FadeIn
	move.w	#150,d0
	moveq	#2,d1
	bsr	WaitFire
	movem.l	(sp)+,d0-d7/a0-a3
	rts

; MapXY: d0 = location -> d0 x, d1 y
MapXY:
	move.l	a0,-(sp)
	lea	MapPos,a0
	lsl.w	#2,d0
	move.w	2(a0,d0.w),d1
	move.w	(a0,d0.w),d0
	move.l	(sp)+,a0
	rts

;---------------------------------------------------------------------
; LevelClear
;---------------------------------------------------------------------
LevelClear:
	movem.l	d0-d7/a0-a2,-(sp)
	moveq	#V_LEVEL,d0
	bsr	PlayVoice
	clr.w	LBoxTarget
	clr.w	LBox
	bsr	ClearBoth
	move.w	#7,BgFade
	lea	TxtLine,a0
	moveq	#40,d1
	moveq	#C_BLUE,d2
	bsr	PrintCentreBoth
	lea	TxtLevelCleared,a0
	move.w	Level,d0
	addq.w	#1,d0
	lea	6(a0),a0
	moveq	#2,d1
	bsr	PutNumW
	lea	TxtLevelCleared,a0
	moveq	#54,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtBusted,a0
	move.w	TotalCaught,d0
	lea	16(a0),a0
	moveq	#4,d1
