	moveq	#2,d0
	moveq	#50,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreLines
	move.w	#300,d0
	moveq	#1,d1
	bsr	WaitFire
	moveq	#1,d0
	bsr	Flight
	; mission complete
	moveq	#1,d0
	bsr	NewScreen
	move.w	#6,BgFade
	; lives bonus
	move.w	Lives,d0
	mulu	#1000,d0
	move.w	d0,LivesBonus
	ext.l	d0
	bsr	AddScore
