	move.l	Score,d0
	lea	15(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtMFinal,a0
	moveq	#10,d0
	move.w	#110,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBoth
	lea	TxtRank,a0
	move.w	#134,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtLegend,a0			; rank: lives lost against the starting lives
	move.w	LivesLost,d0
	beq.s	.rk
	lea	TxtHunter,a0
	move.w	Difficulty,d1
	add.w	d1,d1
	lea	StartLives,a1
	move.w	(a1,d1.w),d1
	lsr.w	#1,d1
	cmp.w	d1,d0
	ble.s	.rk
	lea	TxtRookie,a0
.rk:	move.w	#148,d1
	moveq	#C_GREEN,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtPressFire,a0
	move.w	#186,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	SongMain,a0
	bsr	PlaySong
	bsr	FadeIn
	moveq	#0,d0
	moveq	#1,d1
	bsr	WaitFire
	bsr	Credits
	movem.l	(sp)+,d0-d7/a0-a2
