; Fireworks: rockets bursting over the city (fire skips), about 5 seconds
Fireworks:
	movem.l	d0-d7/a0-a1,-(sp)
	moveq	#0,d6
	lea	FwState,a0
	moveq	#4*4-1,d0
.c:	clr.w	(a0)+
	dbf	d0,.c
.f:	bsr	ClearDirty
	lea	FwState,a0			; 4 rockets: x, y, frame, delay
	moveq	#3,d7
.r:	tst.w	6(a0)
	beq.s	.go
	subq.w	#1,6(a0)
	bne.s	.n
.go:	tst.w	4(a0)
	bne.s	.b
	; new rocket
	move.w	#250,d0
	bsr	RandRange
	add.w	#10,d0
	move.w	d0,(a0)
	moveq	#80,d0
	bsr	RandRange
	add.w	#30,d0
	move.w	d0,2(a0)
	move.w	#1,4(a0)
	move.w	#4,FlashBg
	moveq	#V_FIREWORK,d0
	bsr	PlayVoice
.b:	move.w	4(a0),d0
	addq.w	#1,4(a0)
	lsr.w	#2,d0
	cmp.w	#6,d0
	blt.s	.dr
	clr.w	4(a0)
	moveq	#14,d0
	bsr	RandRange
	addq.w	#2,d0
	move.w	d0,6(a0)
	bra.s	.n
.dr:	move.w	d7,d1
	add.w	d1,d1
	lea	FwBase,a1
	add.w	(a1,d1.w),d0
	move.w	(a0),d1
	move.w	2(a0),d2
	bsr	DrawBob
.n:	addq.l	#8,a0
	dbf	d7,.r
	moveq	#1,d0
	bsr	ScrollCity
	move.w	#12,BgFade
	tst.w	FlashBg
	beq.s	.nf
	subq.w	#1,FlashBg
	move.w	#16,BgFade			; a burst lights the city up
.nf:	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.x
	addq.w	#1,d6
	cmp.w	#280,d6
	bne	.f
.x:	move.w	#12,BgFade
	clr.w	FlashBg
	movem.l	(sp)+,d0-d7/a0-a1
	rts

Credits:
	movem.l	d0-d2/a0,-(sp)
	moveq	#1,d0
	bsr	NewScreen
	move.w	#6,BgFade
	lea	TxtCredits,a0
	moveq	#0,d0
	moveq	#24,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreLines
	bsr	FadeIn
	move.w	#1000,d0
	moveq	#1,d1
	bsr	WaitFire
	movem.l	(sp)+,d0-d2/a0
	rts

; PrintCentreLines: a0 = lines separated by 10, ending 0; d1 = y;
; lines starting with '*' are yellow, '+' green, others colour d2
PrintCentreLines:
	movem.l	d0-d4/a0-a1,-(sp)
	move.w	d2,d4
.l:	tst.b	(a0)
	beq.s	.x
	lea	TmpStr,a1
	move.w	d4,d2
	cmp.b	#'*',(a0)
	bne.s	.n1
	moveq	#C_YELLOW,d2
	addq.l	#1,a0
.n1:	cmp.b	#'+',(a0)
	bne.s	.c
	moveq	#C_GREEN,d2
	addq.l	#1,a0
.c:	move.b	(a0)+,d0
	beq.s	.end
	cmp.b	#10,d0
	beq.s	.end
	move.b	d0,(a1)+
	bra.s	.c
.end:	clr.b	(a1)
	move.l	a0,-(sp)
	lea	TmpStr,a0
	bsr	PrintCentreBoth
	move.l	(sp)+,a0
	add.w	#10,d1
	tst.b	-1(a0)
	bne.s	.l
.x:	movem.l	(sp)+,d0-d4/a0-a1
	rts

;---------------------------------------------------------------------
; High score check / name entry
;---------------------------------------------------------------------
HighScoreCheck:
	movem.l	d0-d7/a0-a3,-(sp)
	tst.w	Cheat				; test cheat: no Hall of Fame entry
	bne	.x
	; find rank
	lea	HiData+4,a0
	moveq	#0,d7
.f:	move.l	8(a0),d0
	cmp.l	Score,d0
	blt.s	.found
	lea	HI_ENTRY(a0),a0
	addq.w	#1,d7
	cmp.w	#10,d7
	bne.s	.f
	bra	.x
.found:	; shift entries down from the end
	lea	HiData+4+HI_ENTRY*9,a1		; last entry
	moveq	#9,d6
.sh:	cmp.w	d7,d6
	beq.s	.ins
	lea	-HI_ENTRY(a1),a2
	moveq	#HI_ENTRY-1,d0
.cp:	move.b	(a2,d0.w),(a1,d0.w)
	dbf	d0,.cp
	move.l	a2,a1
	subq.w	#1,d6
	bra.s	.sh
.ins:	move.l	a1,a3				; slot
	bsr	EnterName
	lea	NameBuf,a0
	moveq	#7,d0
.nm:	move.b	(a0)+,(a3)+
	dbf	d0,.nm
	move.l	Score,(a3)+
	move.w	Level,d0
	addq.w	#1,d0
	cmp.w	#NLEVELS,d0
	ble.s	.lv
	moveq	#NLEVELS,d0
.lv:	move.w	d0,(a3)+
	; save
	lea	TxtSaving,a0
	move.w	#210,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	bsr	Frame
	bsr	Frame
	bsr	SaveHighscores
	; show the table
	moveq	#1,d0
	bsr	NewScreen
	move.w	#6,BgFade
	bsr	DrawHallOfFame
	bsr	FadeIn
	move.w	#500,d0
	moveq	#1,d1
	bsr	WaitFire
.x:	movem.l	(sp)+,d0-d7/a0-a3
	rts

EnterName:
	movem.l	d0-d7/a0-a3,-(sp)
	moveq	#V_HISCORE,d0
	bsr	PlayVoice
	moveq	#1,d0
	bsr	NewScreen
	move.w	#7,BgFade
	lea	TxtNewHigh,a0
	moveq	#26,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtTop10List,a0
	moveq	#52,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtYourScore2,a0
	move.l	Score,d0
	lea	12(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtYourScore2,a0
	moveq	#66,d1
	moveq	#C_GREEN,d2
	bsr	PrintCentreBoth
	lea	TxtLevelReached,a0
	move.w	Level,d0
	addq.w	#1,d0
	cmp.w	#NLEVELS,d0
	ble.s	.l
	moveq	#NLEVELS,d0
.l:	lea	15(a0),a0
	moveq	#2,d1
	bsr	PutNumW
	lea	TxtLevelReached,a0
	moveq	#78,d1
	moveq	#C_GREEN,d2
	bsr	PrintCentreBoth
	lea	TxtEnterName,a0
	moveq	#100,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtNameHelp,a0
	moveq	#0,d0
	move.w	#150,d1
	moveq	#C_BLUE,d2
	bsr	PrintCentreLines
	; name buffer: 8 spaces, start with 'A'
	lea	NameBuf,a0
	moveq	#7,d0
.cl:	move.b	#' ',(a0)+
	dbf	d0,.cl
	clr.b	(a0)
	move.b	#'A',NameBuf
	clr.w	NamePos
	bsr	FadeIn
.loop:	; draw name (big) with cursor
	move.w	#80,d0
	moveq	#118,d1
	move.w	#160,d2
	moveq	#16,d3
	moveq	#0,d4
	move.l	BackBuf,a1
	bsr	FillRect
	lea	NameBuf,a0
	move.w	#96,d0
	moveq	#118,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBig
	; cursor underline
	move.l	FrameCount,d0
	and.w	#16,d0
	bne.s	.nc
	move.w	NamePos,d0
	lsl.w	#4,d0
	add.w	#96,d0
	move.w	#135,d1
	moveq	#16,d2
	moveq	#2,d3
	moveq	#C_WHITE,d4
	bsr	FillRect
.nc:	bsr	Frame
	; keyboard
	bsr	GetKey
	tst.w	d0
	bmi	.joy
	cmp.w	#KEY_RETURN,d0
	beq	.done
	cmp.w	#KEY_BACK,d0
	beq.s	.back
	cmp.w	#KEY_DEL,d0
	beq.s	.back
	cmp.w	#KEY_SPACE,d0
	bne.s	.ns
	moveq	#' ',d0
	bra.s	.put
.ns:	bsr	RawToAscii
	tst.w	d0
	beq.s	.joy
	cmp.b	#'A',d0
	blt.s	.dig
	cmp.b	#'Z',d0
	ble.s	.put
.dig:	cmp.b	#'0',d0
	blt.s	.joy
	cmp.b	#'9',d0
	bgt.s	.joy
.put:	move.w	NamePos,d1
	lea	NameBuf,a0
	move.b	d0,(a0,d1.w)
	cmp.w	#7,d1
	bge.s	.joy
	addq.w	#1,NamePos
	moveq	#SFX_MOVE,d0
	bsr	PlaySfx
	bra.s	.joy
.back:	move.w	NamePos,d1
	lea	NameBuf,a0
	move.b	#' ',(a0,d1.w)
	tst.w	d1
	beq.s	.joy
	subq.w	#1,NamePos
	move.w	NamePos,d1
	move.b	#' ',(a0,d1.w)
.joy:	move.w	JoyNew,d6
	move.w	NamePos,d1
	lea	NameBuf,a0
	move.b	(a0,d1.w),d0
	btst	#J_UP,d6
	beq.s	.nu
	bsr	NextChar
	move.b	d0,(a0,d1.w)
	moveq	#SFX_MOVE,d0
	bsr	PlaySfx
.nu:	btst	#J_DOWN,d6
	beq.s	.nd
	move.b	(a0,d1.w),d0
	bsr	PrevChar
	move.b	d0,(a0,d1.w)
	moveq	#SFX_MOVE,d0
	bsr	PlaySfx
.nd:	btst	#J_RIGHT,d6
	beq.s	.nr
	cmp.w	#7,d1
	bge.s	.nr
	addq.w	#1,NamePos
	move.w	NamePos,d1
	cmp.b	#' ',(a0,d1.w)
	bne.s	.nr
	move.b	#'A',(a0,d1.w)
.nr:	btst	#J_LEFT,d6
	beq.s	.nl
	tst.w	d1
	beq.s	.nl
	subq.w	#1,NamePos
.nl:	btst	#J_FIRE,d6
	beq	.loop
.done:	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	; empty name -> "NO NAME"
	lea	NameBuf,a0
	moveq	#7,d0
.e:	cmp.b	#' ',(a0)+
	bne.s	.ok
	dbf	d0,.e
	lea	NameBuf,a0
	lea	TxtNoName,a1
	moveq	#7,d0
.nn:	move.b	(a1)+,(a0)+
	dbf	d0,.nn
.ok:	movem.l	(sp)+,d0-d7/a0-a3
	rts

; letter cycling: A..Z, space, 0..9
NextChar:
	cmp.b	#'Z',d0
	bne.s	.1
	moveq	#' ',d0
	rts
.1:	cmp.b	#' ',d0
	bne.s	.2
	moveq	#'0',d0
	rts
.2:	cmp.b	#'9',d0
	bne.s	.3
	moveq	#'A',d0
	rts
.3:	addq.b	#1,d0
	rts
PrevChar:
	cmp.b	#'A',d0
	bne.s	.1
	moveq	#'9',d0
	rts
.1:	cmp.b	#'0',d0
	bne.s	.2
	moveq	#' ',d0
	rts
.2:	cmp.b	#' ',d0
	bne.s	.3
	moveq	#'Z',d0
	rts
.3:	subq.b	#1,d0
	rts

