	section	screenvars,bss
CheatPos:	ds.w	1
CheatHold:	ds.w	1
StorySkip:	ds.w	1
StoryBase:	ds.w	1
FwState:	ds.w	16
Page:		ds.w	1
PageTimer:	ds.w	1
MenuSel:	ds.w	1
MapFrom:	ds.w	1
MapTo:		ds.w	1
LivesBonus:	ds.w	1
NamePos:	ds.w	1
NameBuf:	ds.b	10

	section	code,code

;---------------------------------------------------------------------
; file: game.s
;---------------------------------------------------------------------
;=====================================================================
; game.s : the main game - player (hardware sprite), proton beam,
;          ghost types, slime, power-ups, a boss per place with
;          cinematic entrance and capture, weather, cheat, HUD, pause
;=====================================================================
NLEVELS		equ	5
CATCH_TARGET	equ	20
MAXGHOSTS	equ	8
MAXSLIME	equ	10
MAXPOP		equ	4
MAXRAIN		equ	14
PLAYER_Y	equ	201		; top of the 32 pixel hunter sprite
GUN_DX		equ	22		; beam x offset (facing right)
GUN_DXL		equ	9		; beam x offset (facing left)
ENERGY_MAX	equ	640

; ghost structure
G_ACTIVE	equ	0	; 0 free, 1 alive, 2 sparkle
G_TYPE		equ	2	; 0 normal 1 fast 2 splitter 3 dodger 4 mini
G_X16		equ	4
G_Y16		equ	6
G_VX		equ	8
G_BASEY		equ	10	; *16
G_PHASE		equ	12
G_PSPEED	equ	14
G_AMP		equ	16
G_TIMER		equ	18
G_BOB		equ	20
G_HITS		equ	22
G_DIVE		equ	24	; dodge cooldown
G_COOL		equ	26
G_W		equ	28
G_H		equ	30
GSIZE		equ	32

; slime / shot structure
S_ACTIVE	equ	0
S_KIND		equ	2	; 0 slime, 1 boss shot (homing), 2 boss shot (straight)
S_X16		equ	4
S_Y16		equ	6
S_VX		equ	8
S_VY		equ	10
SSIZE		equ	12

; popup structure
PO_TEXT		equ	0
PO_COL		equ	4
PO_Y		equ	6
PO_TIME		equ	8
PO_COLOUR	equ	10
POSIZE		equ	12

;---------------------------------------------------------------------
; PlayGame: full game from story to high score entry
;---------------------------------------------------------------------
PlayGame:
	movem.l	d0-d7/a0-a6,-(sp)
	clr.l	Score
	clr.w	Level
	clr.w	TotalCaught
	clr.w	BossesBeaten
	clr.w	LivesLost
	move.w	Difficulty,d0
	lea	StartLives,a0
	add.w	d0,d0
	move.w	(a0,d0.w),Lives
	bsr	Story
	moveq	#0,d0
	bsr	Flight
.level:	bsr	PlayLevel
	tst.w	d0
	bne.s	.notclear
	bsr	LevelClear
	addq.w	#1,Level
	cmp.w	#NLEVELS,Level
	beq.s	.won
	move.w	Level,d0
	subq.w	#1,d0
	move.w	Level,d1
	bsr	MapScreen
	bra.s	.level
.notclear:
	cmp.w	#2,d0
	beq.s	.quit
	bsr	GameOverScreen
	bra.s	.hi
.won:	bsr	Victory
.hi:	bsr	HighScoreCheck
.quit:	bsr	FadeOut
	clr.w	SprOn
	lea	SongMain,a0
	bsr	PlaySong
	movem.l	(sp)+,d0-d7/a0-a6
	rts

;---------------------------------------------------------------------
; PlayLevel: returns d0 = 0 cleared, 1 game over, 2 quit
;---------------------------------------------------------------------
PlayLevel:
	movem.l	d1-d7/a0-a6,-(sp)
	bsr	FadeOut
	move.w	#16,BgFade
	clr.w	LBox
	clr.w	LBoxTarget
	move.w	Level,d0
	bsr	SetScene
	bsr	ClearBoth
	bsr	ResetLevel
	move.w	#2,HudDirty
	bsr	DrawHud
	bsr	DrawHudBack2
	lea	SongMain,a0
	bsr	PlaySong
	move.w	#1,SprOn
	bsr	DrawPlayer
	bsr	FadeIn
	bsr	LevelIntro
	clr.w	LevelResult
.loop:	bsr	GameFrame
	tst.w	LevelDone
	beq.s	.loop
	clr.w	ShakeX
	clr.w	ShakeY
	clr.w	SkyFog
	move.w	LevelResult,d0
	movem.l	(sp)+,d1-d7/a0-a6
	rts

ResetLevel:
	movem.l	d0-d1/a0,-(sp)
	lea	Ghosts,a0
	move.w	#(GSIZE*MAXGHOSTS/2)-1,d0
.c1:	clr.w	(a0)+
	dbf	d0,.c1
	lea	Slimes,a0
	move.w	#(SSIZE*MAXSLIME/2)-1,d0
.c2:	clr.w	(a0)+
	dbf	d0,.c2
	lea	Popups,a0
	move.w	#(POSIZE*MAXPOP/2)-1,d0
.c3:	clr.w	(a0)+
	dbf	d0,.c3
	move.w	#140,PX
	clr.w	PFace
	clr.w	PAnim
	clr.w	PDead
	clr.w	PInv
	clr.w	PTwin
	move.w	#ENERGY_MAX,Energy
	clr.w	Overheat
	clr.w	Caught
	clr.w	Combo
	clr.w	ComboTimer
	clr.w	PowActive
	clr.w	BossState
	clr.w	TrapState
	clr.w	LevelDone
	clr.w	GameOverTimer
	clr.w	Firing
	clr.w	FlashCol
	clr.w	FlashTime
	clr.w	ShakeTime
	clr.w	FlashBg
	clr.w	SkyFog
	move.w	#60,SpawnTimer
	move.w	#200,Lightning
	; rain drops
	lea	RainX,a0
	moveq	#MAXRAIN-1,d0
.r:	move.w	d0,d1
	mulu	#23,d1
	add.w	#7,d1
	move.w	d1,(a0)+
	dbf	d0,.r
	lea	RainY,a0
	moveq	#MAXRAIN-1,d0
.ry:	move.w	d0,d1
	mulu	#61,d1
	and.w	#127,d1
	add.w	#20,d1
	move.w	d1,(a0)+
	dbf	d0,.ry
	; difficulty parameters
	move.w	Level,d0
	move.w	Difficulty,d1
	subq.w	#1,d1
	add.w	d1,d0				; effective level (-1..6)
	bpl.s	.ok
	moveq	#0,d0
.ok:	move.w	d0,EffLevel
	movem.l	(sp)+,d0-d1/a0
	rts

;---------------------------------------------------------------------
; LevelIntro: letterbox slides in, place name, "Get ready!", 3-2-1-GO!
;---------------------------------------------------------------------
LevelIntro:
	movem.l	d0-d7/a0-a3,-(sp)
	move.w	#28,LBoxTarget
	moveq	#V_READY,d0
	bsr	PlayVoice
	move.w	Level,d0
	lsl.w	#2,d0
	lea	LocNames,a0
	move.l	(a0,d0.w),a0
	moveq	#84,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtGetReady,a0
	moveq	#64,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	moveq	#60,d7
	bsr	IntroFrames
	moveq	#3,d6
.count:	move.w	#118,d0
	moveq	#18,d1
	move.l	BackBuf,a1
	bsr	ClearRows
	move.l	FrontBuf,a1
	bsr	ClearRows
	lea	CountStrs,a0
	move.w	d6,d0
	lsl.w	#2,d0
	move.l	(a0,d0.w),a0
	move.w	#120,d1
	moveq	#C_WHITE,d2
	tst.w	d6
	bne.s	.w
	moveq	#C_YELLOW,d2
.w:	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	lea	CountVoices,a0
	move.b	(a0,d6.w),d0
	ext.w	d0
	bsr	PlayVoice
	moveq	#45,d7
	tst.w	d6
	bne.s	.f
	move.w	#0,LBoxTarget
	moveq	#30,d7
.f:	bsr	IntroFrames
	dbf	d6,.count
	bsr	ClearBoth
	move.w	#2,HudDirty
	movem.l	(sp)+,d0-d7/a0-a3
	rts

; IntroFrames: d7 frames of city, weather and the standing hunter
IntroFrames:
.f:	moveq	#2,d0
	bsr	ScrollCity
	bsr	UpdateCine
	bsr	DrawPlayer
	bsr	DrawHud
	bsr	DrawEnergy
	bsr	Frame
	subq.w	#1,d7
	bgt.s	.f
	rts

;---------------------------------------------------------------------
; GameFrame: one frame of play
;---------------------------------------------------------------------
GameFrame:
	movem.l	d0-d7/a0-a6,-(sp)
	bsr	ClearDirty
	bsr	GameKeys
	tst.w	LevelDone
	bne	.x
	bsr	UpdatePlayer
	bsr	UpdateGhosts
	bsr	UpdateBoss
	bsr	UpdateSlimes
	bsr	UpdatePowerup
	bsr	UpdateTrap
	bsr	UpdatePopups
	bsr	UpdateCine
	moveq	#2,d0
	bsr	ScrollCity
	tst.w	FlashTime
	beq.s	.nf
	subq.w	#1,FlashTime
	bne.s	.nf
	clr.w	FlashCol
.nf:	bsr	DrawWeather
	bsr	DrawTrap
	bsr	DrawGhosts
	bsr	DrawBoss
	bsr	DrawPowerup
	bsr	DrawBeam
	bsr	DrawSlimes
	bsr	DrawPlayer
	bsr	DrawPopups
	bsr	DrawHud
	bsr	DrawEnergy
	bsr	Frame
	tst.w	GameOverTimer
	beq.s	.x
	subq.w	#1,GameOverTimer
	bne.s	.x
	move.w	#1,LevelResult
	move.w	#1,LevelDone
.x:	movem.l	(sp)+,d0-d7/a0-a6
	rts

; GameKeys: pause / music / cheat level skip
GameKeys:
	bsr	GetKey
	tst.w	d0
	bmi.s	.x
	cmp.w	#KEY_M,d0
	bne.s	.nm
	bsr	ToggleMusic
	bra.s	.x
.nm:	cmp.w	#KEY_N,d0
	bne.s	.nn
	tst.w	Cheat
	beq.s	.x
	clr.w	LevelResult			; cheat: N = next level
	move.w	#1,LevelDone
	bra.s	.x
.nn:	cmp.w	#KEY_P,d0
	beq.s	.p
	cmp.w	#KEY_ESC,d0
	bne.s	.x
.p:	bsr	PauseMenu
.x:	rts

ToggleMusic:
	eor.w	#1,MusicOn
	move.w	#2,HudDirty
	rts

;---------------------------------------------------------------------
; UpdateCine: screen shake, letterbox slide, background flashes,
; weather (rain / lightning / fog per place)
;---------------------------------------------------------------------
UpdateCine:
	movem.l	d0-d2/a0,-(sp)
	clr.w	ShakeX
	clr.w	ShakeY
	tst.w	ShakeTime
	beq.s	.ns
	subq.w	#1,ShakeTime
	moveq	#4,d0
	bsr	RandRange
	move.w	d0,ShakeX
	moveq	#3,d0
	bsr	RandRange
	move.w	d0,ShakeY
.ns:	; letterbox: 4 lines every other frame
	move.l	FrameCount,d0
	and.w	#1,d0
	bne.s	.nl
	move.w	LBox,d0
	cmp.w	LBoxTarget,d0
	beq.s	.nl
	blt.s	.lin
	subq.w	#4,LBox
	bra.s	.nl
.lin:	addq.w	#4,LBox
.nl:	; background flash (lightning, hits)
	move.w	#16,BgFade
	tst.w	FlashBg
	beq.s	.nb
	subq.w	#1,FlashBg
	move.w	FlashBg,d0
	and.w	#2,d0
	bne.s	.nb
	move.w	#21,BgFade
.nb:	; weather
	move.w	Level,d1
	lea	WeatherTab,a0
	move.b	(a0,d1.w),d1
	btst	#1,d1				; lightning
	beq.s	.nlt
	subq.w	#1,Lightning
	bgt.s	.nlt
	move.w	#220,d0
	bsr	RandRange
	add.w	#160,d0
	move.w	d0,Lightning
	move.w	#10,FlashBg
	tst.w	VoiceTicks
	bne.s	.nlt
	moveq	#V_THUNDER,d0
	bsr	PlayVoice
.nlt:	btst	#2,d1				; fog: slowly drifting
	beq.s	.nfog
	move.l	FrameCount,d0
	lsr.w	#2,d0
	and.w	#255,d0
	lea	SinTab,a0
	move.b	(a0,d0.w),d0
	ext.w	d0
	bpl.s	.fp
	moveq	#0,d0
.fp:	lsr.w	#4,d0				; 0..7
	addq.w	#2,d0
	move.w	d0,SkyFog
.nfog:	btst	#0,d1				; rain
	beq.s	.x
	lea	RainX,a0
	moveq	#MAXRAIN-1,d2
.rn:	move.w	MAXRAIN*2(a0),d0		; y
	addq.w	#7,d0
	cmp.w	#232,d0
	blt.s	.ry
	moveq	#20,d0
	move.w	(a0),d1
	add.w	#97,d1
	cmp.w	#316,d1
	blt.s	.rx
	sub.w	#316,d1
.rx:	move.w	d1,(a0)
.ry:	move.w	d0,MAXRAIN*2(a0)
	subq.w	#1,(a0)
	bpl.s	.rk
	add.w	#316,(a0)
.rk:	addq.l	#2,a0
	dbf	d2,.rn
.x:	movem.l	(sp)+,d0-d2/a0
	rts

DrawWeather:
	movem.l	d0-d3/a0,-(sp)
	move.w	Level,d1
	lea	WeatherTab,a0
	btst	#0,(a0,d1.w)
	beq.s	.x
	lea	RainX,a0
	moveq	#MAXRAIN-1,d3
.l:	move.w	#BOB_RAIN,d0
	move.w	(a0),d1
	move.w	MAXRAIN*2(a0),d2
	bsr	DrawBob
	addq.l	#2,a0
	dbf	d3,.l
.x:	movem.l	(sp)+,d0-d3/a0
	rts

;---------------------------------------------------------------------
; Player
;---------------------------------------------------------------------
UpdatePlayer:
	movem.l	d0-d7/a0-a2,-(sp)
	tst.w	PDead
	beq.s	.alive
	subq.w	#1,PDead
.alive:	tst.w	PInv
	beq.s	.ni
	subq.w	#1,PInv
.ni:	tst.w	PTwin
	beq.s	.nt
	subq.w	#1,PTwin
.nt:	clr.w	Firing
	tst.w	GameOverTimer
	bne	.nofire
	cmp.w	#7,BossState
	beq	.nofire
	; movement
	move.w	Joy,d2
	moveq	#0,d3
	btst	#J_LEFT,d2
	beq.s	.nl
	moveq	#-3,d3
	move.w	#1,PFace
.nl:	btst	#J_RIGHT,d2
	beq.s	.nr
	moveq	#3,d3
	clr.w	PFace
.nr:	move.w	PX,d0
	add.w	d3,d0
	cmp.w	#-6,d0
	bge.s	.c1
	moveq	#-6,d0
.c1:	cmp.w	#294,d0
	ble.s	.c2
	move.w	#294,d0
.c2:	move.w	d0,PX
	tst.w	d3
	beq.s	.stand
	addq.w	#1,PWalkT
	move.w	PWalkT,d0
	lsr.w	#2,d0
	and.w	#3,d0
	addq.w	#1,d0
	move.w	d0,PAnim
	bra.s	.anim
.stand:	clr.w	PAnim
.anim:	btst	#J_UP,JoyNew+1
	beq.s	.notrap
	bsr	DeployTrap
.notrap:
	btst	#J_FIRE,d2
	beq	.nofire
	tst.w	Overheat
	bne	.nofire
	cmp.w	#5,BossState			; no beam while trapping
	bge	.nofire
	cmp.w	#1,BossState
	beq.s	.f0
	cmp.w	#2,BossState
	beq.s	.nofire
	cmp.w	#3,BossState
	beq.s	.nofire
.f0:	move.w	#1,Firing
	move.w	#5,PAnim			; shooting frame
	tst.w	Cheat
	bne.s	.en				; cheat: the power never drains
	move.w	Difficulty,d0
	add.w	d0,d0
	lea	DrainTab,a0
	move.w	(a0,d0.w),d0
	sub.w	d0,Energy
	bgt.s	.en
	clr.w	Energy
	move.w	#1,Overheat
	lea	TxtRecharging,a0
	moveq	#C_YELLOW,d2
	bsr	AddMsg
	moveq	#SFX_BUZZ,d0
	bsr	PlaySfx
.en:	tst.w	SfxTicks
	bne.s	.done
	moveq	#SFX_ZAP,d0
	bsr	PlaySfx
	bra.s	.done
.nofire:
	move.w	Energy,d0
	addq.w	#2,d0
	cmp.w	#ENERGY_MAX,d0
	ble.s	.e1
	move.w	#ENERGY_MAX,d0
.e1:	move.w	d0,Energy
	tst.w	Overheat
	beq.s	.done
	cmp.w	#ENERGY_MAX/2,d0
	blt.s	.done
	clr.w	Overheat
.done:	tst.w	Firing
	beq.s	.x
	bsr	GunX
	bsr	BeamHit
	move.w	d0,BeamTop
	tst.w	PTwin
	beq.s	.x
	bsr	GunX
	sub.w	#10,d0
	bsr	BeamHit
	move.w	d0,BeamTop2
.x:	movem.l	(sp)+,d0-d7/a0-a2
	rts

; GunX -> d0 = x of the beam
GunX:
	move.w	PX,d0
	tst.w	PFace
	bne.s	.l
	add.w	#GUN_DX,d0
	rts
.l:	add.w	#GUN_DXL,d0
	rts

; BeamHit: d0 = beam centre x. Finds the lowest ghost (or boss) in the
; beam column, applies a hit and returns d0 = top y of the beam
BeamHit:
	movem.l	d1-d7/a0-a2,-(sp)
	move.w	d0,d7				; beam x
	moveq	#16,d6				; best bottom y (beam top)
	sub.l	a2,a2				; best ghost
	lea	Ghosts,a0
	moveq	#MAXGHOSTS-1,d5
.g:	cmp.w	#1,G_ACTIVE(a0)
	bne	.ng
	move.w	G_X16(a0),d0
	asr.w	#4,d0
	move.w	d7,d1
	sub.w	d0,d1
	; dodgers jump away when the beam comes close
	cmp.w	#3,G_TYPE(a0)
	bne.s	.nd
	tst.w	G_DIVE(a0)
	bne.s	.nd
	move.w	d1,d2
	sub.w	#10,d2
	bpl.s	.ab
	neg.w	d2
.ab:	cmp.w	#22,d2
	bgt.s	.nd
	move.w	#60,G_DIVE(a0)
	move.w	#40*16,d2
	cmp.w	#10,d1
	blt.s	.jr
	neg.w	d2
.jr:	add.w	d2,G_X16(a0)
	add.w	#53*16,G_PHASE(a0)
	bra.s	.ng
.nd:	cmp.w	#2,d1
	blt.s	.ng
	move.w	G_W(a0),d2
	subq.w	#2,d2
	cmp.w	d2,d1
	bgt.s	.ng
	move.w	G_Y16(a0),d0
	asr.w	#4,d0
	add.w	G_H(a0),d0			; bottom
	cmp.w	#PLAYER_Y+4,d0
	bge.s	.ng
	cmp.w	d6,d0
	ble.s	.ng
	move.w	d0,d6
	move.l	a0,a2
.ng:	lea	GSIZE(a0),a0
	dbf	d5,.g
	; boss
	cmp.w	#4,BossState
	bne.s	.noboss
	move.w	BX,d0
	addq.w	#8,d0
	cmp.w	d0,d7
	blt.s	.noboss
	add.w	#34,d0
	cmp.w	d0,d7
	bgt.s	.noboss
	move.w	BY,d0
	add.w	#40,d0
	cmp.w	d6,d0
	ble.s	.noboss
	move.w	d0,d6
	sub.l	a2,a2
	bsr	BossBeamHit
	bra.s	.ret
.noboss:
	move.l	a2,d0
	beq.s	.ret
	addq.w	#2,G_HITS(a2)
	move.w	Difficulty,d0
	add.w	d0,d0
	lea	CatchFrames,a0
	move.w	(a0,d0.w),d0
	cmp.w	G_HITS(a2),d0
	bgt.s	.ret
	move.l	a2,a0
	bsr	CatchGhost
.ret:	move.w	d6,d0
	movem.l	(sp)+,d1-d7/a0-a2
	rts

; CatchGhost: a0 = ghost
CatchGhost:
	movem.l	d0-d3/a0-a1,-(sp)
	cmp.w	#2,G_TYPE(a0)			; splitter: first hit only shrinks it
	bne.s	.real
	move.w	#4,G_TYPE(a0)
	clr.w	G_HITS(a0)
	move.w	#BOB_G_MINI0,G_BOB(a0)
	move.w	G_BOB(a0),d0
	bsr	BobSize
	move.w	d1,G_W(a0)
	move.w	d2,G_H(a0)
	move.w	G_VX(a0),d0
	add.w	d0,G_VX(a0)			; twice as fast
	add.w	#40*16,G_PHASE(a0)
	moveq	#5,d0
	bsr	AddScore
	moveq	#SFX_SPLIT,d0
	bsr	PlaySfx
	bra	.nb
.real:	move.w	#2,G_ACTIVE(a0)
	clr.w	G_TIMER(a0)
	addq.w	#1,Caught
	addq.w	#1,TotalCaught
	move.w	#2,HudDirty
	moveq	#SFX_CATCH,d0
	bsr	PlaySfx
	; combo: 10,20,30,40,50 points for quick hits
	tst.w	ComboTimer
	beq.s	.reset
	addq.w	#1,Combo
	cmp.w	#5,Combo
	ble.s	.cok
	move.w	#5,Combo
	bra.s	.cok
.reset:	move.w	#1,Combo
.cok:	move.w	Difficulty,d0
	add.w	d0,d0
	lea	ComboWin,a1
	move.w	(a1,d0.w),ComboTimer
	moveq	#10,d0
	mulu	Combo,d0
	bsr	AddScore
	cmp.w	#3,Combo
	bne.s	.nexc
	moveq	#V_EXCELLENT,d0
	bsr	PlayVoice
.nexc:	move.w	Combo,d1
	cmp.w	#1,d1
	bgt.s	.combo
	lea	TxtPlus10,a1
	bra.s	.pop
.combo:	lea	ComboTxt,a1
	add.b	#'0',d1
	move.b	d1,7(a1)
.pop:	move.w	G_X16(a0),d0
	asr.w	#4,d0
	move.w	G_Y16(a0),d1
	asr.w	#4,d1
	bsr	AddPopup
	tst.w	PowActive
	bne.s	.x
	moveq	#7,d0
	bsr	RandRange
	tst.w	d0
	bne.s	.x
	move.w	G_X16(a0),d0
	asr.w	#4,d0
	move.w	G_Y16(a0),d1
	asr.w	#4,d1
	bsr	SpawnPowerup
.x:	cmp.w	#CATCH_TARGET,Caught
	blt.s	.nb
	tst.w	BossState
	bne.s	.nb
	bsr	BossApproach
.nb:	movem.l	(sp)+,d0-d3/a0-a1
	rts

; AddScore: d0 = points
AddScore:
	add.l	d0,Score
	cmp.l	#99999,Score
	ble.s	.ok
	move.l	#99999,Score
.ok:	move.w	#2,HudDirty
	rts

; HitPlayer: slime / shot hit the player
HitPlayer:
	tst.w	Cheat				; cheat: slime does not hurt
	bne	.x
	tst.w	PDead
	bne	.x
	tst.w	PInv
	bne	.x
	tst.w	GameOverTimer
	bne	.x
	movem.l	d0/a0,-(sp)
	moveq	#SFX_SLIMED,d0
	bsr	PlaySfx
	moveq	#V_SLIMED,d0
	bsr	PlayVoice
	move.w	#$2a4,FlashCol
	move.w	#6,FlashTime
	move.w	#10,ShakeTime
	move.w	#150,PDead			; 3 seconds of invincibility
	subq.w	#1,Lives
	addq.w	#1,LivesLost
	move.w	#2,HudDirty
	lea	TxtSlimed,a0
	moveq	#C_GREEN,d2
	bsr	AddMsg
	tst.w	Lives
	bgt.s	.ok
	clr.w	Lives
	move.w	#150,GameOverTimer
	move.w	#24,LBoxTarget
	lea	SongLose,a0
	bsr	PlaySong
	moveq	#V_GAMEOVER,d0
	bsr	PlayVoice
.ok:	movem.l	(sp)+,d0/a0
.x:	rts

; DrawPlayer: position the hunter sprite
DrawPlayer:
	movem.l	d0-d2,-(sp)
	tst.w	PDead
	beq.s	.v
	move.w	PDead,d0
	and.w	#4,d0
	bne.s	.hide
.v:	tst.w	PInv
	beq.s	.v2
	move.w	PInv,d0
	cmp.w	#100,d0
	bgt.s	.v2
	and.w	#2,d0
	bne.s	.hide
.v2:	move.w	PAnim,d0
	tst.w	GameOverTimer
	beq.s	.d
	moveq	#0,d0
.d:	cmp.w	#7,BossState
	bne.s	.d2
	moveq	#6,d0
.d2:	tst.w	PFace
	beq.s	.d3
	addq.w	#7,d0
.d3:	move.w	PX,d1
	move.w	#PLAYER_Y,d2
	bsr	SetHunter
	bra.s	.x
.hide:	bsr	HideHunter
.x:	movem.l	(sp)+,d0-d2
	rts

;---------------------------------------------------------------------
; Beam
;---------------------------------------------------------------------
DrawBeam:
	tst.w	Firing
	beq.s	.x
	movem.l	d0-d3,-(sp)
	bsr	GunX
	subq.w	#8,d0
	move.w	BeamTop,d3
	bsr	DrawBeamCol
	tst.w	PTwin
	beq.s	.n2
	bsr	GunX
	sub.w	#18,d0
	move.w	BeamTop2,d3
	bsr	DrawBeamCol
.n2:	movem.l	(sp)+,d0-d3
.x:	rts

; DrawBeamCol: d0 = left x of 16px beam, d3 = top y
DrawBeamCol:
	movem.l	d0-d4,-(sp)
	move.w	ClipTop,-(sp)
	move.w	d3,ClipTop
	move.w	d0,d1
	move.w	#PLAYER_Y+4-16,d2
	move.l	FrameCount,d4
	and.w	#3,d4
.seg:	cmp.w	d3,d2
	blt.s	.last
	move.w	#BOB_BEAM0,d0
	add.w	d4,d0
	bsr	DrawBob
	sub.w	#16,d2
	addq.w	#1,d4
	and.w	#3,d4
	bra.s	.seg
.last:	move.w	d2,d0
	add.w	#16,d0
	cmp.w	d3,d0
	ble.s	.done
	move.w	#BOB_BEAM0,d0
	add.w	d4,d0
	bsr	DrawBob
.done:	move.w	(sp)+,ClipTop
	cmp.w	#17,d3
	blt.s	.ns
	move.l	FrameCount,d0
	and.w	#1,d0
	add.w	#BOB_SPARK0,d0
	subq.w	#4,d1
	move.w	d3,d2
	sub.w	#12,d2
	bsr	DrawBob
.ns:	movem.l	(sp)+,d0-d4
	rts

;---------------------------------------------------------------------
; Ghosts
;---------------------------------------------------------------------
UpdateGhosts:
	movem.l	d0-d7/a0-a2,-(sp)
	tst.w	ComboTimer
	beq.s	.ct
	subq.w	#1,ComboTimer
.ct:	tst.w	BossState
	bne.s	.nospawn
	subq.w	#1,SpawnTimer
	bgt.s	.nospawn
	move.w	EffLevel,d0
	mulu	#6,d0
	neg.w	d0
	add.w	#64,d0
	cmp.w	#22,d0
	bge.s	.st
	moveq	#22,d0
.st:	move.w	d0,SpawnTimer
	bsr	CountGhosts
	move.w	EffLevel,d1
	addq.w	#3,d1
	cmp.w	#7,d1
	ble.s	.mx
	moveq	#7,d1
.mx:	cmp.w	d1,d0
	bge.s	.nospawn
	bsr	SpawnGhost
.nospawn:
	lea	Ghosts,a2
	moveq	#MAXGHOSTS-1,d7
.g:	move.w	G_ACTIVE(a2),d0
	beq	.next
	cmp.w	#2,d0
	bne.s	.alive
	addq.w	#1,G_TIMER(a2)
	cmp.w	#20,G_TIMER(a2)
	blt	.next
	clr.w	G_ACTIVE(a2)
	bra	.next
.alive:	tst.w	G_HITS(a2)
	beq.s	.nh
	subq.w	#1,G_HITS(a2)
.nh:	tst.w	G_DIVE(a2)
	beq.s	.nd
	subq.w	#1,G_DIVE(a2)
.nd:	move.w	G_X16(a2),d0
	add.w	G_VX(a2),d0
	move.w	d0,G_X16(a2)
	asr.w	#4,d0
	cmp.w	#1,BossState			; fleeing when the boss comes
	bge.s	.flee
	tst.w	G_VX(a2)
	bmi.s	.left
	cmp.w	#296,d0
	blt.s	.vert
	neg.w	G_VX(a2)
	bra.s	.vert
.left:	cmp.w	#0,d0
	bgt.s	.vert
	neg.w	G_VX(a2)
	bra.s	.vert
.flee:	cmp.w	#-40,d0
	blt.s	.kill
	cmp.w	#340,d0
	bgt.s	.kill
	sub.w	#24,G_BASEY(a2)			; and up and away
	bra.s	.vert
.kill:	clr.w	G_ACTIVE(a2)
	bra	.next
.vert:	move.w	G_PHASE(a2),d0
	add.w	G_PSPEED(a2),d0
	move.w	d0,G_PHASE(a2)
	lsr.w	#4,d0
	and.w	#255,d0
	lea	SinTab,a0
	move.b	(a0,d0.w),d0
	ext.w	d0
	muls	G_AMP(a2),d0
	asr.l	#3,d0
	add.w	G_BASEY(a2),d0
	move.w	d0,G_Y16(a2)
	; slime dropping
	tst.w	G_COOL(a2)
	beq.s	.cool
	subq.w	#1,G_COOL(a2)
	bra	.next
.cool:	tst.w	BossState
	bne	.next
	move.w	G_X16(a2),d0
	asr.w	#4,d0
	add.w	#10,d0
	move.w	PX,d1
	add.w	#15,d1
	sub.w	d1,d0
	bpl.s	.ab
	neg.w	d0
.ab:	cmp.w	#40,d0
	bgt	.next
	move.w	#100,d0
	bsr	RandRange
	move.w	EffLevel,d1
	add.w	d1,d1
	addq.w	#3,d1
	cmp.w	d1,d0
	bge.s	.next
	move.w	#80,G_COOL(a2)
	move.w	G_X16(a2),d0
	asr.w	#4,d0
	move.w	G_W(a2),d1
	lsr.w	#1,d1
	add.w	d1,d0
	subq.w	#6,d0
	move.w	G_Y16(a2),d1
	asr.w	#4,d1
	add.w	G_H(a2),d1
	moveq	#0,d2
	moveq	#0,d3
	move.w	EffLevel,d4
	lsl.w	#2,d4
	add.w	#28,d4
	bsr	SpawnSlime
.next:	lea	GSIZE(a2),a2
	dbf	d7,.g
	movem.l	(sp)+,d0-d7/a0-a2
	rts

CountGhosts:
	movem.l	d1/a0,-(sp)
	moveq	#0,d0
	lea	Ghosts,a0
	moveq	#MAXGHOSTS-1,d1
.l:	tst.w	G_ACTIVE(a0)
	beq.s	.n
	addq.w	#1,d0
.n:	lea	GSIZE(a0),a0
	dbf	d1,.l
	movem.l	(sp)+,d1/a0
	rts

SpawnGhost:
	movem.l	d0-d3/a0-a1,-(sp)
	lea	Ghosts,a0
	moveq	#MAXGHOSTS-1,d1
.f:	tst.w	G_ACTIVE(a0)
	beq.s	.got
	lea	GSIZE(a0),a0
	dbf	d1,.f
	bra	.x
.got:	move.w	#1,G_ACTIVE(a0)
	clr.w	G_HITS(a0)
	clr.w	G_DIVE(a0)
	clr.w	G_TIMER(a0)
	move.w	#40,G_COOL(a0)
	; type from the table of this place
	moveq	#8,d0
	bsr	RandRange
	move.w	Level,d1
	lsl.w	#3,d1
	add.w	d1,d0
	lea	GhostTypes,a1
	moveq	#0,d1
	move.b	(a1,d0.w),d1
	move.w	d1,G_TYPE(a0)
	move.w	d1,d0
	lsl.w	#2,d0
	add.w	#BOB_G_NORMAL0,d0
	move.w	d0,G_BOB(a0)
	move.w	EffLevel,d2
	add.w	d2,d2
	add.w	#9,d2
	moveq	#8,d0
	bsr	RandRange
	add.w	d0,d2				; speed (1/16 px)
	cmp.w	#1,d1
	bne.s	.nf
	add.w	d2,d2				; fast ghost
.nf:	move.w	#10,G_AMP(a0)
	move.w	#40,G_PSPEED(a0)
	moveq	#2,d0
	bsr	RandRange
	tst.w	d0
	beq.s	.fromleft
	move.w	#320*16,G_X16(a0)
	neg.w	d2
	bra.s	.y
.fromleft:
	move.w	#-24*16,G_X16(a0)
.y:	move.w	d2,G_VX(a0)
	move.w	#110,d0
	bsr	RandRange
	add.w	#26,d0
	lsl.w	#4,d0
	move.w	d0,G_BASEY(a0)
	move.w	d0,G_Y16(a0)
	move.w	#4096,d0
	bsr	RandRange
	move.w	d0,G_PHASE(a0)
	move.w	G_BOB(a0),d0
	bsr	BobSize
	move.w	d1,G_W(a0)
	move.w	d2,G_H(a0)
.x:	movem.l	(sp)+,d0-d3/a0-a1
	rts

DrawGhosts:
	movem.l	d0-d7/a2,-(sp)
	lea	Ghosts,a2
	moveq	#MAXGHOSTS-1,d7
.g:	move.w	G_ACTIVE(a2),d3
	beq.s	.next
	move.w	G_X16(a2),d1
	asr.w	#4,d1
	move.w	G_Y16(a2),d2
	asr.w	#4,d2
	cmp.w	#2,d3
	bne.s	.alive
	move.w	G_TIMER(a2),d0
	lsr.w	#2,d0
	add.w	#BOB_SPARK0,d0
	subq.w	#2,d1
	subq.w	#2,d2
	bsr	DrawBob
	bra.s	.next
.alive:	move.w	G_PHASE(a2),d0			; wobble frame
	lsr.w	#8,d0
	and.w	#3,d0
	add.w	G_BOB(a2),d0
	tst.w	G_HITS(a2)
	beq.s	.dr
	move.l	FrameCount,d4
	and.w	#1,d4
	add.w	d4,d4
	subq.w	#1,d4
	add.w	d4,d1
.dr:	bsr	DrawBob
.next:	lea	GSIZE(a2),a2
	dbf	d7,.g
	movem.l	(sp)+,d0-d7/a2
	rts

;---------------------------------------------------------------------
; Boss.  BossState: 0 none 1 approaching 2 warning 3 entering 4 fighting
;                   5 stunned 6 being captured 7 captured
;---------------------------------------------------------------------
BossApproach:
	move.w	#1,BossState
	move.w	#160,BossTimer
	move.w	#28,LBoxTarget
	lea	TxtApproach,a0
	moveq	#C_BLUE,d2
	bsr	AddMsg
	bsr	StopMusic
	moveq	#V_THUNDER,d0
	bsr	PlayVoice
	move.w	#12,FlashBg
	rts

UpdateBoss:
	movem.l	d0-d7/a0-a2,-(sp)
	move.w	BossState,d0
	beq	.x
	cmp.w	#1,d0
	bne.s	.s2
	; approaching: the ground rumbles more and more
	move.w	BossTimer,d0
	cmp.w	#110,d0
	bgt.s	.r1
	move.w	#2,ShakeTime
.r1:	cmp.w	#60,d0
	bne.s	.r2
	move.w	#10,FlashBg
	moveq	#V_THUNDER,d0
	bsr	PlayVoice
.r2:	subq.w	#1,BossTimer
	bgt	.x
	move.w	#2,BossState
	move.w	#150,BossTimer
	moveq	#V_WARNING,d0
	bsr	PlayVoice
	bra	.x
.s2:	cmp.w	#2,d0
	bne	.s3
	subq.w	#1,BossTimer
	move.w	BossTimer,d0
	and.w	#31,d0
	bne.s	.nw
	moveq	#SFX_WARN,d0
	bsr	PlaySfx
.nw:	tst.w	BossTimer
	bgt	.x
	move.w	#3,BossState
	move.w	#160,BossTimer
	move.w	#136,BX
	move.w	#18,BY
	move.w	#2,BVX
	move.w	Level,d0
	add.w	d0,d0
	lea	BossHP,a0
	move.w	(a0,d0.w),BHP
	clr.w	BHitTimer
	clr.w	BHitAcc
	move.w	#100,BAttackTimer
	clr.w	BAttack
	clr.w	BPhase
	move.w	#2,HudDirty
	moveq	#V_LAUGH,d0
	bsr	PlayVoice
	bra	.x
.s3:	cmp.w	#3,d0
	bne.s	.s4
	; entering: grows from far away while coming closer
	move.w	#1,ShakeTime
	move.l	FrameCount,d0
	and.w	#3,d0
	bne.s	.ny
	cmp.w	#40,BY
	bge.s	.ny
	addq.w	#1,BY
.ny:	subq.w	#1,BossTimer
	bgt	.x
	move.w	#4,BossState
	move.w	#40,BY
	clr.w	LBoxTarget
	move.w	#8,ShakeTime
	moveq	#V_FIGHT,d0
	bsr	PlayVoice
	lea	SongBoss,a0
	bsr	PlaySong
	lea	TxtReadyFight,a0
	moveq	#C_YELLOW,d2
	bsr	AddMsg
	bra	.x
.s4:	cmp.w	#4,d0
	bne	.s5
	tst.w	BHitTimer
	beq.s	.nht
	subq.w	#1,BHitTimer
.nht:	bsr	BossMove
	subq.w	#1,BAttackTimer
	bgt	.x
	bsr	BossAttack
	move.w	Level,d0
	lea	BossInt,a0
	moveq	#0,d1
	move.b	(a0,d0.w),d1
	mulu	#3,d1				; frames between attacks
	moveq	#30,d0
	bsr	RandRange
	add.w	d1,d0
	move.w	EffLevel,d1
	lsl.w	#2,d1
	sub.w	d1,d0
	cmp.w	#40,d0
	bge.s	.ai
	moveq	#40,d0
.ai:	move.w	d0,BAttackTimer
	bra	.x
.s5:	cmp.w	#5,d0
	bne	.s6
	cmp.w	#100,BY
	bge.s	.sunk
	addq.w	#1,BY
.sunk:	addq.w	#1,BPhase
	move.w	BPhase,d0
	and.w	#3,d0
	bne.s	.nd
	move.w	BVX,d0
	add.w	d0,BX
	cmp.w	#16,BX
	bgt.s	.b1
	move.w	#1,BVX
.b1:	cmp.w	#252,BX
	blt.s	.nd
	move.w	#-1,BVX
.nd:	subq.w	#1,BStun
	bgt	.x
	move.w	#1,BHP
	move.w	#4,BossState
	move.w	#2,HudDirty
	move.w	#40,BY
	lea	TxtRecovered,a0
	moveq	#C_BLUE,d2
	bsr	AddMsg
	bra	.x
.s6:	cmp.w	#6,d0
	bne	.s7
	; sucked into the trap, shrinking on the way
	move.w	#2,ShakeTime
	move.w	TrapX,d0
	sub.w	#12,d0
	cmp.w	BX,d0
	beq.s	.cx
	blt.s	.cl
	addq.w	#1,BX
	bra.s	.cx
.cl:	subq.w	#1,BX
.cx:	addq.w	#2,BY
	cmp.w	#196,BY
	blt	.x
	move.w	#7,BossState
	move.w	#240,BossTimer
	move.w	#3,TrapState
	move.w	#24,ShakeTime
	move.w	#14,FlashBg
	move.w	#28,LBoxTarget
	moveq	#V_EXPLODE,d0
	bsr	PlayVoice
	moveq	#SFX_TRAP,d0
	bsr	PlaySfx
	addq.w	#1,BossesBeaten
	move.w	#100,d0
	bsr	AddScore
	lea	SongWin,a0
	bsr	PlaySong
	bra.s	.x
.s7:	subq.w	#1,BossTimer
	cmp.w	#190,BossTimer
	bne.s	.ng
	moveq	#V_GOTCHA,d0
	bsr	PlayVoice
.ng:	tst.w	BossTimer
	bgt.s	.x
	clr.w	LevelResult
	move.w	#1,LevelDone
.x:	movem.l	(sp)+,d0-d7/a0-a2
	rts

BossMove:
	move.w	BVX,d0
	add.w	d0,BX
	cmp.w	#8,BX
	bgt.s	.l
	move.w	#2,BVX
	tst.w	EffLevel
	beq.s	.l
	move.w	#3,BVX
.l:	cmp.w	#262,BX
	blt.s	.r
	move.w	#-2,BVX
	tst.w	EffLevel
	beq.s	.r
	move.w	#-3,BVX
.r:	addq.w	#3,BPhase
	move.w	BPhase,d0
	and.w	#255,d0
	lea	SinTab,a0
	move.b	(a0,d0.w),d0
	ext.w	d0
	asr.w	#3,d0
	add.w	#40,d0
	move.w	d0,BY
	rts

; BossBeamHit: beam touches the boss this frame
BossBeamHit:
	tst.w	BHitTimer
	bne	.x
	addq.w	#2,BHitAcc
	cmp.w	#14,BHitAcc
	blt.s	.x
	clr.w	BHitAcc
	move.w	#50,BHitTimer
	moveq	#SFX_BOSSHIT,d0
	bsr	PlaySfx
	move.w	#8,ShakeTime
	move.w	#4,FlashBg
	moveq	#20,d0
	bsr	AddScore
	move.w	#2,HudDirty
	subq.w	#1,BHP
	bgt.s	.x
	clr.w	BHP
	move.w	#5,BossState
	move.w	#600,BStun
	move.w	#1,BVX
	lea	TxtStunned,a0
	moveq	#C_YELLOW,d2
	bsr	AddMsg
	lea	TxtStandUnder,a0
	moveq	#C_WHITE,d2
	bsr	AddMsg2
	moveq	#V_STUNNED,d0
	bsr	PlayVoice
.x:	rts

; BossAttack: the next attack from this place's list
; (0 homing  1 spread  2 sniper  3 pincer)
BossAttack:
	movem.l	d0-d6/a0,-(sp)
	move.w	BX,d0
	add.w	#20,d0
	move.w	BY,d1
	add.w	#40,d1
	move.w	Level,d6
	lsl.w	#3,d6
	add.w	BAttack,d6
	addq.w	#1,BAttack
	and.w	#7,BAttack
	lea	BossPat,a0
	move.b	(a0,d6.w),d6
	ext.w	d6
	tst.w	d6
	bne.s	.a1
	moveq	#1,d2				; homing
	moveq	#0,d3
	moveq	#22,d4
	bsr	SpawnSlime
	bra	.x
.a1:	cmp.w	#1,d6
	bne.s	.a2
	moveq	#2,d2				; spread
	moveq	#28,d4
	moveq	#-18,d3
	bsr	SpawnSlime
	moveq	#0,d3
	bsr	SpawnSlime
	moveq	#18,d3
	bsr	SpawnSlime
	bra.s	.x
.a2:	cmp.w	#2,d6
	bne.s	.a3
	moveq	#2,d2				; sniper: fast, aimed at the player
	moveq	#64,d4
	move.w	PX,d3
	add.w	#12,d3
	sub.w	d0,d3
	asl.w	#4,d3
	ext.l	d3
	divs	#40,d3
	bsr	SpawnSlime
	bra.s	.x
.a3:	moveq	#1,d2				; pincer: one homing + one straight down
	moveq	#0,d3
	moveq	#24,d4
	sub.w	#14,d0
	bsr	SpawnSlime
	moveq	#2,d2
	add.w	#28,d0
	moveq	#36,d4
	bsr	SpawnSlime
.x:	movem.l	(sp)+,d0-d6/a0
	rts

DrawBoss:
	movem.l	d0-d4/a0,-(sp)
	move.w	BossState,d4
	cmp.w	#3,d4
	blt	.x
	cmp.w	#7,d4
	beq	.x
	move.w	Level,d0
	mulu	#6,d0
	add.w	#BOB_BOSS_BLOB,d0		; normal, hit, stun, s1, s2, s3
	move.w	BX,d1
	move.w	BY,d2
	cmp.w	#3,d4
	bne.s	.n3
	; entering: small, smaller ... full size
	move.w	BossTimer,d3
	cmp.w	#40,d3
	blt.s	.full
	addq.w	#3,d0				; s1 (far)
	cmp.w	#120,d3
	bgt.s	.sc
	addq.w	#1,d0				; s2
	cmp.w	#80,d3
	bgt.s	.sc
	addq.w	#1,d0				; s3
.sc:	; keep the small boss centred
	move.w	BossTimer,d3
	lsr.w	#3,d3
	add.w	d3,d1
	add.w	d3,d2
	bra.s	.d
.full:	bra.s	.d
.n3:	cmp.w	#6,d4
	bne.s	.n6
	addq.w	#2,d0				; stunned look while sucked in
	move.w	BY,d3
	cmp.w	#120,d3
	blt.s	.d
	addq.w	#3,d0				; s3
	add.w	#6,d1
	add.w	#6,d2
	cmp.w	#150,d3
	blt.s	.d
	subq.w	#1,d0				; s2
	addq.w	#6,d1
	addq.w	#6,d2
	cmp.w	#175,d3
	blt.s	.d
	subq.w	#1,d0				; s1
	addq.w	#6,d1
	addq.w	#4,d2
	bra.s	.d
.n6:	tst.w	BHitTimer
	beq.s	.nh
	move.w	BHitTimer,d3
	and.w	#4,d3
	beq.s	.nh
	addq.w	#1,d0				; hit flash
.nh:	cmp.w	#5,d4
	bne.s	.d
	addq.w	#2,d0				; stunned
.d:	bsr	DrawBob
	; dizzy stars around a stunned boss
	cmp.w	#5,d4
	bne.s	.x
	moveq	#2,d4
.st:	move.l	FrameCount,d3
	lsl.w	#2,d3
	move.w	d4,d0
	mulu	#85,d0
	add.w	d0,d3
	and.w	#255,d3
	lea	SinTab,a0
	move.b	(a0,d3.w),d1
	ext.w	d1
	asr.w	#3,d1
	add.w	BX,d1
	add.w	#22,d1
	add.w	#64,d3
	and.w	#255,d3
	move.b	(a0,d3.w),d2
	ext.w	d2
	asr.w	#5,d2
	add.w	BY,d2
	move.w	#BOB_STAR,d0
	bsr	DrawBob
	dbf	d4,.st
.x:	movem.l	(sp)+,d0-d4/a0
	rts

;---------------------------------------------------------------------
; Slime and boss shots
; SpawnSlime: d0 = x, d1 = y, d2 = kind, d3 = vx (1/16), d4 = vy (1/16)
;---------------------------------------------------------------------
SpawnSlime:
	movem.l	d5/a0,-(sp)
	lea	Slimes,a0
	moveq	#MAXSLIME-1,d5
.f:	tst.w	S_ACTIVE(a0)
	beq.s	.got
	lea	SSIZE(a0),a0
	dbf	d5,.f
	bra.s	.x
.got:	move.w	#1,S_ACTIVE(a0)
	move.w	d2,S_KIND(a0)
	lsl.w	#4,d0
	move.w	d0,S_X16(a0)
	lsr.w	#4,d0
	lsl.w	#4,d1
	move.w	d1,S_Y16(a0)
	lsr.w	#4,d1
	move.w	d3,S_VX(a0)
	move.w	d4,S_VY(a0)
	move.l	d0,-(sp)
	moveq	#SFX_DROP,d0
	tst.w	d2
	beq.s	.s
	moveq	#SFX_SHOOT,d0
.s:	tst.w	Firing
	bne.s	.ns
	bsr	PlaySfx
.ns:	move.l	(sp)+,d0
.x:	movem.l	(sp)+,d5/a0
	rts

UpdateSlimes:
	movem.l	d0-d7/a0,-(sp)
	lea	Slimes,a0
	moveq	#MAXSLIME-1,d7
.s:	tst.w	S_ACTIVE(a0)
	beq	.next
	cmp.w	#1,S_KIND(a0)
	bne.s	.move
	; homing: steer towards the player
	move.w	PX,d0
	add.w	#12,d0
	lsl.w	#4,d0
	cmp.w	S_X16(a0),d0
	blt.s	.hl
	cmp.w	#20,S_VX(a0)
	bge.s	.move
	addq.w	#1,S_VX(a0)
	bra.s	.move
.hl:	cmp.w	#-20,S_VX(a0)
	ble.s	.move
	subq.w	#1,S_VX(a0)
.move:	move.w	S_X16(a0),d0
	add.w	S_VX(a0),d0
	move.w	d0,S_X16(a0)
	move.w	S_Y16(a0),d1
	add.w	S_VY(a0),d1
	move.w	d1,S_Y16(a0)
	asr.w	#4,d0
	asr.w	#4,d1
	cmp.w	#236,d1
	blt.s	.on
	clr.w	S_ACTIVE(a0)
	bra.s	.next
.on:	cmp.w	#-16,d0
	blt.s	.off
	cmp.w	#330,d0
	bgt.s	.off
	; collide with the player box (px+5 .. px+19, y 205..232)
	move.w	PX,d2
	addq.w	#3,d2
	cmp.w	d2,d0
	blt.s	.next
	add.w	#16,d2
	cmp.w	d2,d0
	bgt.s	.next
	cmp.w	#PLAYER_Y+2,d1
	blt.s	.next
	clr.w	S_ACTIVE(a0)
	bsr	HitPlayer
	bra.s	.next
.off:	clr.w	S_ACTIVE(a0)
.next:	lea	SSIZE(a0),a0
	dbf	d7,.s
	movem.l	(sp)+,d0-d7/a0
	rts

DrawSlimes:
	movem.l	d0-d7/a0,-(sp)
	lea	Slimes,a0
	moveq	#MAXSLIME-1,d7
.s:	tst.w	S_ACTIVE(a0)
	beq.s	.next
	move.w	S_X16(a0),d1
	asr.w	#4,d1
	move.w	S_Y16(a0),d2
	asr.w	#4,d2
	move.l	FrameCount,d0
	lsr.w	#3,d0
	and.w	#1,d0
	add.w	#BOB_SLIME0,d0
	tst.w	S_KIND(a0)
	beq.s	.d
	move.w	#BOB_BSHOT,d0
	cmp.w	#1,S_KIND(a0)
	bne.s	.d
	move.w	#BOB_BSHOT2,d0
.d:	bsr	DrawBob
.next:	lea	SSIZE(a0),a0
	dbf	d7,.s
	movem.l	(sp)+,d0-d7/a0
	rts

;---------------------------------------------------------------------
; Power-ups: d0 = x, d1 = y
;---------------------------------------------------------------------
SpawnPowerup:
	movem.l	d0-d2,-(sp)
	move.w	#1,PowActive
	move.w	d0,PowX
	lsl.w	#4,d1
	move.w	d1,PowY16
	moveq	#10,d0
	bsr	RandRange
	moveq	#3,d2				; star (extra life) 10%
	cmp.w	#9,d0
	beq.s	.s
	moveq	#3,d0
	bsr	RandRange
	move.w	d0,d2
.s:	move.w	d2,PowType
	movem.l	(sp)+,d0-d2
	rts

UpdatePowerup:
	movem.l	d0-d2/a0,-(sp)
	tst.w	PowActive
	beq	.x
	add.w	#20,PowY16
	move.w	PowY16,d1
	asr.w	#4,d1
	cmp.w	#222,d1
	blt.s	.fall
	clr.w	PowActive			; landed - lost
	bra	.x
.fall:	cmp.w	#PLAYER_Y-16,d1
	blt	.x
	move.w	PowX,d0
	sub.w	PX,d0
	cmp.w	#-12,d0
	blt	.x
	cmp.w	#26,d0
	bgt	.x
	; collected
	clr.w	PowActive
	move.w	PowType,d0
	bne.s	.n0
	move.w	#500,PInv
	lea	TxtInvincible,a0
	bra.s	.msg
.n0:	cmp.w	#1,d0
	bne.s	.n1
	move.w	#ENERGY_MAX,Energy
	clr.w	Overheat
	lea	TxtFullPower,a0
	bra.s	.msg
.n1:	cmp.w	#2,d0
	bne.s	.n2
	move.w	#750,PTwin
	lea	TxtTwin,a0
	bra.s	.msg
.n2:	cmp.w	#9,Lives
	bge.s	.n3
	addq.w	#1,Lives
.n3:	move.w	#2,HudDirty
	lea	TxtExtraLife,a0
	moveq	#SFX_LIFE,d0
	bsr	PlaySfx
	moveq	#V_EXTRALIFE,d0
	bsr	PlayVoice
	moveq	#C_YELLOW,d2
	bsr	AddMsg
	moveq	#50,d0
	bsr	AddScore
	bra.s	.x
.msg:	moveq	#C_YELLOW,d2
	bsr	AddMsg
	moveq	#SFX_POWER,d0
	bsr	PlaySfx
	moveq	#V_POWERUP,d0
	bsr	PlayVoice
	moveq	#25,d0
	bsr	AddScore
.x:	movem.l	(sp)+,d0-d2/a0
	rts

DrawPowerup:
	tst.w	PowActive
	beq.s	.x
	movem.l	d0-d2,-(sp)
	move.w	#BOB_PW_INV,d0
	add.w	PowType,d0
	move.w	PowX,d1
	move.w	PowY16,d2
	asr.w	#4,d2
	bsr	DrawBob
	movem.l	(sp)+,d0-d2
.x:	rts

;---------------------------------------------------------------------
; Trap: TrapState 0 none, 1 open + beam, 2 closing, 3 closed (boss caught)
;---------------------------------------------------------------------
DeployTrap:
	cmp.w	#5,BossState
	bne.s	.x
	tst.w	TrapState
	bne.s	.x
	move.w	#1,TrapState
	move.w	#70,TrapTimer
	move.w	PX,TrapX
	addq.w	#2,TrapX
	moveq	#SFX_TRAP,d0
	bsr	PlaySfx
.x:	rts

UpdateTrap:
	movem.l	d0-d2,-(sp)
	move.w	TrapState,d0
	beq	.x
	cmp.w	#1,d0
	bne.s	.s2
	; capture check: boss centre above the trap
	cmp.w	#5,BossState
	bne.s	.nc
	cmp.w	#80,BY
	blt.s	.nc
	move.w	BX,d0
	add.w	#24,d0
	move.w	TrapX,d1
	add.w	#12,d1
	sub.w	d1,d0
	bpl.s	.ab
	neg.w	d0
.ab:	cmp.w	#26,d0
	bgt.s	.nc
	move.w	#6,BossState
	move.w	#2,HudDirty
	bra.s	.x
.nc:	cmp.w	#6,BossState
	beq.s	.x
	subq.w	#1,TrapTimer
	bgt.s	.x
	move.w	#2,TrapState
	move.w	#30,TrapTimer
	bra.s	.x
.s2:	cmp.w	#2,d0
	bne.s	.x
	subq.w	#1,TrapTimer
	bgt.s	.x
	clr.w	TrapState
.x:	movem.l	(sp)+,d0-d2
	rts

DrawTrap:
	movem.l	d0-d4,-(sp)
	move.w	TrapState,d4
	beq	.x
	move.w	TrapX,d1
	move.w	#218,d2
	move.w	#BOB_TRAP_CLOSED,d0
	cmp.w	#1,d4
	bne.s	.d
	move.w	#BOB_TRAP_OPEN,d0
	bsr	DrawBob
	; capture beam
	move.w	TrapX,d1
	subq.w	#4,d1
	move.w	ClipTop,-(sp)
	move.w	BY,d3
	add.w	#20,d3
	cmp.w	#6,BossState
	beq.s	.tb
	cmp.w	#5,BossState
	beq.s	.tb
	move.w	#120,d3
.tb:	move.w	d3,ClipTop
	move.w	#202,d2
	move.l	FrameCount,d4
	lsr.w	#2,d4
	and.w	#1,d4
.seg:	move.w	#BOB_TBEAM0,d0
	add.w	d4,d0
	bsr	DrawBob
	sub.w	#16,d2
	move.w	d2,d0
	add.w	#16,d0
	cmp.w	d3,d0
	bgt.s	.seg
	move.w	(sp)+,ClipTop
	bra.s	.x
.d:	bsr	DrawBob
.x:	movem.l	(sp)+,d0-d4
	rts

;---------------------------------------------------------------------
; Popups (floating text) and centre messages
; AddPopup: a1 = text, d0 = x, d1 = y ; AddMsg: a0 = text, d2 = colour
;---------------------------------------------------------------------
AddPopup:
	movem.l	d0-d3/a0,-(sp)
	lea	Popups+POSIZE*2,a0		; slots 2,3 for small popups
	moveq	#1,d3
.f:	tst.w	PO_TIME(a0)
	beq.s	.got
	lea	POSIZE(a0),a0
	dbf	d3,.f
	lea	Popups+POSIZE*2,a0
.got:	move.l	a1,PO_TEXT(a0)
	lsr.w	#3,d0
	bpl.s	.c0
	moveq	#0,d0
.c0:	cmp.w	#32,d0
	ble.s	.c1
	moveq	#32,d0
.c1:	move.w	d0,PO_COL(a0)
	cmp.w	#24,d1
	bge.s	.y
	moveq	#24,d1
.y:	move.w	d1,PO_Y(a0)
	move.w	#40,PO_TIME(a0)
	move.w	#C_YELLOW,PO_COLOUR(a0)
	movem.l	(sp)+,d0-d3/a0
	rts

AddMsg:	movem.l	d0-d1/a1,-(sp)
	lea	Popups,a1
	move.w	#84,d1
	bra.s	AddMsgC
AddMsg2:
	movem.l	d0-d1/a1,-(sp)
	lea	Popups+POSIZE,a1
	move.w	#98,d1
AddMsgC:
	move.l	a0,PO_TEXT(a1)
	bsr	CentreCol
	move.w	d0,PO_COL(a1)
	move.w	d1,PO_Y(a1)
	move.w	#150,PO_TIME(a1)
	move.w	d2,PO_COLOUR(a1)
	movem.l	(sp)+,d0-d1/a1
	rts

UpdatePopups:
	movem.l	d0-d1/a0,-(sp)
	lea	Popups,a0
	moveq	#MAXPOP-1,d0
.l:	tst.w	PO_TIME(a0)
	beq.s	.n
	subq.w	#1,PO_TIME(a0)
	cmp.l	#Popups+POSIZE*2,a0
	blt.s	.n
	move.l	FrameCount,d1
	and.w	#1,d1
	sub.w	d1,PO_Y(a0)
.n:	lea	POSIZE(a0),a0
	dbf	d0,.l
	movem.l	(sp)+,d0-d1/a0
	rts

;---------------------------------------------------------------------
; Popups, boss banner, boss name card, capture title
;---------------------------------------------------------------------
DrawPopups:
	movem.l	d0-d3/a0-a2,-(sp)
	lea	Popups,a2
	moveq	#MAXPOP-1,d3
.l:	tst.w	PO_TIME(a2)
	beq.s	.n
	move.l	PO_TEXT(a2),a0
	move.w	PO_COL(a2),d0
	move.w	PO_Y(a2),d1
	move.w	PO_COLOUR(a2),d2
	move.l	BackBuf,a1
	bsr	Print
.n:	lea	POSIZE(a2),a2
	dbf	d3,.l
	move.l	BackBuf,a1
	move.w	BossState,d0
	cmp.w	#2,d0
	bne.s	.n2
	move.l	FrameCount,d0
	and.w	#16,d0
	beq	.x
	lea	TxtWarning,a0
	moveq	#76,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBigCentre
	lea	TxtBossIncoming,a0
	move.w	#102,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBack
	bra	.x
.n2:	cmp.w	#3,d0
	bne.s	.n3
	; name card in the bottom letterbox bar
	cmp.w	#24,LBox
	blt.s	.x
	move.w	Level,d0
	lea	BossNames,a0
	lsl.w	#2,d0
	move.l	(a0,d0.w),a0
	move.w	#226,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBigCentre
	bra.s	.x
.n3:	cmp.w	#7,d0
	bne.s	.n4
	cmp.w	#24,LBox
	blt.s	.x
	lea	TxtCaptured,a0
	move.w	#226,d1
	moveq	#C_YELLOW,d2
	bsr	PrintBigCentre
	; burst of sparks around the trap
	move.w	BossTimer,d0
	cmp.w	#200,d0
	blt.s	.x
	bsr	CaptureBurst
	bra.s	.x
.n4:	tst.w	GameOverTimer
	beq.s	.x
	cmp.w	#24,LBox
	blt.s	.x
	lea	TxtGameOver2,a0
	move.w	#226,d1
	moveq	#C_WHITE,d2
	bsr	PrintBigCentre
.x:	movem.l	(sp)+,d0-d3/a0-a2
	rts

CaptureBurst:
	movem.l	d0-d4/a0,-(sp)
	move.w	#240,d4
	sub.w	BossTimer,d4			; 0..40
	moveq	#7,d3
.l:	move.w	d3,d0
	lsl.w	#5,d0
	lea	SinTab,a0
	move.b	(a0,d0.w),d1
	ext.w	d1
	muls	d4,d1
	asr.l	#6,d1
	add.w	TrapX,d1
	add.w	#2,d1
	add.w	#64,d0
	and.w	#255,d0
	move.b	(a0,d0.w),d2
	ext.w	d2
	muls	d4,d2
	asr.l	#6,d2
	add.w	#200,d2
	move.w	d4,d0
	lsr.w	#3,d0
	add.w	#BOB_SPARK0,d0
	bsr	DrawBob
	dbf	d3,.l
	movem.l	(sp)+,d0-d4/a0
	rts

;---------------------------------------------------------------------
; HUD
;---------------------------------------------------------------------
DrawHudBack2:
	move.w	#2,HudDirty
	rts

DrawHud:
	tst.w	HudDirty
	beq	.x
	subq.w	#1,HudDirty
	movem.l	d0-d7/a0-a2,-(sp)
	move.l	BackBuf,a1
	moveq	#0,d0
	moveq	#0,d1
	move.w	#320,d2
	moveq	#16,d3
	moveq	#0,d4
	bsr	FillRect
	move.w	#248,d1
	moveq	#8,d3
	bsr	FillRect
	lea	EnergyShownA,a0
	cmp.l	#PF2BufA,BackBuf
	beq.s	.ea
	lea	EnergyShownB,a0
.ea:	move.w	#-1,(a0)
	; lives
	lea	TmpStr,a0
	move.w	Lives,d0
	cmp.w	#7,d0
	ble.s	.lv
	moveq	#7,d0
.lv:	subq.w	#1,d0
	bmi.s	.nolives
.hl:	move.b	#$7e,(a0)+
	dbf	d0,.hl
.nolives:
	clr.b	(a0)
	lea	TmpStr,a0
	moveq	#0,d0
	moveq	#0,d1
	moveq	#C_YELLOW,d2
	bsr	Print
	; title or the cheat label next to the lives
	lea	TxtHudTitle,a0
	moveq	#11,d0
	moveq	#C_WHITE,d2
	tst.w	Cheat
	beq.s	.nc
	lea	TxtCheatOn,a0
	moveq	#8,d0
	moveq	#C_YELLOW,d2
	move.l	FrameCount,d3
	and.w	#32,d3
	beq.s	.nc
	moveq	#C_GREEN,d2
.nc:	bsr	Print
	lea	TxtCaught,a0
	move.w	Caught,d0
	cmp.w	#CATCH_TARGET,d0
	ble.s	.cc
	moveq	#CATCH_TARGET,d0
.cc:	lea	7(a0),a0
	moveq	#2,d1
	bsr	PutNumW
	lea	TxtCaught,a0
	moveq	#0,d0
	moveq	#8,d1
	moveq	#C_GREEN,d2
	bsr	Print
	cmp.w	#4,BossState
	blt.s	.loc
	cmp.w	#6,BossState
	bge.s	.loc
	lea	TxtBossHP,a0
	move.w	BHP,d0
	add.b	#'0',d0
	move.b	d0,8(a0)
	moveq	#16,d0
	moveq	#8,d1
	moveq	#C_YELLOW,d2
	bsr	Print
	bra.s	.mus
.loc:	move.w	Level,d0
	lsl.w	#2,d0
	lea	HudLocNames,a0
	move.l	(a0,d0.w),a0
	moveq	#16,d0
	moveq	#8,d1
	moveq	#C_BLUE,d2
	bsr	Print
.mus:	lea	TxtMusicOn,a0
	tst.w	MusicOn
	bne.s	.mo
	lea	TxtMusicOff,a0
.mo:	moveq	#31,d0
	moveq	#8,d1
	moveq	#C_MAGENTA,d2
	bsr	Print
	lea	TxtBottom,a0
	move.l	Score,d0
	lea	6(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtBottom,a0
	move.l	HiData+4+8,d0
	cmp.l	Score,d0
	bge.s	.hs
	move.l	Score,d0
.hs:	lea	17(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtBottom,a0
	move.w	Level,d0
	addq.w	#1,d0
	lea	33(a0),a0
	moveq	#2,d1
	bsr	PutNumW
	lea	TxtBottom,a0
	moveq	#1,d0
	move.w	#248,d1
	moveq	#C_WHITE,d2
	bsr	Print
	movem.l	(sp)+,d0-d7/a0-a2
.x:	rts

DrawEnergy:
	movem.l	d0-d5/a0-a1,-(sp)
	move.w	Energy,d3
	tst.w	Cheat
	beq.s	.nch
	move.w	#ENERGY_MAX,d3
.nch:	ext.l	d3
	divu	#10,d3
	and.w	#$fff8,d3
	tst.w	Overheat
	beq.s	.no
	bset	#15,d3
.no:	lea	EnergyShownA,a0
	cmp.l	#PF2BufA,BackBuf
	beq.s	.a
	lea	EnergyShownB,a0
.a:	cmp.w	(a0),d3
	beq	.skip
	move.w	d3,(a0)
	bclr	#15,d3
	move.w	#248,d0
	moveq	#1,d1
	moveq	#64,d2
	moveq	#C_GREEN,d4
	tst.w	Overheat
	beq.s	.c
	moveq	#C_MAGENTA,d4
.c:	moveq	#C_DARK,d5
	move.l	BackBuf,a1
	bsr	Bar
.skip:	movem.l	(sp)+,d0-d5/a0-a1
	rts

;---------------------------------------------------------------------
; Pause menu
;---------------------------------------------------------------------
PauseMenu:
	movem.l	d0-d7/a0-a2,-(sp)
	move.w	#6,BgFade
	move.w	LBox,-(sp)
	clr.w	LBox
	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
.redraw:
	bsr	ClearBoth
	move.w	#2,HudDirty
	bsr	DrawHud
	bsr	CopyBuffers
	lea	TxtPaused,a0
	moveq	#56,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	lea	TxtPScore,a0
	move.l	Score,d0
	lea	6(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtPScore,a0
	move.l	HiData+4+8,d0
	cmp.l	Score,d0
	bge.s	.b
	move.l	Score,d0
.b:	lea	18(a0),a0
	moveq	#5,d1
	bsr	PutNum
	lea	TxtPScore,a0
	moveq	#80,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtPLives,a0
	move.w	Lives,d0
	lea	6(a0),a0
	moveq	#1,d1
	bsr	PutNumW
	lea	TxtPLives,a0
	move.w	Level,d0
	addq.w	#1,d0
	lea	16(a0),a0
	moveq	#1,d1
	bsr	PutNumW
	lea	TxtPLives,a0
	moveq	#92,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtPCaught,a0
	move.w	TotalCaught,d0
	lea	14(a0),a0
	moveq	#4,d1
	bsr	PutNumW
	lea	TxtPCaught,a0
	moveq	#104,d1
	moveq	#C_GREEN,d2
	bsr	PrintCentreBoth
	lea	TxtPHelp,a0
	moveq	#9,d0
	moveq	#124,d1
	moveq	#C_BLUE,d2
	bsr	PrintBoth
	lea	TxtPKeys,a0
	move.w	#166,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
.loop:	bsr	Frame
	bsr	GetKey
	tst.w	d0
	bmi.s	.loop
	cmp.w	#KEY_P,d0
	beq.s	.resume
	cmp.w	#KEY_ESC,d0
	beq.s	.resume
	cmp.w	#KEY_M,d0
	bne.s	.nm
	bsr	ToggleMusic
	bra	.redraw
.nm:	cmp.w	#KEY_Q,d0
	bne.s	.loop
	lea	TxtQuitQ,a0
	move.w	#184,d1
	moveq	#C_MAGENTA,d2
	bsr	PrintCentreBoth
.q:	bsr	Frame
	bsr	GetKey
	cmp.w	#KEY_Y,d0
	beq.s	.quit
	cmp.w	#KEY_N,d0
	beq	.redraw
	cmp.w	#KEY_ESC,d0
	beq	.redraw
	bra.s	.q
.quit:	move.w	#2,LevelResult
	move.w	#1,LevelDone
.resume:
	move.w	(sp)+,LBox
	move.w	#16,BgFade
	bsr	ClearBoth
	move.w	#2,HudDirty
	clr.w	Joy
	movem.l	(sp)+,d0-d7/a0-a2
	rts

