;---------------------------------------------------------------------
; file: bonus.s
;---------------------------------------------------------------------
;=====================================================================
; bonus.s : bonus games - Slime Dodge, Ghost Whack, Memory Ghosts,
;           Ghost Invaders
;=====================================================================
BEST_BASE	equ	HiData+4+HI_ENTRY*10	; 4 words

BonusMenu:
	movem.l	d0-d7/a0-a3,-(sp)
	clr.w	BonusSel
.redraw:
	moveq	#4,d0
	bsr	NewScreen
	move.w	#7,BgFade
	bsr	DrawBonusMenu
	bsr	FadeIn
.loop:	moveq	#1,d0
	bsr	ScrollCity
	bsr	Frame
	bsr	GetKey
	cmp.w	#KEY_ESC,d0
	beq	.back
	move.w	d0,d7
	move.w	JoyNew,d6
	btst	#J_UP,d6
	beq.s	.nu
	subq.w	#1,BonusSel
	bpl.s	.mv
	move.w	#4,BonusSel
	bra.s	.mv
.nu:	btst	#J_DOWN,d6
	beq.s	.nd
	addq.w	#1,BonusSel
	cmp.w	#5,BonusSel
	blt.s	.mv
	clr.w	BonusSel
.mv:	moveq	#SFX_MOVE,d0
	bsr	PlaySfx
	bsr	DrawBonusItems
	bra.s	.loop
.nd:	btst	#J_FIRE,d6
	bne.s	.sel
	cmp.w	#KEY_RETURN,d7
	beq.s	.sel
	cmp.w	#KEY_SPACE,d7
	bne.s	.loop
.sel:	moveq	#SFX_SELECT,d0
	bsr	PlaySfx
	move.w	BonusSel,d0
	cmp.w	#4,d0
	beq.s	.back
.again:	move.w	BonusSel,d0
	bsr	RunBonus			; d0 = score
	; best?
	lea	BEST_BASE,a0
	move.w	BonusSel,d1
	add.w	d1,d1
	tst.w	Cheat				; no bests in cheat mode
	bne.s	.nobest
	cmp.w	(a0,d1.w),d0
	bls.s	.nobest
	move.w	d0,(a0,d1.w)
	move.w	#1,NewBest
	bra.s	.res
.nobest:
	clr.w	NewBest
.res:	bsr	BonusResult			; d0 = 1 again, 0 menu
	tst.w	NewBest
	beq.s	.ns
	bsr	SaveHighscores
.ns:	tst.w	d0
	bne.s	.again
	lea	SongMain,a0
	bsr	PlaySong
	bra	.redraw
.back:	movem.l	(sp)+,d0-d7/a0-a3
	rts

RunBonus:
	movem.l	d1-d7/a0-a6,-(sp)
	tst.w	d0
	bne.s	.1
	bsr	SlimeDodge
	bra.s	.x
.1:	cmp.w	#1,d0
	bne.s	.2
	bsr	GhostWhack
	bra.s	.x
.2:	cmp.w	#2,d0
	bne.s	.3
	bsr	MemoryGhosts
	bra.s	.x
.3:	bsr	GhostInvaders
.x:	movem.l	(sp)+,d1-d7/a0-a6
	rts

DrawBonusMenu:
	lea	TxtBonusTitle,a0
	moveq	#22,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtBonusKeys,a0
	move.w	#236,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	bsr	DrawBonusItems
	rts

DrawBonusItems:
	movem.l	d0-d7/a0-a2,-(sp)
	moveq	#0,d7
	moveq	#52,d6
	lea	BonusNames,a2
.l:	moveq	#0,d0
	move.w	d6,d1
	move.w	#320,d2
	moveq	#20,d3
	moveq	#0,d4
	move.l	BackBuf,a1
	bsr	FillRect
	move.l	FrontBuf,a1
	bsr	FillRect
	move.l	(a2)+,a0
	moveq	#C_WHITE,d2
	cmp.w	BonusSel,d7
	bne.s	.c
	moveq	#C_YELLOW,d2
.c:	move.w	d6,d1
	bsr	PrintCentreBoth
	cmp.w	#4,d7
	beq.s	.n
	move.l	(a2)+,a0			; description
	move.w	d6,d1
	add.w	#10,d1
	moveq	#C_BLUE,d2
	bsr	PrintCentreBoth
	; best
	lea	TxtBest,a0
	lea	BEST_BASE,a1
	move.w	d7,d0
	add.w	d0,d0
	move.w	(a1,d0.w),d0
	lea	5(a0),a0
	moveq	#4,d1
	bsr	PutNumW
	lea	TxtBest,a0
	moveq	#30,d0
	move.w	d6,d1
	moveq	#C_GREEN,d2
	bsr	PrintBoth
.n:	add.w	#34,d6
	addq.w	#1,d7
	cmp.w	#5,d7
	bne	.l
	movem.l	(sp)+,d0-d7/a0-a2
	rts

; BonusResult: shows "FIRE: AGAIN   ESC: MENU" and waits. returns d0 = 1 again
BonusResult:
	movem.l	d1-d2/a0,-(sp)
	lea	TxtAgain,a0
	move.w	#184,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	tst.w	NewBest
	beq.s	.w
	lea	TxtNewBest,a0
	move.w	#170,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
.w:	clr.w	JoyNew
	moveq	#30,d0
.pause:	bsr	Frame
	dbf	d0,.pause
.l:	bsr	Frame
	btst	#J_FIRE,JoyNew+1
	bne.s	.again
	bsr	GetKey
	cmp.w	#KEY_SPACE,d0
	beq.s	.again
	cmp.w	#KEY_RETURN,d0
	beq.s	.again
	cmp.w	#KEY_ESC,d0
	bne.s	.l
	moveq	#0,d0
	bra.s	.x
.again:	moveq	#1,d0
.x:	movem.l	(sp)+,d1-d2/a0
	rts

; BonusHud: a0 = title, prints title on row 0 and TmpStr on row 8 (both buffers)
BonusHeader:
	movem.l	d0-d4/a0-a1,-(sp)
	moveq	#0,d0
	moveq	#0,d1
	move.w	#320,d2
	moveq	#16,d3
	moveq	#0,d4
	move.l	BackBuf,a1
	bsr	FillRect
	moveq	#0,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBack
	lea	TmpStr,a0
	moveq	#8,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBack
	movem.l	(sp)+,d0-d4/a0-a1
	rts

; CopyStr: a0 src -> TmpStr
CopyStr:
	movem.l	a0-a1,-(sp)
	lea	TmpStr,a1
.c:	move.b	(a0)+,(a1)+
	bne.s	.c
	movem.l	(sp)+,a0-a1
	rts

;---------------------------------------------------------------------
; 1. SLIME DODGE - survive the falling slime.  score = time in 1/10 s
;---------------------------------------------------------------------
SlimeDodge:
	moveq	#4,d0
	bsr	NewScreen
	bsr	ResetLevel
	move.w	#1,Lives
	move.w	#1,Overheat
	clr.w	Energy
	clr.w	BTime
	move.w	#40,BSpawn
	clr.w	BCount
	lea	SongMain,a0
	bsr	PlaySong
	bsr	FadeIn
.loop:	bsr	ClearDirty
	bsr	GetKey
	; spawn slime
	subq.w	#1,BSpawn
	bgt.s	.ns
	move.w	BTime,d0
	lsr.w	#4,d0
	neg.w	d0
	add.w	#34,d0
	cmp.w	#7,d0
	bge.s	.sp
	moveq	#7,d0
.sp:	move.w	d0,BSpawn
	move.w	#304,d0
	bsr	RandRange
	moveq	#16,d1
	moveq	#0,d2
	moveq	#0,d3
	move.w	BTime,d4
	lsr.w	#5,d4
	add.w	#24,d4
	cmp.w	#80,d4
	ble.s	.vy
	moveq	#80,d4
.vy:	bsr	SpawnSlime
.ns:	bsr	UpdatePlayer
	move.w	#1,Overheat
	bsr	UpdateSlimes
	bsr	UpdatePopups
	bsr	DrawSlimes
	bsr	DrawPlayer
	bsr	DrawPopups
	tst.w	GameOverTimer
	bne.s	.dead
	move.l	FrameCount,d0
	divu	#5,d0
	swap	d0
	tst.w	d0
	bne.s	.hud
	addq.w	#1,BTime
.hud:	lea	TxtSDHud,a0
	bsr	CopyStr
	lea	TmpStr+5,a0
	move.w	BTime,d0
	moveq	#4,d1
	bsr	PutNumW
	lea	TmpStr+18,a0
	move.w	BEST_BASE,d0
	bsr	PutNumW
	lea	TxtSlimeDodge,a0
	bsr	BonusHeader
	bsr	Frame
	bra	.loop
.dead:	; slimed
	clr.w	GameOverTimer
	clr.w	FlashCol
	clr.w	FlashTime
	bsr	ClearBoth
	lea	TxtGotSlimed,a0
	moveq	#80,d1
	moveq	#C_GREEN,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtSDHud,a0
	bsr	CopyStr
	lea	TmpStr+5,a0
	move.w	BTime,d0
	moveq	#4,d1
	bsr	PutNumW
	lea	TmpStr+18,a0
	move.w	BEST_BASE,d0
	cmp.w	BTime,d0
	bhs.s	.b
	move.w	BTime,d0
.b:	bsr	PutNumW
	lea	TmpStr,a0
	move.w	#120,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	move.w	BTime,d0
	rts

;---------------------------------------------------------------------
; 2. GHOST WHACK - zap ghosts in the windows. score = hits (of 30)
;---------------------------------------------------------------------
GW_X0	equ	40
GW_Y0	equ	48
GhostWhack:
	moveq	#3,d0
	bsr	NewScreen
	clr.w	BHits
	move.w	#30,BCount			; ghosts left
	clr.w	CurX
	clr.w	CurY
	move.w	#-1,GhostWin
	move.w	#30,BSpawn
	lea	SongMain,a0
	bsr	PlaySong
	bsr	FadeIn
.loop:	bsr	ClearDirty
	bsr	GetKey
	; cursor movement
	move.w	JoyNew,d6
	btst	#J_LEFT,d6
	beq.s	.nl
	tst.w	CurX
	beq.s	.nl
	subq.w	#1,CurX
.nl:	btst	#J_RIGHT,d6
	beq.s	.nr
	cmp.w	#3,CurX
	beq.s	.nr
	addq.w	#1,CurX
.nr:	btst	#J_UP,d6
	beq.s	.nu
	tst.w	CurY
	beq.s	.nu
	subq.w	#1,CurY
.nu:	btst	#J_DOWN,d6
	beq.s	.nd
	cmp.w	#2,CurY
	beq.s	.nd
	addq.w	#1,CurY
.nd:	; ghost timing
	tst.w	GhostWin
	bpl.s	.active
	subq.w	#1,BSpawn
	bgt.s	.fire
	tst.w	BCount
	beq	.end
	moveq	#12,d0
	bsr	RandRange
	move.w	d0,GhostWin
	moveq	#4,d0
	bsr	RandRange
	lsl.w	#2,d0
	add.w	#BOB_G_NORMAL0,d0
	move.w	d0,GhostBob
	move.w	BCount,d0
	add.w	d0,d0
	add.w	#24,d0				; visible time shrinks
	move.w	d0,GhostTime
	clr.w	GhostHit
	subq.w	#1,BCount
	bra.s	.fire
.active:
	subq.w	#1,GhostTime
	bgt.s	.fire
	move.w	#-1,GhostWin
	move.w	#12,BSpawn
.fire:	btst	#J_FIRE,d6
	beq.s	.draw
	move.w	CurY,d0
	lsl.w	#2,d0
	add.w	CurX,d0
	cmp.w	GhostWin,d0
	bne.s	.miss
	tst.w	GhostHit
	bne.s	.draw
	move.w	#1,GhostHit
	move.w	#14,GhostTime
	addq.w	#1,BHits
	moveq	#SFX_CATCH,d0
	bsr	PlaySfx
	bra.s	.draw
.miss:	moveq	#SFX_BUZZ,d0
	bsr	PlaySfx
.draw:	; windows
	moveq	#11,d7
.w:	move.w	d7,d0
	bsr	WinXY
	move.w	#BOB_WINDOW,d0
	bsr	DrawBob
	dbf	d7,.w
	; ghost
	move.w	GhostWin,d0
	bmi.s	.nog
	bsr	WinXY
	addq.w	#8,d1
	addq.w	#6,d2
	move.w	GhostBob,d0
	tst.w	GhostHit
	beq.s	.g
	move.w	GhostTime,d0
	lsr.w	#2,d0
	neg.w	d0
	addq.w	#3,d0
	and.w	#3,d0
	add.w	#BOB_SPARK0,d0
.g:	bsr	DrawBob
.nog:	; cursor
	move.w	CurY,d0
	lsl.w	#2,d0
	add.w	CurX,d0
	bsr	WinXY
	addq.w	#8,d1
	addq.w	#4,d2
	move.w	#BOB_CROSS,d0
	bsr	DrawBob
	; header
	lea	TxtGWHud,a0
	bsr	CopyStr
	lea	TmpStr+5,a0
	move.w	BHits,d0
	moveq	#2,d1
	bsr	PutNumW
	lea	TmpStr+14,a0
	move.w	BCount,d0
	bsr	PutNumW
	lea	TmpStr+23,a0
	move.w	BEST_BASE+2,d0
	bsr	PutNumW
	lea	TxtGhostWhack,a0
	bsr	BonusHeader
	bsr	Frame
	bra	.loop
.end:	bsr	ClearBoth
	lea	TxtGWResult,a0
	bsr	CopyStr
	lea	TmpStr+7,a0
	move.w	BHits,d0
	moveq	#2,d1
	bsr	PutNumW
	lea	TmpStr+22,a0
	move.w	BEST_BASE+2,d0
	cmp.w	BHits,d0
	bhs.s	.b
	move.w	BHits,d0
.b:	bsr	PutNumW
	lea	TmpStr,a0
	moveq	#80,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	lea	TxtKeepPract,a0
	move.w	BHits,d0
	cmp.w	#12,d0
	blo.s	.r
	lea	TxtNotBad,a0
	cmp.w	#20,d0
	blo.s	.r
	lea	TxtGreatZap,a0
	cmp.w	#27,d0
	blo.s	.r
	lea	TxtGhostMaster,a0
.r:	moveq	#100,d1
	moveq	#C_YELLOW,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	move.w	BHits,d0
	rts

; WinXY: d0 = window 0..11 -> d1 x, d2 y
WinXY:
	move.w	d0,d1
	and.w	#3,d1
	mulu	#64,d1
	add.w	#GW_X0,d1
	move.w	d0,d2
	lsr.w	#2,d2
	mulu	#52,d2
	add.w	#GW_Y0,d2
	rts

;---------------------------------------------------------------------
; 3. MEMORY GHOSTS - repeat the sequence. score = rounds
;---------------------------------------------------------------------
MemoryGhosts:
	moveq	#3,d0
	bsr	NewScreen
	; random sequence of 24
	lea	MemSeq,a0
	moveq	#23,d7
.r:	moveq	#4,d0
	bsr	RandRange
	move.b	d0,(a0)+
	dbf	d7,.r
	clr.w	BRound
	move.w	#-1,MemLit
	bsr	StopMusic
	bsr	FadeIn
.round:	; WATCH...
	lea	TxtWatch,a0
	move.l	a0,MemMsg
	moveq	#40,d0
	bsr	MemFrames
	moveq	#0,d6
.show:	lea	MemSeq,a0
	move.b	(a0,d6.w),d0
	ext.w	d0
	move.w	d0,MemLit
	add.w	#SFX_NOTE0,d0
	bsr	PlaySfx
	move.w	BRound,d0
	neg.w	d0
	add.w	#30,d0
	cmp.w	#12,d0
	bge.s	.t
	moveq	#12,d0
.t:	bsr	MemFrames
	move.w	#-1,MemLit
	moveq	#8,d0
	bsr	MemFrames
	addq.w	#1,d6
	cmp.w	BRound,d6
	ble.s	.show
	; YOUR TURN
	lea	TxtYourTurn,a0
	move.l	a0,MemMsg
	moveq	#0,d6
.input:	moveq	#1,d0
	bsr	MemFrames
	bsr	GetKey
	move.w	JoyNew,d1
	moveq	#-1,d0
	btst	#J_UP,d1
	beq.s	.i1
	moveq	#0,d0
.i1:	btst	#J_RIGHT,d1
	beq.s	.i2
	moveq	#1,d0
.i2:	btst	#J_DOWN,d1
	beq.s	.i3
	moveq	#2,d0
.i3:	btst	#J_LEFT,d1
	beq.s	.i4
	moveq	#3,d0
.i4:	tst.w	d0
	bmi.s	.input
	move.w	d0,MemLit
	move.w	d0,d5
	add.w	#SFX_NOTE0,d0
	bsr	PlaySfx
	moveq	#12,d0
	bsr	MemFrames
	move.w	#-1,MemLit
	lea	MemSeq,a0
	move.b	(a0,d6.w),d0
	ext.w	d0
	cmp.w	d0,d5
	bne.s	.wrong
	addq.w	#1,d6
	cmp.w	BRound,d6
	ble.s	.input
	; round complete
	addq.w	#1,BRound
	cmp.w	#24,BRound
	beq.s	.perfect
	moveq	#20,d0
	bsr	MemFrames
	bra	.round
.wrong:	moveq	#SFX_BUZZ,d0
	bsr	PlaySfx
	bsr	ClearBoth
	lea	TxtWrong,a0
	bsr	CopyStr
	lea	TmpStr+16,a0
	move.w	BRound,d0
	moveq	#2,d1
	bsr	PutNumW
	bra.s	.res
.perfect:
	bsr	ClearBoth
	lea	TxtPerfect,a0
	bsr	CopyStr
.res:	lea	TmpStr,a0
	moveq	#90,d1
	moveq	#C_YELLOW,d2
	bsr	PrintCentreBoth
	move.w	BRound,d0
	rts

; MemFrames: run d0 frames of the memory screen
MemFrames:
	movem.l	d0-d7/a0-a2,-(sp)
	move.w	d0,d7
.f:	bsr	ClearDirty
	moveq	#3,d6
.g:	lea	MemPos,a0
	move.w	d6,d0
	lsl.w	#2,d0
	move.w	(a0,d0.w),d1
	move.w	2(a0,d0.w),d2
	lea	MemBobs,a0
	move.w	d6,d0
	add.w	d0,d0
	move.w	(a0,d0.w),d0
	cmp.w	MemLit,d6
	bne.s	.d
	; lit: sparkle ring and lifted ghost
	movem.l	d0-d2,-(sp)
	move.w	#BOB_SPARK3,d0
	subq.w	#1,d1
	subq.w	#2,d2
	bsr	DrawBob
	movem.l	(sp)+,d0-d2
	subq.w	#4,d2
.d:	bsr	DrawBob
	dbf	d6,.g
	lea	TxtMemHud,a0
	bsr	CopyStr
	lea	TmpStr+6,a0
	move.w	BRound,d0
	moveq	#2,d1
	bsr	PutNumW
	lea	TmpStr+15,a0
	move.w	BEST_BASE+4,d0
	bsr	PutNumW
	lea	TxtMemoryGhosts,a0
	bsr	BonusHeader
	move.l	MemMsg,a0
	move.w	#200,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBack
	bsr	Frame
	subq.w	#1,d7
	bgt	.f
	movem.l	(sp)+,d0-d7/a0-a2
	rts

;---------------------------------------------------------------------
; 4. GHOST INVADERS
;---------------------------------------------------------------------
INV_COLS	equ	6
INV_ROWS	equ	4
GhostInvaders:
	moveq	#3,d0
	bsr	NewScreen
	bsr	ResetLevel
	clr.w	BScore
	move.w	#1,BWave
	move.w	#3,BLives
	lea	SongBoss,a0
	bsr	PlaySong
	bsr	FadeIn
.wave:	; set up formation
	lea	InvAlive,a0
	moveq	#INV_COLS*INV_ROWS-1,d0
.a:	st	(a0)+
	dbf	d0,.a
	move.w	#INV_COLS*INV_ROWS,InvLeft
	move.w	#40,InvX
	move.w	#28,InvY
	move.w	#1,InvDir
	clr.w	BoltY
	clr.w	PDead
.loop:	bsr	ClearDirty
	bsr	GetKey
	; player
	move.w	Joy,d2
	btst	#J_LEFT,d2
	beq.s	.nl
	subq.w	#3,PX
	bpl.s	.nl
	clr.w	PX
.nl:	btst	#J_RIGHT,d2
	beq.s	.nr
	addq.w	#3,PX
	cmp.w	#296,PX
	ble.s	.nr
	move.w	#296,PX
.nr:	tst.w	PDead
	beq.s	.pd
	subq.w	#1,PDead
.pd:	; fire bolt
	btst	#J_FIRE,d2
	beq.s	.nf
	tst.w	BoltY
	bne.s	.nf
	move.w	PX,d0
	add.w	#GUN_DX-2,d0
	move.w	d0,BoltX
	move.w	#PLAYER_Y-4,BoltY
	moveq	#SFX_SHOOT,d0
	bsr	PlaySfx
.nf:	tst.w	BoltY
	beq.s	.nb
	subq.w	#6,BoltY
	cmp.w	#20,BoltY
	bgt.s	.nb
	clr.w	BoltY
.nb:	; formation movement
	move.w	InvLeft,d0
	lsr.w	#2,d0
	add.w	#2,d0				; frames per step (fewer ghosts = faster)
	sub.w	BWave,d0
	cmp.w	#1,d0
	bge.s	.sp
	moveq	#1,d0
.sp:	addq.w	#1,InvTick
	cmp.w	InvTick,d0
	bgt.s	.nomove
	clr.w	InvTick
	move.w	InvDir,d0
	add.w	d0,d0
	add.w	d0,InvX
	bsr	InvBounds			; d0 = min x, d1 = max x of live ghosts
	cmp.w	#4,d0
	blt.s	.turn
	cmp.w	#300,d1
	ble.s	.nomove
.turn:	neg.w	InvDir
	addq.w	#6,InvY
	move.w	InvDir,d0
	add.w	d0,d0
	add.w	d0,InvX
.nomove:
	; ghosts shoot slime
	moveq	#60,d0
	bsr	RandRange
	cmp.w	BWave,d0
	bge.s	.noshot
	moveq	#INV_COLS,d0
	bsr	RandRange
	bsr	InvBottom			; d0 col -> d1 = index or -1
	tst.w	d1
	bmi.s	.noshot
	move.w	d1,d0
	bsr	InvXY
	move.w	d1,d0
	addq.w	#8,d0
	move.w	d2,d1
	add.w	#18,d1
	moveq	#0,d2
	moveq	#0,d3
	moveq	#30,d4
	bsr	SpawnSlime
.noshot:
	; bolt vs ghosts
	tst.w	BoltY
	beq.s	.nohit
	lea	InvAlive,a0
	moveq	#INV_COLS*INV_ROWS-1,d7
.h:	tst.b	(a0,d7.w)
	beq.s	.hn
	move.w	d7,d0
	bsr	InvXY
	move.w	BoltX,d0
	sub.w	d1,d0
	cmp.w	#-2,d0
	blt.s	.hn
	cmp.w	#22,d0
	bgt.s	.hn
	move.w	BoltY,d0
	sub.w	d2,d0
	bmi.s	.hn
	cmp.w	#20,d0
	bgt.s	.hn
	clr.b	(a0,d7.w)
	subq.w	#1,InvLeft
	clr.w	BoltY
	moveq	#0,d0
	move.w	d7,d0
	divu	#INV_COLS,d0
	neg.w	d0
	addq.w	#4,d0
	mulu	#10,d0
	add.w	d0,BScore
	moveq	#SFX_CATCH,d0
	bsr	PlaySfx
	bra.s	.nohit
.hn:	dbf	d7,.h
.nohit:	; slime vs player (own check: uses BLives)
	lea	Slimes,a0
	moveq	#MAXSLIME-1,d7
.s:	tst.w	S_ACTIVE(a0)
	beq.s	.sn
	move.w	S_Y16(a0),d1
	add.w	S_VY(a0),d1
	move.w	d1,S_Y16(a0)
	asr.w	#4,d1
	cmp.w	#236,d1
	blt.s	.son
	clr.w	S_ACTIVE(a0)
	bra.s	.sn
.son:	cmp.w	#PLAYER_Y-6,d1
	blt.s	.sn
	move.w	S_X16(a0),d0
	asr.w	#4,d0
	move.w	PX,d2
	addq.w	#1,d2
	cmp.w	d2,d0
	blt.s	.sn
	add.w	#16,d2
	cmp.w	d2,d0
	bgt.s	.sn
	clr.w	S_ACTIVE(a0)
	tst.w	PDead
	bne.s	.sn
	move.w	#90,PDead
	subq.w	#1,BLives
	moveq	#SFX_SLIMED,d0
	bsr	PlaySfx
.sn:	lea	SSIZE(a0),a0
	dbf	d7,.s
	; draw formation
	lea	InvAlive,a2
	moveq	#INV_COLS*INV_ROWS-1,d7
.d:	tst.b	(a2,d7.w)
	beq.s	.dn
	move.w	d7,d0
	bsr	InvXY
	moveq	#0,d0
	move.w	d7,d0
	divu	#INV_COLS,d0
	and.w	#3,d0
	add.w	#BOB_INV0,d0
	bsr	DrawBob
.dn:	dbf	d7,.d
	tst.w	BoltY
	beq.s	.nob
	move.w	#BOB_BOLT,d0
	move.w	BoltX,d1
	move.w	BoltY,d2
	bsr	DrawBob
.nob:	bsr	DrawSlimes
	clr.w	PAnim
	bsr	DrawPlayer
	; header
	lea	TxtGIHud,a0
	bsr	CopyStr
	lea	TmpStr+6,a0
	move.w	BScore,d0
	moveq	#4,d1
	bsr	PutNumW
	lea	TmpStr+17,a0
	move.w	BWave,d0
	moveq	#1,d1
	bsr	PutNumW
	lea	TmpStr+26,a0
	move.w	BLives,d0
	bsr	PutNumW
	lea	TxtGhostInvaders,a0
	bsr	BonusHeader
	bsr	Frame
	; end conditions
	tst.w	BLives
	ble.s	.over
	tst.w	InvLeft
	beq.s	.next
	move.w	InvY,d0
	add.w	#INV_ROWS*22,d0
	cmp.w	#PLAYER_Y,d0
	bge.s	.over
	bra	.loop
.next:	addq.w	#1,BWave
	add.w	#100,BScore
	moveq	#SFX_LIFE,d0
	bsr	PlaySfx
	lea	Slimes,a0
	move.w	#(SSIZE*MAXSLIME/2)-1,d0
.cs:	clr.w	(a0)+
	dbf	d0,.cs
	bra	.wave
.over:	bsr	ClearBoth
	lea	TxtGameOver,a0
	moveq	#70,d1
	moveq	#C_MAGENTA,d2
	move.l	BackBuf,a1
	bsr	PrintBigCentre
	move.l	FrontBuf,a1
	bsr	PrintBigCentre
	lea	TxtGIHud,a0
	bsr	CopyStr
	lea	TmpStr+6,a0
	move.w	BScore,d0
	moveq	#4,d1
	bsr	PutNumW
	lea	TmpStr+17,a0
	move.w	BWave,d0
	moveq	#1,d1
	bsr	PutNumW
	lea	TmpStr+26,a0
	moveq	#0,d0
	bsr	PutNumW
	lea	TmpStr,a0
	move.w	#110,d1
	moveq	#C_WHITE,d2
	bsr	PrintCentreBoth
	move.w	BScore,d0
	rts

; InvXY: d0 = index -> d1 x, d2 y
InvXY:
	movem.l	d0,-(sp)
	and.l	#$ffff,d0
	divu	#INV_COLS,d0
	move.w	d0,d2				; row
	swap	d0				; col
	move.w	d0,d1
	mulu	#36,d1
	add.w	InvX,d1
	mulu	#22,d2
	add.w	InvY,d2
	movem.l	(sp)+,d0
	rts

; InvBounds -> d0 = leftmost x, d1 = rightmost x+24 of live ghosts
InvBounds:
	movem.l	d2-d5/a0,-(sp)
	move.w	#999,d4
	move.w	#-999,d5
	lea	InvAlive,a0
	moveq	#INV_COLS*INV_ROWS-1,d3
.l:	tst.b	(a0,d3.w)
	beq.s	.n
	move.w	d3,d0
	bsr	InvXY
	cmp.w	d4,d1
	bge.s	.a
	move.w	d1,d4
.a:	add.w	#24,d1
	cmp.w	d5,d1
	ble.s	.n
	move.w	d1,d5
.n:	dbf	d3,.l
	move.w	d4,d0
	move.w	d5,d1
	movem.l	(sp)+,d2-d5/a0
	rts

; InvBottom: d0 = column -> d1 = index of the lowest live ghost or -1
InvBottom:
	movem.l	d0/d2/a0,-(sp)
	lea	InvAlive,a0
	move.w	d0,d1
	add.w	#INV_COLS*(INV_ROWS-1),d1
	moveq	#INV_ROWS-1,d2
.l:	tst.b	(a0,d1.w)
	bne.s	.x
	sub.w	#INV_COLS,d1
	dbf	d2,.l
	moveq	#-1,d1
.x:	movem.l	(sp)+,d0/d2/a0
	rts

